INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C1','sci',5,2,'u1',1,'한 가지 물질과 섞여 있는 물질 — 우리 주변 물질에는 한 가지 물질로만 이루어진 것(금관의 금, 못의 철, 얼음의 물, 산소)과 두 가지 이상의 물질이 섞여 있는 것(소금물 — 소금과 물, 공기 — 질소·산소·이산화 탄소 등, 탄산음료 — 물과 이산화 탄소 등, 바닷가 흙, 유성 물감 — 기름과 색소 등)이 있음 · 겉모습(차가움·딱딱함·색)이 아니라 무엇으로 되어 있는지로 나눔 · 눈에 보이지 않게 섞인 것도 섞여 있는 물질',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C2','sci',5,2,'u1',2,'혼합물의 뜻 — 두 가지 이상의 물질이 각각의 성질이 변하지 않은 채 섞여 있는 것 · 소금물 속 소금은 여전히 짜고 설탕물 속 설탕은 여전히 닮 · 성질이 그대로라서 그 차이를 이용해 나눌 수 있음',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C3','sci',5,2,'u1',2,'혼합물에서 얻는 물질과 쓰임 — 바닷물 → 소금(음식)·마실 물, 사탕수수 → 설탕(사탕·시럽), 금광석 → 금, 고무나무 → 천연고무액(지우개), 목화 → 목화솜(옷·이불), 콩 → 콩 단백질(두부·콩고기) · 얻은 물질은 그대로 쓰거나 가공해 필요한 물건을 만듦 · 병원에서는 혈액을 여러 성분으로 나누어 치료·연구에 씀',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C4','sci',5,2,'u1',2,'혼합물을 분리하는 까닭 — 여러 물질이 섞여 있으므로 나누어야 필요한 물질을 얻어 쓸 수 있음 · 분리배출도 물질별로 나누어 다시 얻어 쓰려는 것과 닮음 · 옛날 키·풍구로 곡식과 쭉정이·티끌을 나눈 것도 같은 까닭 · 「주변 물질이 모두 혼합물이라서」는 옳지 않음(한 가지 물질도 있음)',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C5','sci',5,2,'u1',3,'모래와 자갈의 관찰 — 모양과 색깔은 둘 다 여러 가지라 그것으로는 나누기 어렵고, 가장 뚜렷한 차이는 알갱이의 크기(모래가 자갈보다 작음) · 체로 나눈 모래·자갈도 여러 알갱이가 섞여 있어 여전히 섞여 있는 물질',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C6','sci',5,2,'u1',3,'체로 고체 혼합물 분리하기 — 알갱이의 크기가 다른 고체 혼합물은 크기 차이를 이용해 체로 나눔 · 체의 눈보다 작은 알갱이는 빠져나가고 큰 알갱이는 체에 남음 · 체의 눈은 작은 알갱이보다 크고 큰 알갱이보다 작아야 함(밀가루 체처럼 너무 촘촘하면 모두 남고, 너무 크면 모두 빠져나감) · 손으로 고르는 것보다 양이 많아도 한 번에 빠르게 나눔',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C7','sci',5,2,'u1',3,'생활 속 체와 여러 번 거르기 — 강에서 조개 잡기(모래는 빠지고 조개가 남음), 해변 쓰레기 수거 장비(모래는 돌아가고 쓰레기가 남음), 마스크(공기는 지나가고 황사·먼지는 걸림) · 세 가지 이상이 섞이면 눈 크기가 다른 체를 차례로 써서 한 번에 하나씩 나눔(좁쌀 < 쌀 < 팥이면 체 두 개)',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C8','sci',5,2,'u1',4,'섞이지 않는 물과 기름 — 물과 기름은 골고루 섞이지 않고 층을 이루어 기름이 위쪽, 물이 아래쪽에 있음 · 기름을 먼저 붓고 물을 부어도, 세게 흔들어 잠깐 뿌옇게 되어도 시간이 지나면 다시 층을 이룸 · 섞이지 않는 까닭은 이 단원에서 다루지 않음',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C9','sci',5,2,'u1',4,'스포이트로 분리하기 — 위층의 기름을 스포이트로 뽑아 빈 그릇에 옮기기를 되풀이해 물과 기름을 각각 얻음 · 경계면 가까이는 물이 섞여 들지 않게 조심하고 따로 모음 · 뽑아 옮긴 기름은 다시 쓸 수 있음',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C10','sci',5,2,'u1',4,'흡착포와 두 도구 견주기 — 흡착포는 기름을 흡수하는 종이로, 물 위에 뜬 기름에 대면 기름만 빨아들여 물을 깨끗이 남김(얇게 넓게 퍼진 기름에 편함, 흡수한 기름은 다시 쓰기 어려움) · 바다 기름 유출 때 흡착포를 쓰고 울타리를 침 · 상황에 맞는 도구를 고름 · 마블링·국 위 기름 떠내기도 위에 뜨는 성질을 이용',ARRAY['[6과05-01] 알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C11','sci',5,2,'u1',5,'소금과 모래의 성질 차이 — 소금과 모래는 알갱이 크기가 비슷해 체로 나누기 어려움 · 소금은 물에 녹고 모래는 물에 녹지 않음 → 이 차이를 이용해 나눔 · 물에 녹은 소금은 없어진 것이 아니라 물속에 섞여 있음',ARRAY['[6과05-02] 물에 용해되는 성질을 이용하여 고체 혼합물을 분리하고, 물을 증발시켜 물에 용해된 고체 물질을 분리할 수 있다.']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C12','sci',5,2,'u1',5,'거름 — 물에 녹는 물질과 녹지 않는 물질을 걸러서 나누는 방법 · 소금과 모래를 물에 녹여 저은 뒤 거름 장치로 거르면 모래는 거름종이 위에 남고 소금물은 빠져나감 · 거름종이를 접어 깔때기에 물을 묻혀 붙이고, 유리 막대를 따라 천천히 붓고, 깔때기 끝을 비커 옆면에 댐',ARRAY['[6과05-02] 물에 용해되는 성질을 이용하여 고체 혼합물을 분리하고, 물을 증발시켜 물에 용해된 고체 물질을 분리할 수 있다.']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C13','sci',5,2,'u1',5,'증발과 안전 — 거름종이를 빠져나간 소금물을 증발 접시에 담아 가열하면 물이 증발하고 녹아 있던 소금이 하얗게 남음 · 차례는 물에 녹이기 → 거름 → 증발 · 약하게 가열하고 보안경·면장갑을 끼며 증발 접시는 집게로 옮기고, 전원을 끈 가열판도 뜨거우니 만지지 않음',ARRAY['[6과05-02] 물에 용해되는 성질을 이용하여 고체 혼합물을 분리하고, 물을 증발시켜 물에 용해된 고체 물질을 분리할 수 있다.']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C14','sci',5,2,'u1',5,'생활 속 거름과 증발 — 장 담그기에서 천으로 걸러 간장을 얻음(거름) · 치즈를 만들 때 천으로 걸러 냄(거름) · 염전에서 바닷물을 가두어 햇빛과 바람으로 물을 증발시켜 소금을 얻음(증발 장치를 크게 만든 것과 같음) · 바닷가 신발에 남은 하얀 알갱이도 물이 증발하고 남은 소금',ARRAY['[6과05-02] 물에 용해되는 성질을 이용하여 고체 혼합물을 분리하고, 물을 증발시켜 물에 용해된 고체 물질을 분리할 수 있다.']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C15','sci',5,2,'u1',6,'해수 담수화 장치 — 바닷물에는 소금 등이 섞여 있어 그대로 마실 수 없음 · 해수 담수화 장치는 바닷물에서 소금 등을 나누어 마실 물과 생활용수를 만듦 · 가뭄이 들거나 바다로 둘러싸인 섬 마을처럼 물이 모자란 곳에 꼭 필요함',ARRAY['[6과05-03] 지속가능한 삶을 위한 과학 기술 사례 중 혼합물의 분리를 이용한 장치를 조사하여 공유할 수 있다.']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C16','sci',5,2,'u1',6,'혼합물의 분리를 이용한 장치와 지속가능한 삶 — 정수 장치(여러 겹 거름망으로 물속 오염 물질을 거름), 하수 처리 시설(오염된 물을 나누어 다시 씀), 공기 정화 장치(필터로 공기 속 먼지를 거름), 인공지능 폐기물 선별 장치(카메라로 보고 플라스틱·종이·유리를 골라 냄) · 장치는 물질의 성질을 바꾸지 않고 나눔 · 깨끗한 물과 공기로 건강을 지키고 자원을 다시 써 지속가능한 삶을 도움 · 실험실의 체·거름·증발이 큰 장치로 쓰임',ARRAY['[6과05-03] 지속가능한 삶을 위한 과학 기술 사례 중 혼합물의 분리를 이용한 장치를 조사하여 공유할 수 있다.']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C17','sci',5,2,'u1',6,'장치 조사 보고서와 출처 — 장치를 하나 골라 쓰임·개발 배경(어떤 상황에서 왜 만들었나)·분리 원리·효과를 조사함 · 장치 고르기 → 조사하기 → 보고서 쓰기 → 공유하기 · 믿을 수 있는 자료를 쓰고 출처를 밝히며 내 말로 정리함',ARRAY['[6과05-03] 지속가능한 삶을 위한 과학 기술 사례 중 혼합물의 분리를 이용한 장치를 조사하여 공유할 수 있다.']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C18','sci',5,2,'u1',7,'분리 장치 소개 포스터 — 계획하기(장치·역할 정하기) → 해 보기(디자인 앱으로 만들기) → 나누기(공유하고 댓글 달기) · 어떤 방법으로 무엇을 무엇에서 나누는지가 가장 크게 드러나야 함 · 장치 이름·분리 방법·개발 배경·출처를 넣고 개인 정보는 넣지 않음 · 보는 사람에 맞게 쉬운 말과 그림 화살표를 씀',ARRAY['[6과05-03] 지속가능한 삶을 위한 과학 기술 사례 중 혼합물의 분리를 이용한 장치를 조사하여 공유할 수 있다.']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C19','sci',5,2,'u1',7,'공유와 댓글 예절 — 다른 모둠 포스터에 새로 알게 된 점·궁금한 점·구체적인 칭찬과 고칠 방향을 바르고 고운 말로 씀 · 「별로야」처럼 까닭 없는 말, 친구 개인 정보는 쓰지 않음 · 모둠원이 역할을 나누어 모두 참여함',ARRAY['[6과05-03] 지속가능한 삶을 위한 과학 기술 사례 중 혼합물의 분리를 이용한 장치를 조사하여 공유할 수 있다.']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C20','sci',5,2,'u1',8,'새활용 — 버려지는 물건에 아이디어나 디자인을 더해 새로운 가치를 만드는 것(페트병 뚜껑 벽화, 안 쓰는 천으로 만든 가방, 플라스틱 병 조명) · 재활용은 녹이거나 부수어 변형해 다시 쓰는 것이고, 새활용은 에너지와 자원을 더 아낌 · 쓸 수 있는 재료를 먼저 나누어 골라 모음 · 업사이클링 아티스트는 버린 물건을 작품으로 바꿈',ARRAY['[6과05-03] 지속가능한 삶을 위한 과학 기술 사례 중 혼합물의 분리를 이용한 장치를 조사하여 공유할 수 있다.']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u1-C21','sci',5,2,'u1',8,'성질에 맞는 분리 방법 고르기 — 혼합물은 섞인 물질의 서로 다른 성질을 이용해 나눔: 알갱이 크기 차이 → 체 · 섞이지 않고 위에 뜸 → 스포이트·흡착포 · 물에 녹는지 → 거름 → 증발 · 도구보다 성질을 먼저 살피고, 여러 가지가 섞이면 방법을 알맞은 차례로 이어 씀',ARRAY['[6과05-02] 물에 용해되는 성질을 이용하여 고체 혼합물을 분리하고, 물을 증발시켜 물에 용해된 고체 물질을 분리할 수 있다.']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X01','sci',5,'u1',ARRAY['SC5-2-u1-C1']::text[],'눈에 보이지 않게 섞인 것을 한 가지 물질로 여긴다(공기·탄산음료·소금물을 한 가지라고)','보이지 않아도 섞여 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X02','sci',5,'u1',ARRAY['SC5-2-u1-C1']::text[],'무엇으로 되어 있는지가 아니라 겉모습(차가움·딱딱함·색)으로 한 가지 물질과 섞인 물질을 나눈다','무엇으로 되어 있나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X03','sci',5,'u1',ARRAY['SC5-2-u1-C2']::text[],'물질이 섞이면 새 물질이 되어 성질이 바뀐다고 여긴다','성질이 그대로인 채 섞여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X04','sci',5,'u1',ARRAY['SC5-2-u1-C2','SC5-2-u1-C11']::text[],'물에 녹은 물질은 없어졌다고 여긴다(녹은 소금·설탕은 사라졌다고)','녹아서 보이지 않을 뿐 섞여 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X05','sci',5,'u1',ARRAY['SC5-2-u1-C3']::text[],'혼합물과 그 혼합물에서 얻는 물질을 바꾸어 짝짓는다(고무나무에서 금, 사탕수수에서 소금)','바닷물 소금 · 사탕수수 설탕 · 고무나무 천연고무액') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X06','sci',5,'u1',ARRAY['SC5-2-u1-C4']::text[],'혼합물을 분리하는 까닭을 엉뚱하게 든다(무겁게·예쁘게·양을 늘리려고)','필요한 물질을 얻으려고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X07','sci',5,'u1',ARRAY['SC5-2-u1-C1','SC5-2-u1-C4']::text[],'우리 주변 물질은 모두 혼합물이라고 여긴다','한 가지 물질도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X08','sci',5,'u1',ARRAY['SC5-2-u1-C5']::text[],'모래와 자갈을 색깔이나 모양으로 나눌 수 있다고 여긴다','색·모양은 둘 다 여러 가지 · 크기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X09','sci',5,'u1',ARRAY['SC5-2-u1-C6','SC5-2-u1-C7']::text[],'체의 눈 크기 조건을 놓친다(눈이 작을수록, 또는 클수록 좋다고)','작은 알갱이 < 눈 < 큰 알갱이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X10','sci',5,'u1',ARRAY['SC5-2-u1-C6']::text[],'체에 남는 것과 빠져나가는 것을 거꾸로 안다','작으면 빠지고 크면 남아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X11','sci',5,'u1',ARRAY['SC5-2-u1-C5']::text[],'체로 나누어 얻은 모래나 자갈은 이제 한 가지 물질이라고 여긴다','모래도 여러 알갱이가 섞여 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X12','sci',5,'u1',ARRAY['SC5-2-u1-C7']::text[],'체 하나로 세 가지 이상을 한 번에 나눌 수 있다고 여긴다','한 번에 하나씩 · 체를 차례로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X13','sci',5,'u1',ARRAY['SC5-2-u1-C8']::text[],'물과 기름을 세게 흔들거나 저으면 골고루 섞인다고 여긴다','잠깐 뿌옇다가 다시 층') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X14','sci',5,'u1',ARRAY['SC5-2-u1-C8']::text[],'물과 기름의 층을 거꾸로 안다(물이 위, 기름이 아래)','기름 위 · 물 아래') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X15','sci',5,'u1',ARRAY['SC5-2-u1-C9']::text[],'스포이트 쓰는 법을 놓친다(아래층부터 깊이 넣거나 경계면을 신경 쓰지 않음)','위층부터 · 경계면 조심') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X16','sci',5,'u1',ARRAY['SC5-2-u1-C10']::text[],'스포이트와 흡착포의 좋은 점·아쉬운 점을 거꾸로 안다(흡착포로 얻은 기름을 바로 다시 쓴다고)','스포이트 다시 씀 · 흡착포 얇은 기름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X17','sci',5,'u1',ARRAY['SC5-2-u1-C8','SC5-2-u1-C10']::text[],'섞이지 않는 액체 혼합물에 맞지 않는 방법(체·데우기 등)을 고른다','위에 뜬 쪽을 걷어 내요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X18','sci',5,'u1',ARRAY['SC5-2-u1-C11']::text[],'소금과 모래를 체로 나눌 수 있다고 여긴다','크기가 비슷해요 · 물에 녹는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X19','sci',5,'u1',ARRAY['SC5-2-u1-C12']::text[],'거름종이 위에 소금이 남는다고 여기거나, 빠져나간 액체에 소금이 없다고 여긴다','모래는 위 · 소금은 물과 함께 아래') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X20','sci',5,'u1',ARRAY['SC5-2-u1-C12','SC5-2-u1-C13']::text[],'거름과 증발의 차례나 쓰임을 바꾸어 안다','녹이기 → 거름 → 증발') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X21','sci',5,'u1',ARRAY['SC5-2-u1-C13']::text[],'가열 실험의 안전 수칙을 놓친다(세게 가열, 맨손, 끈 가열판 만지기)','약하게 · 집게 · 끈 뒤에도 뜨거움') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X22','sci',5,'u1',ARRAY['SC5-2-u1-C14']::text[],'생활 속 거름·증발의 예를 바꾸어 짝짓는다(염전을 거름, 간장 거르기를 증발로)','천으로 거르기 · 햇빛과 바람으로 증발') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X23','sci',5,'u1',ARRAY['SC5-2-u1-C12']::text[],'거름 장치를 꾸미는 법을 놓친다(거름종이를 붙이지 않거나 한꺼번에 쏟음)','물 묻혀 붙이기 · 유리 막대 · 옆면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X24','sci',5,'u1',ARRAY['SC5-2-u1-C15']::text[],'해수 담수화 장치가 하는 일을 잘못 안다(소금을 넣는다고, 바닷물을 그대로 마셔도 된다고)','바닷물에서 소금 등을 나눠요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X25','sci',5,'u1',ARRAY['SC5-2-u1-C16']::text[],'혼합물의 분리는 실험실에서만 쓰는 방법이라고 여긴다','정수기·마스크·공기 청정기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X26','sci',5,'u1',ARRAY['SC5-2-u1-C16']::text[],'분리 장치와 그 장치가 나누는 것을 바꾸어 짝짓는다(공기 청정기가 물을, 정수 장치가 공기를)','무엇에서 무엇을 나누나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X27','sci',5,'u1',ARRAY['SC5-2-u1-C16']::text[],'분리 장치가 물질의 성질을 바꾼다고 여긴다','성질은 그대로 나누기만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X28','sci',5,'u1',ARRAY['SC5-2-u1-C17']::text[],'조사 자료를 출처 없이 그대로 옮기거나 믿을 수 있는지 따지지 않는다','출처 · 내 말로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X29','sci',5,'u1',ARRAY['SC5-2-u1-C18']::text[],'포스터에 이름·사진·꾸미기만 크게 넣고 분리 방법을 드러내지 않는다','무엇을 어떻게 나누는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X30','sci',5,'u1',ARRAY['SC5-2-u1-C19']::text[],'까닭 없는 말·흉보는 말·개인 정보를 댓글이나 포스터에 쓴다','새로 안 점 · 바르고 고운 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X31','sci',5,'u1',ARRAY['SC5-2-u1-C20']::text[],'재활용과 새활용을 같은 것으로 안다','녹이고 부수기 ↔ 아이디어 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X32','sci',5,'u1',ARRAY['SC5-2-u1-C20']::text[],'새활용을 낡은 물건을 그대로 쓰는 것으로 여기거나 재료를 나누어 모으는 단계를 빠뜨린다','나누어 모으고 새 가치를') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X33','sci',5,'u1',ARRAY['SC5-2-u1-C21']::text[],'섞인 물질의 성질을 따지지 않고 맞지 않는 방법이나 성질(자석·색깔 등)을 고른다','성질 먼저 → 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X34','sci',5,'u1',ARRAY['SC5-2-u1-C13','SC5-2-u1-C21']::text[],'여러 방법을 이어 쓸 때 차례를 놓친다(증발을 맨 처음에 함)','크기 → 녹이기·거름 → 증발') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u1-X35','sci',5,'u1',ARRAY['SC5-2-u1-C16']::text[],'분리 장치의 좋은 점을 편리함 하나로만 보아 건강·환경·자원의 가치를 놓친다','깨끗한 물·공기 · 자원 다시 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_basic#1','sci',5,2,'u1','L01','g5_2_sci_u1_L01_basic','lesson_basic','SC5-2-u1-C1',1,'mc','auto','두 가지 이상의 물질이 섞여 있는 것은 어느 것인가요?',ARRAY['SC5-2-u1-X02','SC5-2-u1-X01']::text[],false,'{"seq":1,"concept":"SC5-2-u1-C1","difficulty":1,"kind":"mc","stem":"두 가지 이상의 물질이 섞여 있는 것은 어느 것인가요?","options":[{"t":"소금물","correct":true},{"t":"금관","mis":"SC5-2-u1-X02"},{"t":"못","mis":"SC5-2-u1-X02"},{"t":"산소","mis":"SC5-2-u1-X01"}],"explanation":["소금물에는 소금이 있어요.","물도 있어요.","두 가지가 섞였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_basic#2','sci',5,2,'u1','L01','g5_2_sci_u1_L01_basic','lesson_basic','SC5-2-u1-C1',1,'mc','auto','한 가지 물질로만 이루어진 것은 어느 것인가요?',ARRAY['SC5-2-u1-X01','SC5-2-u1-X02']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C1","difficulty":1,"kind":"mc","stem":"한 가지 물질로만 이루어진 것은 어느 것인가요?","options":[{"t":"금관","correct":true},{"t":"공기","mis":"SC5-2-u1-X01"},{"t":"탄산음료","mis":"SC5-2-u1-X01"},{"t":"바닷가 흙","mis":"SC5-2-u1-X02"}],"explanation":["금관은 금으로 만들어요.","금 한 가지예요.","한 가지 물질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_basic#3','sci',5,2,'u1','L01','g5_2_sci_u1_L01_basic','lesson_basic','SC5-2-u1-C1',1,'ox','auto','얼음은 물이 언 것이라 한 가지 물질이에요.',ARRAY['SC5-2-u1-X02']::text[],false,'{"seq":3,"concept":"SC5-2-u1-C1","difficulty":1,"kind":"ox","stem":"얼음은 물이 언 것이라 한 가지 물질이에요.","answer":"O","reason_options":[{"t":"물 한 가지로만 되어 있기 때문에","correct":true},{"t":"차갑고 딱딱해서 섞여 있는 물질이기 때문에","mis":"SC5-2-u1-X02"}],"mis":"SC5-2-u1-X02","explanation":["얼음은 물이 언 거예요.","물 한 가지예요.","모양은 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_basic#4','sci',5,2,'u1','L01','g5_2_sci_u1_L01_basic','lesson_basic','SC5-2-u1-C1',1,'sa','auto','말판 놀이에서 섞여 있는 물질 칸을 모두 색칠하면 나타나는 세 글자 낱말은 무엇인가요?','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u1-C1","difficulty":1,"kind":"sa","stem":"말판 놀이에서 섞여 있는 물질 칸을 모두 색칠하면 나타나는 세 글자 낱말은 무엇인가요?","answer":["혼합물"],"explanation":["섞인 칸을 색칠했어요.","세 글자 낱말이에요.","혼합물이에요."],"mis":"SC5-2-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_basic#5','sci',5,2,'u1','L01','g5_2_sci_u1_L01_basic','lesson_basic','SC5-2-u1-C1',2,'mc','auto','공기에 섞여 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X01','SC5-2-u1-X02']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C1","difficulty":2,"kind":"mc","stem":"공기에 섞여 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"질소, 산소, 이산화 탄소 등 여러 가지 기체","correct":true},{"t":"산소 한 가지뿐","mis":"SC5-2-u1-X01"},{"t":"아무것도 섞여 있지 않다","mis":"SC5-2-u1-X01"},{"t":"소금과 물","mis":"SC5-2-u1-X02"}],"explanation":["숨 쉴 때 산소를 들이마셔요.","내쉴 때 이산화 탄소가 나와요.","여러 기체가 섞였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_basic#6','sci',5,2,'u1','L01','g5_2_sci_u1_L01_basic','lesson_basic','SC5-2-u1-C1',2,'mc','auto','유성 물감에 섞여 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X02']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C1","difficulty":2,"kind":"mc","stem":"유성 물감에 섞여 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"기름과 색소 등","correct":true},{"t":"물과 소금","mis":"SC5-2-u1-X02"},{"t":"모래와 자갈","mis":"SC5-2-u1-X02"},{"t":"금과 철","mis":"SC5-2-u1-X02"}],"explanation":["유성 물감은 기름 성분이에요.","색을 내는 것도 있어요.","기름과 색소 등이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_basic#7','sci',5,2,'u1','L01','g5_2_sci_u1_L01_basic','lesson_basic','SC5-2-u1-C1',2,'mc','auto','말판 놀이 칸 카드에서 섞여 있는 물질만 모은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X02','SC5-2-u1-X01']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C1","difficulty":2,"kind":"mc","stem":"말판 놀이 칸 카드에서 섞여 있는 물질만 모은 것은 어느 것인가요?","options":[{"t":"㉡ ㉣ ㉥ ㉦","correct":true},{"t":"㉠ ㉢ ㉤ ㉧","mis":"SC5-2-u1-X02"},{"t":"㉡ ㉤ ㉥ ㉦","mis":"SC5-2-u1-X02"},{"t":"㉠ ㉡ ㉣ ㉧","mis":"SC5-2-u1-X01"}],"explanation":["소금물·공기는 섞였어요.","탄산음료·바닷가 흙도요.","얼음·금관은 한 가지예요."],"asset":{"type":"passage","lines":["㉠ 금관   ㉡ 소금물   ㉢ 못   ㉣ 공기","㉤ 얼음   ㉥ 탄산음료   ㉦ 바닷가 흙   ㉧ 산소"],"title":"말판 놀이 칸 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_basic#8','sci',5,2,'u1','L01','g5_2_sci_u1_L01_basic','lesson_basic','SC5-2-u1-C1',2,'ox','auto','탄산음료는 컵에 따르면 한 가지 색이니 한 가지 물질이에요.',ARRAY['SC5-2-u1-X01']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C1","difficulty":2,"kind":"ox","stem":"탄산음료는 컵에 따르면 한 가지 색이니 한 가지 물질이에요.","answer":"X","reason_options":[{"t":"물과 이산화 탄소 등이 섞여 있어 거품이 올라오기 때문에","correct":true},{"t":"컵에서 한 가지 액체로만 보이기 때문에","mis":"SC5-2-u1-X01"}],"mis":"SC5-2-u1-X01","explanation":["거품이 올라와요.","물에 기체가 섞였어요.","섞여 있는 물질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_basic#9','sci',5,2,'u1','L01','g5_2_sci_u1_L01_basic','lesson_basic','SC5-2-u1-C1',2,'mc','auto','물질을 한 가지 물질과 섞여 있는 물질로 나눌 때 따져야 할 것은 어느 것인가요?',ARRAY['SC5-2-u1-X02']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C1","difficulty":2,"kind":"mc","stem":"물질을 한 가지 물질과 섞여 있는 물질로 나눌 때 따져야 할 것은 어느 것인가요?","options":[{"t":"무엇으로 되어 있는지","correct":true},{"t":"차가운지 따뜻한지","mis":"SC5-2-u1-X02"},{"t":"딱딱한지 물렁한지","mis":"SC5-2-u1-X02"},{"t":"색깔이 예쁜지","mis":"SC5-2-u1-X02"}],"explanation":["모양으로는 알 수 없어요.","무엇으로 되었는지 봐요.","한 가지인지 여럿인지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_basic#10','sci',5,2,'u1','L01','g5_2_sci_u1_L01_basic','lesson_basic','SC5-2-u1-C1',3,'error','auto','말판 놀이를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X01','SC5-2-u1-X02']::text[],false,'{"seq":10,"concept":"SC5-2-u1-C1","difficulty":3,"kind":"error","stem":"말판 놀이를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「공기는 눈에 안 보이니까 한 가지 물질이야.」","correct":true,"mis_target":"SC5-2-u1-X01"},{"t":"서아 — 「바닷가 흙에는 모래랑 조개껍데기 조각이 섞여 있어.」","mis":"SC5-2-u1-X02"},{"t":"도윤 — 「못은 철 한 가지로 되어 있어.」","mis":"SC5-2-u1-X02"}],"explanation":["공기에는 여러 기체가 있어요.","안 보여도 섞였어요.","하준의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_challenge#1','sci',5,2,'u1','L01','g5_2_sci_u1_L01_challenge','lesson_challenge','SC5-2-u1-C1',2,'match','auto','섞여 있는 물질과 그 속에 섞인 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u1-C1","difficulty":2,"kind":"match","stem":"섞여 있는 물질과 그 속에 섞인 것을 알맞게 이으세요.","pairs":[{"l":"소금물","r":"소금과 물"},{"l":"공기","r":"질소·산소 등"},{"l":"탄산음료","r":"물과 이산화 탄소 등"},{"l":"유성 물감","r":"기름과 색소 등"}],"mis":"SC5-2-u1-X01","explanation":["소금물은 소금과 물이에요.","공기는 여러 기체예요.","물감은 기름과 색소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_challenge#2','sci',5,2,'u1','L01','g5_2_sci_u1_L01_challenge','lesson_challenge','SC5-2-u1-C1',2,'mc','auto','금관·못·산소·얼음의 공통점은 어느 것인가요?',ARRAY['SC5-2-u1-X02','SC5-2-u1-X01']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C1","difficulty":2,"kind":"mc","stem":"금관·못·산소·얼음의 공통점은 어느 것인가요?","options":[{"t":"한 가지 물질로 이루어져 있다","correct":true},{"t":"모두 섞여 있는 물질이다","mis":"SC5-2-u1-X02"},{"t":"모두 딱딱한 고체이다","mis":"SC5-2-u1-X02"},{"t":"모두 눈에 보이지 않는다","mis":"SC5-2-u1-X01"}],"explanation":["금관은 금이에요.","못은 철, 얼음은 물이에요.","모두 한 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_challenge#3','sci',5,2,'u1','L01','g5_2_sci_u1_L01_challenge','lesson_challenge','SC5-2-u1-C1',3,'mc','auto','설탕을 물에 넣고 저어 설탕물을 만들었어요. 설탕물에 섞여 있는 물질을 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u1-X04','SC5-2-u1-X02','SC5-2-u1-X01']::text[],false,'{"seq":3,"concept":"SC5-2-u1-C1","difficulty":3,"kind":"mc","stem":"설탕을 물에 넣고 저어 설탕물을 만들었어요. 설탕물에 섞여 있는 물질을 바르게 말한 것은 어느 것인가요?","options":[{"t":"설탕과 물 두 가지","correct":true},{"t":"물 한 가지 — 설탕은 녹아서 없어졌다","mis":"SC5-2-u1-X04"},{"t":"설탕 한 가지 — 물은 담는 그릇일 뿐이다","mis":"SC5-2-u1-X02"},{"t":"아무것도 섞이지 않았다","mis":"SC5-2-u1-X01"}],"explanation":["넣은 것을 세어 봐요.","설탕과 물이에요.","녹아도 섞여 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_challenge#4','sci',5,2,'u1','L01','g5_2_sci_u1_L01_challenge','lesson_challenge','SC5-2-u1-C1',3,'mc','auto','탄산음료 병을 열면 거품이 보글보글 올라와요. 이 거품이 알려 주는 것은 어느 것인가요?',ARRAY['SC5-2-u1-X01','SC5-2-u1-X03']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C1","difficulty":3,"kind":"mc","stem":"탄산음료 병을 열면 거품이 보글보글 올라와요. 이 거품이 알려 주는 것은 어느 것인가요?","options":[{"t":"물에 이산화 탄소 등이 섞여 있었다","correct":true},{"t":"병 속이 처음부터 비어 있었다","mis":"SC5-2-u1-X01"},{"t":"음료가 새로운 물질로 바뀌었다","mis":"SC5-2-u1-X03"},{"t":"탄산음료는 한 가지 물질이다","mis":"SC5-2-u1-X01"}],"explanation":["거품은 기체예요.","물속에 섞여 있었어요.","섞여 있는 물질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_challenge#5','sci',5,2,'u1','L01','g5_2_sci_u1_L01_challenge','lesson_challenge','SC5-2-u1-C1',3,'ox','auto','눈으로 보아 한 가지 색이면 한 가지 물질이에요.',ARRAY['SC5-2-u1-X01']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C1","difficulty":3,"kind":"ox","stem":"눈으로 보아 한 가지 색이면 한 가지 물질이에요.","answer":"X","reason_options":[{"t":"소금물·공기처럼 보이지 않게 섞인 물질도 있기 때문에","correct":true},{"t":"섞여 있으면 반드시 눈에 보이기 때문에","mis":"SC5-2-u1-X01"}],"mis":"SC5-2-u1-X01","explanation":["소금물은 투명해요.","그래도 소금이 섞였어요.","색만으로는 몰라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_challenge#6','sci',5,2,'u1','L01','g5_2_sci_u1_L01_challenge','lesson_challenge','SC5-2-u1-C1',3,'error','auto','말판 칸의 물질을 두 갈래로 나누며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X02','SC5-2-u1-X01']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C1","difficulty":3,"kind":"error","stem":"말판 칸의 물질을 두 갈래로 나누며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유나 — 「얼음은 차갑고 딱딱하니까 섞여 있는 물질 쪽이야.」","correct":true,"mis_target":"SC5-2-u1-X02"},{"t":"지호 — 「소금물은 섞여 있는 물질 쪽이야.」","mis":"SC5-2-u1-X01"},{"t":"민서 — 「금관은 금 한 가지라서 한 가지 물질 쪽이야.」","mis":"SC5-2-u1-X02"}],"explanation":["얼음은 물이 언 거예요.","물 한 가지예요.","유나의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_challenge#7','sci',5,2,'u1','L01','g5_2_sci_u1_L01_challenge','lesson_challenge','SC5-2-u1-C1',3,'mc','auto','우유니 소금 사막은 원래 호수였는데 물이 모두 말라 없어지자 바닥이 하얀 소금으로 덮였어요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X04','SC5-2-u1-X03','SC5-2-u1-X01']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C1","difficulty":3,"kind":"mc","stem":"우유니 소금 사막은 원래 호수였는데 물이 모두 말라 없어지자 바닥이 하얀 소금으로 덮였어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"호수의 물에 소금이 섞여 있었기 때문이다","correct":true},{"t":"호수의 물에는 아무것도 섞여 있지 않았기 때문이다","mis":"SC5-2-u1-X04"},{"t":"물이 마르면서 새 물질로 바뀌었기 때문이다","mis":"SC5-2-u1-X03"},{"t":"하늘에서 소금이 내렸기 때문이다","mis":"SC5-2-u1-X01"}],"explanation":["호수 물에 소금이 있었어요.","물이 없어졌어요.","섞여 있던 소금이 남았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_challenge#8','sci',5,2,'u1','L01','g5_2_sci_u1_L01_challenge','lesson_challenge','SC5-2-u1-C1',4,'mc','auto','교실에서 섞여 있는 물질 두 가지를 바르게 찾은 친구는 누구인가요?',ARRAY['SC5-2-u1-X02','SC5-2-u1-X01']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C1","difficulty":4,"kind":"mc","stem":"교실에서 섞여 있는 물질 두 가지를 바르게 찾은 친구는 누구인가요?","options":[{"t":"은우 — 화단 흙, 우유","correct":true},{"t":"시우 — 얼음, 못","mis":"SC5-2-u1-X02"},{"t":"하린 — 금반지, 화단 흙","mis":"SC5-2-u1-X02"},{"t":"준서 — 산소, 우유","mis":"SC5-2-u1-X01"}],"explanation":["화단 흙에는 흙·모래·돌이 있어요.","우유에도 여러 가지가 있어요.","은우가 바르게 찾았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_challenge#9','sci',5,2,'u1','L01','g5_2_sci_u1_L01_challenge','lesson_challenge','SC5-2-u1-C1',4,'mc','auto','물질을 두 갈래로 나누는 방법을 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SC5-2-u1-X01','SC5-2-u1-X02','SC5-2-u1-X07']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C1","difficulty":4,"kind":"mc","stem":"물질을 두 갈래로 나누는 방법을 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"무엇으로 되어 있는지 따져 한 가지면 한 가지 물질, 두 가지 이상이면 섞여 있는 물질로 나눈다","correct":true},{"t":"눈에 보이는 것은 섞인 물질, 안 보이는 것은 한 가지 물질로 나눈다","mis":"SC5-2-u1-X01"},{"t":"딱딱하면 한 가지 물질, 물렁하면 섞인 물질로 나눈다","mis":"SC5-2-u1-X02"},{"t":"주변 물질은 모두 섞여 있으니 나눌 필요가 없다","mis":"SC5-2-u1-X07"}],"explanation":["무엇으로 되었는지 봐요.","한 가지인지 세어요.","겉모습은 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L01_challenge#10','sci',5,2,'u1','L01','g5_2_sci_u1_L01_challenge','lesson_challenge','SC5-2-u1-C1',4,'essay','teacher','말판 놀이 칸 카드에서 한 가지 물질 두 개와 섞여 있는 물질 두 개를 골라 쓰고, 섞여 있는 물질은 무엇과 무엇이 섞였는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u1-C1","difficulty":4,"kind":"essay","stem":"말판 놀이 칸 카드에서 한 가지 물질 두 개와 섞여 있는 물질 두 개를 골라 쓰고, 섞여 있는 물질은 무엇과 무엇이 섞였는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 한 가지 물질은 금관(금)과 못(철)이다. 섞여 있는 물질은 소금물과 공기이다. 소금물에는 소금과 물이, 공기에는 질소·산소·이산화 탄소 등이 섞여 있기 때문이다.","scoring_points":["한 가지 물질 두 개를 바르게 골랐는가","섞여 있는 물질 두 개를 바르게 골랐는가","무엇과 무엇이 섞였는지 까닭을 썼는가"]},"explanation":["한 가지를 골라요.","섞인 것을 골라요.","섞인 것을 밝혀요."],"asset":{"type":"passage","lines":["㉠ 금관   ㉡ 소금물   ㉢ 못   ㉣ 공기","㉤ 얼음   ㉥ 탄산음료   ㉦ 바닷가 흙   ㉧ 산소"],"title":"말판 놀이 칸 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_basic#1','sci',5,2,'u1','L02','g5_2_sci_u1_L02_basic','lesson_basic','SC5-2-u1-C2',1,'sa','auto','두 가지 이상의 물질이 각각의 성질이 변하지 않은 채 섞여 있는 것을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u1-C2","difficulty":1,"kind":"sa","stem":"두 가지 이상의 물질이 각각의 성질이 변하지 않은 채 섞여 있는 것을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["혼합물"],"explanation":["여럿이 섞였어요.","성질은 그대로예요.","혼합물이에요."],"mis":"SC5-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_basic#2','sci',5,2,'u1','L02','g5_2_sci_u1_L02_basic','lesson_basic','SC5-2-u1-C3',1,'mc','auto','사탕수수에서 분리해 얻는 물질은 어느 것인가요?',ARRAY['SC5-2-u1-X05']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C3","difficulty":1,"kind":"mc","stem":"사탕수수에서 분리해 얻는 물질은 어느 것인가요?","options":[{"t":"설탕","correct":true},{"t":"소금","mis":"SC5-2-u1-X05"},{"t":"금","mis":"SC5-2-u1-X05"},{"t":"목화솜","mis":"SC5-2-u1-X05"}],"explanation":["사탕수수는 달아요.","단맛을 내는 물질이에요.","설탕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_basic#3','sci',5,2,'u1','L02','g5_2_sci_u1_L02_basic','lesson_basic','SC5-2-u1-C3',1,'mc','auto','바닷물에서 분리해 얻는 물질은 어느 것인가요?',ARRAY['SC5-2-u1-X05']::text[],false,'{"seq":3,"concept":"SC5-2-u1-C3","difficulty":1,"kind":"mc","stem":"바닷물에서 분리해 얻는 물질은 어느 것인가요?","options":[{"t":"소금","correct":true},{"t":"설탕","mis":"SC5-2-u1-X05"},{"t":"천연고무액","mis":"SC5-2-u1-X05"},{"t":"금","mis":"SC5-2-u1-X05"}],"explanation":["바닷물은 짜요.","짠맛을 내는 물질이에요.","소금이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_basic#4','sci',5,2,'u1','L02','g5_2_sci_u1_L02_basic','lesson_basic','SC5-2-u1-C4',1,'ox','auto','혼합물을 분리하면 필요한 물질을 얻을 수 있어요.',ARRAY['SC5-2-u1-X06']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C4","difficulty":1,"kind":"ox","stem":"혼합물을 분리하면 필요한 물질을 얻을 수 있어요.","answer":"O","reason_options":[{"t":"여러 물질이 섞여 있어 나누어야 필요한 것만 쓸 수 있기 때문에","correct":true},{"t":"분리하면 물질의 양이 더 많아지기 때문에","mis":"SC5-2-u1-X06"}],"mis":"SC5-2-u1-X06","explanation":["여러 물질이 섞였어요.","나누면 골라 쓸 수 있어요.","필요한 물질을 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_basic#5','sci',5,2,'u1','L02','g5_2_sci_u1_L02_basic','lesson_basic','SC5-2-u1-C2',2,'mc','auto','혼합물에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X01','SC5-2-u1-X03']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C2","difficulty":2,"kind":"mc","stem":"혼합물에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"두 가지 이상의 물질이 성질이 변하지 않은 채 섞여 있는 것","correct":true},{"t":"한 가지 물질로만 이루어진 것","mis":"SC5-2-u1-X01"},{"t":"섞이면 성질이 모두 바뀌는 것","mis":"SC5-2-u1-X03"},{"t":"눈에 보이는 물질만 섞인 것","mis":"SC5-2-u1-X01"}],"explanation":["두 가지 이상이에요.","성질은 그대로예요.","섞여 있는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_basic#6','sci',5,2,'u1','L02','g5_2_sci_u1_L02_basic','lesson_basic','SC5-2-u1-C3',2,'mc','auto','혼합물에서 얻는 물질 카드를 보고, 혼합물과 얻는 물질의 짝이 알맞지 않은 것을 고르세요.',ARRAY['SC5-2-u1-X05']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C3","difficulty":2,"kind":"mc","stem":"혼합물에서 얻는 물질 카드를 보고, 혼합물과 얻는 물질의 짝이 알맞지 않은 것을 고르세요.","options":[{"t":"고무나무 — 금","correct":true},{"t":"바닷물 — 소금","mis":"SC5-2-u1-X05"},{"t":"사탕수수 — 설탕","mis":"SC5-2-u1-X05"},{"t":"목화 — 목화솜","mis":"SC5-2-u1-X05"}],"explanation":["금은 금광석에서 얻어요.","고무나무는 천연고무액이에요.","고무나무 — 금이 틀렸어요."],"asset":{"type":"passage","lines":["바닷물 → 소금","사탕수수 → 설탕","금광석 → 금","고무나무 → 천연고무액","목화 → 목화솜","콩 → 콩 단백질"],"title":"혼합물에서 얻는 물질 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_basic#7','sci',5,2,'u1','L02','g5_2_sci_u1_L02_basic','lesson_basic','SC5-2-u1-C4',2,'mc','auto','혼합물을 분리하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X03','SC5-2-u1-X06']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C4","difficulty":2,"kind":"mc","stem":"혼합물을 분리하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"필요한 물질을 얻을 수 있어서","correct":true},{"t":"물질의 성질을 바꾸려고","mis":"SC5-2-u1-X03"},{"t":"물질을 더 무겁게 만들려고","mis":"SC5-2-u1-X06"},{"t":"혼합물을 더 많이 만들려고","mis":"SC5-2-u1-X06"}],"explanation":["섞여 있으면 골라 쓰기 어려워요.","나누면 골라 써요.","필요한 물질을 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_basic#8','sci',5,2,'u1','L02','g5_2_sci_u1_L02_basic','lesson_basic','SC5-2-u1-C2',2,'ox','auto','바닷물에서 얻은 소금도 짠맛이 나요.',ARRAY['SC5-2-u1-X03']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C2","difficulty":2,"kind":"ox","stem":"바닷물에서 얻은 소금도 짠맛이 나요.","answer":"O","reason_options":[{"t":"바닷물 속 소금은 성질이 변하지 않은 채 섞여 있었기 때문에","correct":true},{"t":"바닷물에 섞이면서 새 물질로 바뀌었기 때문에","mis":"SC5-2-u1-X03"}],"mis":"SC5-2-u1-X03","explanation":["혼합물 속 물질은 성질이 그대로예요.","소금은 계속 짜요.","얻은 소금도 짜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_basic#9','sci',5,2,'u1','L02','g5_2_sci_u1_L02_basic','lesson_basic','SC5-2-u1-C3',2,'mc','auto','고무나무에서 얻은 천연고무액으로 만들 수 있는 물건은 어느 것인가요?',ARRAY['SC5-2-u1-X05']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C3","difficulty":2,"kind":"mc","stem":"고무나무에서 얻은 천연고무액으로 만들 수 있는 물건은 어느 것인가요?","options":[{"t":"지우개","correct":true},{"t":"두부","mis":"SC5-2-u1-X05"},{"t":"이불","mis":"SC5-2-u1-X05"},{"t":"사탕","mis":"SC5-2-u1-X05"}],"explanation":["고무나무에서 고무액을 얻어요.","고무로 만든 물건을 찾아요.","지우개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_basic#10','sci',5,2,'u1','L02','g5_2_sci_u1_L02_basic','lesson_basic','SC5-2-u1-C4',3,'error','auto','분리배출하는 날 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X06']::text[],false,'{"seq":10,"concept":"SC5-2-u1-C4","difficulty":3,"kind":"error","stem":"분리배출하는 날 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「분리배출은 통을 보기 좋게 채우려고 하는 거야.」","correct":true,"mis_target":"SC5-2-u1-X06"},{"t":"서진 — 「물질별로 나누어 모으면 다시 얻어 쓸 수 있어.」","mis":"SC5-2-u1-X06"},{"t":"나연 — 「혼합물을 나누어 필요한 물질을 얻는 것과 닮았어.」","mis":"SC5-2-u1-X06"}],"explanation":["나누면 다시 쓸 수 있어요.","필요한 물질을 얻어요.","태윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_challenge#1','sci',5,2,'u1','L02','g5_2_sci_u1_L02_challenge','lesson_challenge','SC5-2-u1-C3',2,'match','auto','혼합물과 그 혼합물에서 분리해 얻는 물질을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u1-C3","difficulty":2,"kind":"match","stem":"혼합물과 그 혼합물에서 분리해 얻는 물질을 알맞게 이으세요.","pairs":[{"l":"바닷물","r":"소금"},{"l":"금광석","r":"금"},{"l":"목화","r":"목화솜"},{"l":"콩","r":"콩 단백질"}],"mis":"SC5-2-u1-X05","explanation":["바닷물은 소금이에요.","금광석은 금이에요.","목화는 솜, 콩은 단백질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_challenge#2','sci',5,2,'u1','L02','g5_2_sci_u1_L02_challenge','lesson_challenge','SC5-2-u1-C2',2,'mc','auto','소금물 속 소금에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X04','SC5-2-u1-X03','SC5-2-u1-X01']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C2","difficulty":2,"kind":"mc","stem":"소금물 속 소금에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"짠맛이 그대로 있다 — 성질이 변하지 않은 채 섞여 있다","correct":true},{"t":"짠맛이 사라졌다 — 물에 섞여 없어졌다","mis":"SC5-2-u1-X04"},{"t":"단맛으로 바뀌었다 — 새 물질이 되었다","mis":"SC5-2-u1-X03"},{"t":"소금물에는 소금이 들어 있지 않다","mis":"SC5-2-u1-X01"}],"explanation":["혼합물 속 물질은 성질이 그대로예요.","소금은 여전히 짜요.","섞여 있을 뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_challenge#3','sci',5,2,'u1','L02','g5_2_sci_u1_L02_challenge','lesson_challenge','SC5-2-u1-C4',3,'mc','auto','옛날 곡식 까부르기를 혼합물의 분리로 설명한 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X06','SC5-2-u1-X03']::text[],false,'{"seq":3,"concept":"SC5-2-u1-C4","difficulty":3,"kind":"mc","stem":"옛날 곡식 까부르기를 혼합물의 분리로 설명한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"곡식과 쭉정이·티끌이 섞인 혼합물에서 필요한 알곡만 얻으려고 했다","correct":true},{"t":"곡식을 더 무겁게 만들려고 했다","mis":"SC5-2-u1-X06"},{"t":"곡식을 새 물질로 바꾸려고 했다","mis":"SC5-2-u1-X03"},{"t":"곡식의 색깔을 예쁘게 하려고 했다","mis":"SC5-2-u1-X06"}],"explanation":["곡식에 티끌이 섞였어요.","필요한 건 알곡이에요.","알곡만 얻으려 했어요."],"asset":{"type":"passage","lines":["옛날 농부는 거둔 곡식을 키에 담아 위아래로 흔들었다.","바람을 일으키는 풍구에 곡식을 붓기도 했다.","가벼운 쭉정이와 티끌은 날아가고 알곡이 모였다."],"title":"옛날 곡식 까부르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_challenge#4','sci',5,2,'u1','L02','g5_2_sci_u1_L02_challenge','lesson_challenge','SC5-2-u1-C3',3,'mc','auto','콩 한 가지에서 분리해 얻은 물질로 만들 수 있는 것을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X05']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C3","difficulty":3,"kind":"mc","stem":"콩 한 가지에서 분리해 얻은 물질로 만들 수 있는 것을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"두부와 콩고기","correct":true},{"t":"지우개와 이불","mis":"SC5-2-u1-X05"},{"t":"사탕과 시럽","mis":"SC5-2-u1-X05"},{"t":"금반지와 지우개","mis":"SC5-2-u1-X05"}],"explanation":["콩에서 콩 단백질을 얻어요.","단백질로 음식을 만들어요.","두부와 콩고기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_challenge#5','sci',5,2,'u1','L02','g5_2_sci_u1_L02_challenge','lesson_challenge','SC5-2-u1-C4',3,'ox','auto','혼합물을 분리하는 까닭은 우리 주변의 물질이 모두 혼합물이기 때문이에요.',ARRAY['SC5-2-u1-X07']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C4","difficulty":3,"kind":"ox","stem":"혼합물을 분리하는 까닭은 우리 주변의 물질이 모두 혼합물이기 때문이에요.","answer":"X","reason_options":[{"t":"한 가지 물질도 있고, 분리하는 까닭은 필요한 물질을 얻기 위해서이기 때문에","correct":true},{"t":"주변 물질은 하나도 빠짐없이 섞여 있기 때문에","mis":"SC5-2-u1-X07"}],"mis":"SC5-2-u1-X07","explanation":["금관·못은 한 가지 물질이에요.","「모두」가 틀렸어요.","필요한 물질을 얻으려 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_challenge#6','sci',5,2,'u1','L02','g5_2_sci_u1_L02_challenge','lesson_challenge','SC5-2-u1-C2',3,'error','auto','혼합물을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X04','SC5-2-u1-X01','SC5-2-u1-X03']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C2","difficulty":3,"kind":"error","stem":"혼합물을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로아 — 「설탕물 속 설탕은 녹아서 단맛이 없어졌어.」","correct":true,"mis_target":"SC5-2-u1-X04"},{"t":"지안 — 「공기도 여러 기체가 섞인 혼합물이야.」","mis":"SC5-2-u1-X01"},{"t":"하율 — 「바닷물에서 얻은 소금은 짜.」","mis":"SC5-2-u1-X03"}],"explanation":["녹아도 설탕은 섞여 있어요.","단맛은 그대로예요.","로아의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_challenge#7','sci',5,2,'u1','L02','g5_2_sci_u1_L02_challenge','lesson_challenge','SC5-2-u1-C3',3,'mc','auto','병원에서 혈액을 나누는 기계를 쓰는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X03','SC5-2-u1-X06','SC5-2-u1-X01']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C3","difficulty":3,"kind":"mc","stem":"병원에서 혈액을 나누는 기계를 쓰는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"혈액을 여러 성분으로 나누어 치료와 연구에 필요한 곳에 쓰려고","correct":true},{"t":"혈액을 새 물질로 바꾸려고","mis":"SC5-2-u1-X03"},{"t":"혈액의 양을 늘리려고","mis":"SC5-2-u1-X06"},{"t":"혈액은 한 가지 물질이라 확인하려고","mis":"SC5-2-u1-X01"}],"explanation":["혈액도 여러 성분이 섞였어요.","나누면 필요한 곳에 써요.","치료와 연구에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_challenge#8','sci',5,2,'u1','L02','g5_2_sci_u1_L02_challenge','lesson_challenge','SC5-2-u1-C4',4,'mc','auto','바닷물을 나누지 않고 그대로 둔다면 생길 수 있는 불편함으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X06','SC5-2-u1-X01','SC5-2-u1-X04']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C4","difficulty":4,"kind":"mc","stem":"바닷물을 나누지 않고 그대로 둔다면 생길 수 있는 불편함으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"음식에 넣을 소금도, 마실 물도 따로 얻을 수 없다","correct":true},{"t":"바닷물이 저절로 소금과 물로 나뉘어 불편함이 없다","mis":"SC5-2-u1-X06"},{"t":"바닷물은 한 가지 물질이라 나눌 것이 없다","mis":"SC5-2-u1-X01"},{"t":"바닷물의 소금은 없어졌으니 얻을 것이 없다","mis":"SC5-2-u1-X04"}],"explanation":["바닷물엔 소금과 물이 섞였어요.","나누지 않으면 골라 못 써요.","소금도 물도 못 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_challenge#9','sci',5,2,'u1','L02','g5_2_sci_u1_L02_challenge','lesson_challenge','SC5-2-u1-C2',4,'mc','auto','혼합물 속 물질의 성질이 그대로라는 점이 분리에 도움이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X03','SC5-2-u1-X33']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C2","difficulty":4,"kind":"mc","stem":"혼합물 속 물질의 성질이 그대로라는 점이 분리에 도움이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"물질마다 성질이 남아 있어 그 차이를 이용해 나눌 수 있다","correct":true},{"t":"섞이면 모두 같은 성질이 되어 한꺼번에 나뉜다","mis":"SC5-2-u1-X03"},{"t":"성질이 그대로이면 나눌 수 없다","mis":"SC5-2-u1-X03"},{"t":"성질과 분리는 아무 관계가 없다","mis":"SC5-2-u1-X33"}],"explanation":["성질이 그대로예요.","서로 달라요.","그 차이로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L02_challenge#10','sci',5,2,'u1','L02','g5_2_sci_u1_L02_challenge','lesson_challenge','SC5-2-u1-C4',4,'essay','teacher','혼합물을 분리하는 까닭을 쓰고, 혼합물에서 분리해 얻는 물질과 그 쓰임의 예를 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u1-C4","difficulty":4,"kind":"essay","stem":"혼합물을 분리하는 까닭을 쓰고, 혼합물에서 분리해 얻는 물질과 그 쓰임의 예를 두 가지 쓰세요.","answer_guide":{"answer":"예: 혼합물에는 여러 물질이 섞여 있어 분리해야 필요한 물질을 얻어 쓸 수 있다. 바닷물에서 소금을 얻어 음식에 넣고, 사탕수수에서 설탕을 얻어 사탕을 만든다.","scoring_points":["필요한 물질을 얻으려는 까닭을 썼는가","혼합물과 얻는 물질을 두 가지 바르게 썼는가","얻은 물질의 쓰임을 썼는가"]},"explanation":["까닭을 써요.","예를 둘 들어요.","쓰임도 써요."],"asset":{"type":"passage","lines":["바닷물 → 소금","사탕수수 → 설탕","금광석 → 금","고무나무 → 천연고무액","목화 → 목화솜","콩 → 콩 단백질"],"title":"혼합물에서 얻는 물질 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_basic#1','sci',5,2,'u1','L03','g5_2_sci_u1_L03_basic','lesson_basic','SC5-2-u1-C5',1,'mc','auto','모래와 자갈의 가장 뚜렷한 차이는 어느 것인가요?',ARRAY['SC5-2-u1-X08']::text[],false,'{"seq":1,"concept":"SC5-2-u1-C5","difficulty":1,"kind":"mc","stem":"모래와 자갈의 가장 뚜렷한 차이는 어느 것인가요?","options":[{"t":"알갱이의 크기","correct":true},{"t":"알갱이의 색깔","mis":"SC5-2-u1-X08"},{"t":"알갱이의 모양","mis":"SC5-2-u1-X08"},{"t":"알갱이의 냄새","mis":"SC5-2-u1-X08"}],"explanation":["색과 모양은 둘 다 여러 가지예요.","크기는 확실히 달라요.","알갱이의 크기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_basic#2','sci',5,2,'u1','L03','g5_2_sci_u1_L03_basic','lesson_basic','SC5-2-u1-C6',1,'mc','auto','모래와 자갈의 혼합물을 알맞은 체에 내렸을 때 체에 남는 것은 어느 것인가요?',ARRAY['SC5-2-u1-X10','SC5-2-u1-X09']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C6","difficulty":1,"kind":"mc","stem":"모래와 자갈의 혼합물을 알맞은 체에 내렸을 때 체에 남는 것은 어느 것인가요?","options":[{"t":"자갈","correct":true},{"t":"모래","mis":"SC5-2-u1-X10"},{"t":"모래와 자갈 모두","mis":"SC5-2-u1-X09"},{"t":"아무것도 남지 않는다","mis":"SC5-2-u1-X10"}],"explanation":["자갈은 커요.","체의 눈을 못 지나가요.","자갈이 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_basic#3','sci',5,2,'u1','L03','g5_2_sci_u1_L03_basic','lesson_basic','SC5-2-u1-C6',1,'sa','auto','알갱이의 크기가 다른 고체 혼합물을 나눌 때 쓰는, 구멍이 뚫린 도구는 무엇인가요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-2-u1-C6","difficulty":1,"kind":"sa","stem":"알갱이의 크기가 다른 고체 혼합물을 나눌 때 쓰는, 구멍이 뚫린 도구는 무엇인가요? 한 글자로 쓰세요.","answer":["체"],"explanation":["구멍이 송송 있어요.","작은 알갱이가 빠져요.","체예요."],"mis":"SC5-2-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_basic#4','sci',5,2,'u1','L03','g5_2_sci_u1_L03_basic','lesson_basic','SC5-2-u1-C6',1,'ox','auto','체의 눈보다 작은 알갱이는 체를 빠져나가요.',ARRAY['SC5-2-u1-X10']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C6","difficulty":1,"kind":"ox","stem":"체의 눈보다 작은 알갱이는 체를 빠져나가요.","answer":"O","reason_options":[{"t":"구멍보다 작아서 지나갈 수 있기 때문에","correct":true},{"t":"작은 알갱이일수록 구멍에 잘 걸리기 때문에","mis":"SC5-2-u1-X10"}],"mis":"SC5-2-u1-X10","explanation":["작으면 지나가요.","크면 걸려요.","작은 알갱이는 빠져나가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_basic#5','sci',5,2,'u1','L03','g5_2_sci_u1_L03_basic','lesson_basic','SC5-2-u1-C5',2,'mc','auto','모래와 자갈 관찰 표를 보고, 옳지 않은 설명을 고르세요.',ARRAY['SC5-2-u1-X08']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C5","difficulty":2,"kind":"mc","stem":"모래와 자갈 관찰 표를 보고, 옳지 않은 설명을 고르세요.","options":[{"t":"모래는 자갈보다 알갱이의 크기가 크다","correct":true},{"t":"모래 알갱이의 색은 여러 가지이다","mis":"SC5-2-u1-X08"},{"t":"자갈 알갱이의 모양은 여러 가지이다","mis":"SC5-2-u1-X08"},{"t":"자갈 알갱이의 색은 여러 가지이다","mis":"SC5-2-u1-X08"}],"explanation":["모래는 작아요.","자갈이 커요.","크기가 거꾸로예요."],"asset":{"type":"passage","lines":["모래 — 모양: 여러 가지 · 색: 갈색·노란색·회색 등 · 크기: 작다","자갈 — 모양: 여러 가지 · 색: 갈색·회색·검은색 등 · 크기: 크다"],"title":"모래와 자갈 관찰 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_basic#6','sci',5,2,'u1','L03','g5_2_sci_u1_L03_basic','lesson_basic','SC5-2-u1-C6',2,'mc','auto','눈 크기가 다른 체 세 개 가운데 모래와 자갈을 나누기에 알맞은 체는 어느 것인가요?',ARRAY['SC5-2-u1-X09']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C6","difficulty":2,"kind":"mc","stem":"눈 크기가 다른 체 세 개 가운데 모래와 자갈을 나누기에 알맞은 체는 어느 것인가요?","options":[{"t":"체 나","correct":true},{"t":"체 가","mis":"SC5-2-u1-X09"},{"t":"체 다","mis":"SC5-2-u1-X09"},{"t":"어느 체를 써도 같다","mis":"SC5-2-u1-X09"}],"explanation":["모래는 빠져야 해요.","자갈은 남아야 해요.","그 사이 크기인 체 나예요."],"asset":{"type":"passage","lines":["체 가 — 눈이 모래 알갱이보다 작다","체 나 — 눈이 모래 알갱이보다 크고 자갈 알갱이보다 작다","체 다 — 눈이 자갈 알갱이보다 크다"],"title":"눈 크기가 다른 체 세 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_basic#7','sci',5,2,'u1','L03','g5_2_sci_u1_L03_basic','lesson_basic','SC5-2-u1-C7',2,'mc','auto','강에서 모래 속 작은 조개를 체로 잡을 때 일어나는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X10','SC5-2-u1-X09']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C7","difficulty":2,"kind":"mc","stem":"강에서 모래 속 작은 조개를 체로 잡을 때 일어나는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"모래는 체를 빠져나가고 조개는 체에 남는다","correct":true},{"t":"조개는 빠져나가고 모래가 체에 남는다","mis":"SC5-2-u1-X10"},{"t":"모래와 조개가 모두 체에 남는다","mis":"SC5-2-u1-X09"},{"t":"모래와 조개가 모두 빠져나간다","mis":"SC5-2-u1-X09"}],"explanation":["조개가 모래보다 커요.","작은 모래는 빠져요.","조개가 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_basic#8','sci',5,2,'u1','L03','g5_2_sci_u1_L03_basic','lesson_basic','SC5-2-u1-C7',2,'ox','auto','마스크는 공기는 지나가게 하고 황사나 먼지는 걸러 내요.',ARRAY['SC5-2-u1-X10']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C7","difficulty":2,"kind":"ox","stem":"마스크는 공기는 지나가게 하고 황사나 먼지는 걸러 내요.","answer":"O","reason_options":[{"t":"먼지 알갱이가 마스크의 구멍보다 커서 걸리기 때문에","correct":true},{"t":"마스크가 공기까지 모두 막기 때문에","mis":"SC5-2-u1-X10"}],"mis":"SC5-2-u1-X10","explanation":["공기는 지나가요.","먼지는 걸려요.","크기 차이로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_basic#9','sci',5,2,'u1','L03','g5_2_sci_u1_L03_basic','lesson_basic','SC5-2-u1-C6',2,'mc','auto','밀가루를 거르는 아주 촘촘한 체에 모래와 자갈의 혼합물을 부으면 어떻게 될까요?',ARRAY['SC5-2-u1-X09','SC5-2-u1-X10']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C6","difficulty":2,"kind":"mc","stem":"밀가루를 거르는 아주 촘촘한 체에 모래와 자갈의 혼합물을 부으면 어떻게 될까요?","options":[{"t":"모래와 자갈이 모두 체에 남아 나뉘지 않는다","correct":true},{"t":"모래만 빠져나가 잘 나뉜다","mis":"SC5-2-u1-X09"},{"t":"자갈만 빠져나간다","mis":"SC5-2-u1-X10"},{"t":"모래와 자갈이 모두 빠져나간다","mis":"SC5-2-u1-X10"}],"explanation":["눈이 모래보다 작아요.","모래도 걸려요.","둘 다 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_basic#10','sci',5,2,'u1','L03','g5_2_sci_u1_L03_basic','lesson_basic','SC5-2-u1-C6',3,'error','auto','체로 모래와 자갈을 나눈 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X09','SC5-2-u1-X10']::text[],false,'{"seq":10,"concept":"SC5-2-u1-C6","difficulty":3,"kind":"error","stem":"체로 모래와 자갈을 나눈 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「체는 눈이 작을수록 무엇이든 잘 나눠.」","correct":true,"mis_target":"SC5-2-u1-X09"},{"t":"소율 — 「모래는 체를 빠져나가 쟁반에 모였어.」","mis":"SC5-2-u1-X10"},{"t":"이준 — 「자갈은 체의 눈보다 커서 체에 남았어.」","mis":"SC5-2-u1-X10"}],"explanation":["눈이 너무 작으면 다 남아요.","사이 크기여야 해요.","하람의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_challenge#1','sci',5,2,'u1','L03','g5_2_sci_u1_L03_challenge','lesson_challenge','SC5-2-u1-C7',2,'match','auto','생활 속에서 체처럼 나누는 예와 걸러져 남는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u1-C7","difficulty":2,"kind":"match","stem":"생활 속에서 체처럼 나누는 예와 걸러져 남는 것을 알맞게 이으세요.","pairs":[{"l":"강에서 조개 잡기","r":"조개"},{"l":"해변 쓰레기 수거 장비","r":"병뚜껑·플라스틱 조각"},{"l":"마스크","r":"황사·먼지"},{"l":"밀가루 체","r":"밀가루 덩어리"}],"mis":"SC5-2-u1-X10","explanation":["큰 것이 남아요.","작은 것은 빠져요.","크기 차이를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_challenge#2','sci',5,2,'u1','L03','g5_2_sci_u1_L03_challenge','lesson_challenge','SC5-2-u1-C6',2,'mc','auto','모래와 자갈을 나누는 체의 눈 크기로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X09']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C6","difficulty":2,"kind":"mc","stem":"모래와 자갈을 나누는 체의 눈 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"모래 알갱이보다 크고 자갈 알갱이보다 작다","correct":true},{"t":"모래 알갱이보다 작다","mis":"SC5-2-u1-X09"},{"t":"자갈 알갱이보다 크다","mis":"SC5-2-u1-X09"},{"t":"클수록 좋다","mis":"SC5-2-u1-X09"}],"explanation":["모래는 빠져야 해요.","자갈은 남아야 해요.","둘 사이 크기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_challenge#3','sci',5,2,'u1','L03','g5_2_sci_u1_L03_challenge','lesson_challenge','SC5-2-u1-C7',3,'mc','auto','좁쌀·쌀·팥이 섞인 혼합물을 체로 모두 나누려고 해요. 크기는 좁쌀 < 쌀 < 팥이에요. 필요한 체로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X12','SC5-2-u1-X09']::text[],false,'{"seq":3,"concept":"SC5-2-u1-C7","difficulty":3,"kind":"mc","stem":"좁쌀·쌀·팥이 섞인 혼합물을 체로 모두 나누려고 해요. 크기는 좁쌀 < 쌀 < 팥이에요. 필요한 체로 알맞은 것은 어느 것인가요?","options":[{"t":"눈이 좁쌀보다 크고 쌀보다 작은 체와, 쌀보다 크고 팥보다 작은 체 두 개","correct":true},{"t":"눈이 좁쌀보다 크고 팥보다 작은 체 하나","mis":"SC5-2-u1-X12"},{"t":"눈이 좁쌀보다 작은 체 두 개","mis":"SC5-2-u1-X09"},{"t":"눈이 팥보다 큰 체 하나","mis":"SC5-2-u1-X09"}],"explanation":["한 번에 하나씩 나뉘어요.","세 가지면 두 번 걸러요.","체 두 개가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_challenge#4','sci',5,2,'u1','L03','g5_2_sci_u1_L03_challenge','lesson_challenge','SC5-2-u1-C7',3,'mc','auto','곡식 혼합물과 체 두 개 자료에서 작은 체로 먼저 거를 때 체를 빠져나가는 것은 어느 것인가요?',ARRAY['SC5-2-u1-X10','SC5-2-u1-X09']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C7","difficulty":3,"kind":"mc","stem":"곡식 혼합물과 체 두 개 자료에서 작은 체로 먼저 거를 때 체를 빠져나가는 것은 어느 것인가요?","options":[{"t":"좁쌀","correct":true},{"t":"팥","mis":"SC5-2-u1-X10"},{"t":"콩","mis":"SC5-2-u1-X10"},{"t":"좁쌀·팥·콩 모두","mis":"SC5-2-u1-X09"}],"explanation":["작은 체 눈은 좁쌀보다 커요.","팥보다는 작아요.","좁쌀만 빠져요."],"asset":{"type":"passage","lines":["좁쌀 < 팥 < 콩 (알갱이 크기 차례)","작은 체 — 눈이 좁쌀보다 크고 팥보다 작다","큰 체 — 눈이 팥보다 크고 콩보다 작다"],"title":"곡식 혼합물과 체 두 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_challenge#5','sci',5,2,'u1','L03','g5_2_sci_u1_L03_challenge','lesson_challenge','SC5-2-u1-C5',3,'ox','auto','모래와 자갈은 색깔로 골라내면 쉽게 나눌 수 있어요.',ARRAY['SC5-2-u1-X08']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C5","difficulty":3,"kind":"ox","stem":"모래와 자갈은 색깔로 골라내면 쉽게 나눌 수 있어요.","answer":"X","reason_options":[{"t":"둘 다 갈색·회색 등 여러 색이라 색으로는 가르기 어렵기 때문에","correct":true},{"t":"모래는 모두 노랗고 자갈은 모두 검기 때문에","mis":"SC5-2-u1-X08"}],"mis":"SC5-2-u1-X08","explanation":["둘 다 갈색이 있어요.","색으로는 헷갈려요.","크기로 나눠요."],"asset":{"type":"passage","lines":["모래 — 모양: 여러 가지 · 색: 갈색·노란색·회색 등 · 크기: 작다","자갈 — 모양: 여러 가지 · 색: 갈색·회색·검은색 등 · 크기: 크다"],"title":"모래와 자갈 관찰 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_challenge#6','sci',5,2,'u1','L03','g5_2_sci_u1_L03_challenge','lesson_challenge','SC5-2-u1-C5',3,'error','auto','체로 나눈 모래와 자갈을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X11']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C5","difficulty":3,"kind":"error","stem":"체로 나눈 모래와 자갈을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다온 — 「체로 나눈 모래는 이제 한 가지 물질이 됐어.」","correct":true,"mis_target":"SC5-2-u1-X11"},{"t":"예린 — 「쟁반의 모래 알갱이도 색이 여러 가지야.」","mis":"SC5-2-u1-X11"},{"t":"주원 — 「체에 남은 자갈도 여러 가지 돌이 섞여 있어.」","mis":"SC5-2-u1-X11"}],"explanation":["모래도 여러 알갱이예요.","여전히 섞여 있어요.","다온의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_challenge#7','sci',5,2,'u1','L03','g5_2_sci_u1_L03_challenge','lesson_challenge','SC5-2-u1-C6',3,'mc','auto','모래와 자갈을 손으로 골라낼 수도 있는데 체를 쓰는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X03','SC5-2-u1-X08','SC5-2-u1-X09']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C6","difficulty":3,"kind":"mc","stem":"모래와 자갈을 손으로 골라낼 수도 있는데 체를 쓰는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"양이 많아도 한 번에 빠르게 나눌 수 있고 작은 알갱이를 놓치지 않는다","correct":true},{"t":"체를 쓰면 모래가 자갈로 바뀌기 때문이다","mis":"SC5-2-u1-X03"},{"t":"체를 쓰면 색깔로 나눌 수 있기 때문이다","mis":"SC5-2-u1-X08"},{"t":"손으로는 자갈을 만질 수 없기 때문이다","mis":"SC5-2-u1-X09"}],"explanation":["손으로는 오래 걸려요.","체는 한 번에 나눠요.","빠르고 꼼꼼해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_challenge#8','sci',5,2,'u1','L03','g5_2_sci_u1_L03_challenge','lesson_challenge','SC5-2-u1-C7',4,'mc','auto','해변 쓰레기 수거 장비가 모래와 쓰레기를 나누는 방법을 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SC5-2-u1-X33','SC5-2-u1-X09','SC5-2-u1-X10']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C7","difficulty":4,"kind":"mc","stem":"해변 쓰레기 수거 장비가 모래와 쓰레기를 나누는 방법을 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"모래보다 크고 쓰레기보다 작은 눈의 체로 흔들어 모래는 바닷가로 돌려보내고 쓰레기를 남긴다","correct":true},{"t":"모래와 쓰레기를 물에 녹여 거른다","mis":"SC5-2-u1-X33"},{"t":"눈이 아주 작은 체로 모래와 쓰레기를 모두 남긴다","mis":"SC5-2-u1-X09"},{"t":"쓰레기는 빠져나가고 모래를 모아 버린다","mis":"SC5-2-u1-X10"}],"explanation":["체가 달린 장비예요.","고운 모래는 빠져요.","쓰레기가 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_challenge#9','sci',5,2,'u1','L03','g5_2_sci_u1_L03_challenge','lesson_challenge','SC5-2-u1-C6',4,'mc','auto','체로 모래와 자갈을 나눴는데 쟁반에 작은 자갈 몇 개가 섞여 나왔어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X09','SC5-2-u1-X03','SC5-2-u1-X04']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C6","difficulty":4,"kind":"mc","stem":"체로 모래와 자갈을 나눴는데 쟁반에 작은 자갈 몇 개가 섞여 나왔어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"체의 눈이 작은 자갈 알갱이보다 컸다","correct":true},{"t":"체의 눈이 모래 알갱이보다 작았다","mis":"SC5-2-u1-X09"},{"t":"자갈이 모래로 바뀌었다","mis":"SC5-2-u1-X03"},{"t":"체를 흔들면 자갈이 녹는다","mis":"SC5-2-u1-X04"}],"explanation":["자갈도 크기가 여러 가지예요.","작은 자갈은 눈을 지나갔어요.","눈이 조금 컸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L03_challenge#10','sci',5,2,'u1','L03','g5_2_sci_u1_L03_challenge','lesson_challenge','SC5-2-u1-C7',4,'essay','teacher','곡식 혼합물과 체 두 개 자료를 보고, 좁쌀·팥·콩을 모두 나누는 차례를 쓰고 각 단계에서 체에 남는 것과 빠져나가는 것을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u1-C7","difficulty":4,"kind":"essay","stem":"곡식 혼합물과 체 두 개 자료를 보고, 좁쌀·팥·콩을 모두 나누는 차례를 쓰고 각 단계에서 체에 남는 것과 빠져나가는 것을 쓰세요.","answer_guide":{"answer":"예: 먼저 작은 체로 거르면 좁쌀은 빠져나가고 팥과 콩은 체에 남는다. 남은 팥과 콩을 큰 체로 거르면 팥은 빠져나가고 콩이 체에 남는다. 그래서 좁쌀·팥·콩을 각각 얻는다.","scoring_points":["두 번 거르는 차례를 썼는가","각 단계에서 남는 것과 빠지는 것을 썼는가","알갱이 크기 차이를 이용한다는 것이 드러나는가"]},"explanation":["작은 체로 좁쌀을요.","큰 체로 팥을요.","콩이 남아요."],"asset":{"type":"passage","lines":["좁쌀 < 팥 < 콩 (알갱이 크기 차례)","작은 체 — 눈이 좁쌀보다 크고 팥보다 작다","큰 체 — 눈이 팥보다 크고 콩보다 작다"],"title":"곡식 혼합물과 체 두 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_basic#1','sci',5,2,'u1','L04','g5_2_sci_u1_L04_basic','lesson_basic','SC5-2-u1-C8',1,'mc','auto','물과 기름을 한 비커에 넣으면 기름은 어디에 있나요?',ARRAY['SC5-2-u1-X14','SC5-2-u1-X13']::text[],false,'{"seq":1,"concept":"SC5-2-u1-C8","difficulty":1,"kind":"mc","stem":"물과 기름을 한 비커에 넣으면 기름은 어디에 있나요?","options":[{"t":"위쪽","correct":true},{"t":"아래쪽","mis":"SC5-2-u1-X14"},{"t":"골고루 섞여 어디인지 모른다","mis":"SC5-2-u1-X13"},{"t":"물 가운데에 떠 있다","mis":"SC5-2-u1-X14"}],"explanation":["두 층이 생겨요.","기름은 위에 떠요.","위쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_basic#2','sci',5,2,'u1','L04','g5_2_sci_u1_L04_basic','lesson_basic','SC5-2-u1-C9',1,'sa','auto','층을 이룬 두 액체에서 위층 액체를 뽑아 옮길 때 쓰는 도구는 무엇인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-2-u1-C9","difficulty":1,"kind":"sa","stem":"층을 이룬 두 액체에서 위층 액체를 뽑아 옮길 때 쓰는 도구는 무엇인가요? 네 글자로 쓰세요.","answer":["스포이트"],"explanation":["고무 부분을 눌러요.","액체를 빨아들여요.","스포이트예요."],"mis":"SC5-2-u1-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_basic#3','sci',5,2,'u1','L04','g5_2_sci_u1_L04_basic','lesson_basic','SC5-2-u1-C10',1,'mc','auto','흡착포가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X16','SC5-2-u1-X13','SC5-2-u1-X17']::text[],false,'{"seq":3,"concept":"SC5-2-u1-C10","difficulty":1,"kind":"mc","stem":"흡착포가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"물 위에 뜬 기름을 빨아들인다","correct":true},{"t":"물만 빨아들이고 기름은 남긴다","mis":"SC5-2-u1-X16"},{"t":"기름을 물에 골고루 섞는다","mis":"SC5-2-u1-X13"},{"t":"물을 데워 날려 보낸다","mis":"SC5-2-u1-X17"}],"explanation":["흡착포는 기름을 좋아해요.","기름에 대요.","기름을 흡수해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_basic#4','sci',5,2,'u1','L04','g5_2_sci_u1_L04_basic','lesson_basic','SC5-2-u1-C8',1,'ox','auto','물과 기름은 골고루 섞이지 않아요.',ARRAY['SC5-2-u1-X13']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C8","difficulty":1,"kind":"ox","stem":"물과 기름은 골고루 섞이지 않아요.","answer":"O","reason_options":[{"t":"층을 이루어 기름은 위, 물은 아래에 있기 때문에","correct":true},{"t":"한 번 저으면 계속 섞여 있기 때문에","mis":"SC5-2-u1-X13"}],"mis":"SC5-2-u1-X13","explanation":["층이 생겨요.","기름은 위예요.","골고루 안 섞여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_basic#5','sci',5,2,'u1','L04','g5_2_sci_u1_L04_basic','lesson_basic','SC5-2-u1-C8',2,'mc','auto','골고루 섞이지 않는 액체 혼합물은 어느 것인가요?',ARRAY['SC5-2-u1-X13']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C8","difficulty":2,"kind":"mc","stem":"골고루 섞이지 않는 액체 혼합물은 어느 것인가요?","options":[{"t":"물과 식용유","correct":true},{"t":"물과 식초","mis":"SC5-2-u1-X13"},{"t":"오렌지주스와 탄산음료","mis":"SC5-2-u1-X13"},{"t":"설탕물과 물","mis":"SC5-2-u1-X13"}],"explanation":["식용유는 기름이에요.","물과 층을 이뤄요.","물과 식용유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_basic#6','sci',5,2,'u1','L04','g5_2_sci_u1_L04_basic','lesson_basic','SC5-2-u1-C10',2,'mc','auto','바다에 기름이 흘러나왔을 때 알맞은 방법은 어느 것인가요?',ARRAY['SC5-2-u1-X17','SC5-2-u1-X13']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C10","difficulty":2,"kind":"mc","stem":"바다에 기름이 흘러나왔을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"흡착포를 던져 물 위의 기름을 흡수한다","correct":true},{"t":"체로 바닷물을 거른다","mis":"SC5-2-u1-X17"},{"t":"바닷물을 세게 저어 섞는다","mis":"SC5-2-u1-X13"},{"t":"기름 위에 물을 더 붓는다","mis":"SC5-2-u1-X17"}],"explanation":["기름은 위에 떠요.","흡착포가 빨아들여요.","흡착포를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_basic#7','sci',5,2,'u1','L04','g5_2_sci_u1_L04_basic','lesson_basic','SC5-2-u1-C9',2,'mc','auto','스포이트로 물과 기름을 나눌 때 알맞은 방법은 어느 것인가요?',ARRAY['SC5-2-u1-X15']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C9","difficulty":2,"kind":"mc","stem":"스포이트로 물과 기름을 나눌 때 알맞은 방법은 어느 것인가요?","options":[{"t":"위층의 기름부터 뽑고, 경계면 가까이는 조심해서 따로 모은다","correct":true},{"t":"아래층의 물부터 깊이 넣어 뽑는다","mis":"SC5-2-u1-X15"},{"t":"스포이트를 닦지 않고 계속 다시 넣는다","mis":"SC5-2-u1-X15"},{"t":"경계면까지 한 번에 세게 빨아들인다","mis":"SC5-2-u1-X15"}],"explanation":["기름은 위에 있어요.","경계면에서는 섞일 수 있어요.","위층부터 조심히 뽑아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_basic#8','sci',5,2,'u1','L04','g5_2_sci_u1_L04_basic','lesson_basic','SC5-2-u1-C8',2,'ox','auto','물과 기름을 세게 흔들면 골고루 섞인 채로 계속 있어요.',ARRAY['SC5-2-u1-X13']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C8","difficulty":2,"kind":"ox","stem":"물과 기름을 세게 흔들면 골고루 섞인 채로 계속 있어요.","answer":"X","reason_options":[{"t":"잠깐 뿌옇게 보이지만 시간이 지나면 다시 층을 이루기 때문에","correct":true},{"t":"한 번 섞이면 다시는 나뉘지 않기 때문에","mis":"SC5-2-u1-X13"}],"mis":"SC5-2-u1-X13","explanation":["흔들면 뿌예져요.","기다리면 층이 생겨요.","골고루 섞이지 않아요."],"asset":{"type":"passage","lines":["① 비커에 물을 붓고 식용유를 조금 부었다.","② 식용유가 물 위로 올라와 두 층이 생겼다.","③ 유리 막대로 세게 저었더니 뿌옇게 되었다.","④ 몇 분 뒤 다시 보니 또 두 층으로 나뉘어 있었다."],"title":"물과 기름 관찰 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_basic#9','sci',5,2,'u1','L04','g5_2_sci_u1_L04_basic','lesson_basic','SC5-2-u1-C10',2,'mc','auto','분리한 기름을 다시 써야 할 때 알맞은 도구는 어느 것인가요?',ARRAY['SC5-2-u1-X16','SC5-2-u1-X17']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C10","difficulty":2,"kind":"mc","stem":"분리한 기름을 다시 써야 할 때 알맞은 도구는 어느 것인가요?","options":[{"t":"스포이트","correct":true},{"t":"흡착포","mis":"SC5-2-u1-X16"},{"t":"체","mis":"SC5-2-u1-X17"},{"t":"돋보기","mis":"SC5-2-u1-X17"}],"explanation":["흡착포는 기름을 머금어요.","스포이트는 옮겨 담아요.","스포이트예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_basic#10','sci',5,2,'u1','L04','g5_2_sci_u1_L04_basic','lesson_basic','SC5-2-u1-C10',3,'error','auto','물과 기름을 나눈 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X16']::text[],false,'{"seq":10,"concept":"SC5-2-u1-C10","difficulty":3,"kind":"error","stem":"물과 기름을 나눈 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라희 — 「흡착포에 빨아들인 기름은 꼭 짜서 바로 요리에 다시 쓰면 돼.」","correct":true,"mis_target":"SC5-2-u1-X16"},{"t":"건우 — 「스포이트로 옮긴 기름은 다시 쓸 수 있어.」","mis":"SC5-2-u1-X16"},{"t":"채아 — 「흡착포는 얇게 퍼진 기름에 쓰기 편해.」","mis":"SC5-2-u1-X16"}],"explanation":["흡착포 기름은 다시 쓰기 어려워요.","스포이트는 다시 써요.","라희의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["스포이트 — 위층 기름을 뽑아 다른 비커에 옮긴다.","흡착포 — 핀셋으로 기름 위에 가볍게 대어 기름을 빨아들인다."],"title":"물과 기름을 나누는 두 도구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_challenge#1','sci',5,2,'u1','L04','g5_2_sci_u1_L04_challenge','lesson_challenge','SC5-2-u1-C10',2,'match','auto','도구와 그 도구로 할 수 있는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u1-C10","difficulty":2,"kind":"match","stem":"도구와 그 도구로 할 수 있는 일을 알맞게 이으세요.","pairs":[{"l":"스포이트","r":"위층 기름을 뽑아 다른 그릇에 옮긴다"},{"l":"흡착포","r":"얇게 퍼진 기름을 빨아들인다"},{"l":"국자","r":"국 위에 뜬 기름을 떠낸다"},{"l":"주방 종이","r":"찌개 위 기름에 살짝 대어 흡수한다"}],"mis":"SC5-2-u1-X16","explanation":["스포이트는 옮겨요.","흡착포·종이는 빨아들여요.","국자는 떠내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_challenge#2','sci',5,2,'u1','L04','g5_2_sci_u1_L04_challenge','lesson_challenge','SC5-2-u1-C8',2,'mc','auto','비커에 기름을 먼저 붓고 물을 나중에 부으면 어떻게 될까요?',ARRAY['SC5-2-u1-X14','SC5-2-u1-X13','SC5-2-u1-X04']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C8","difficulty":2,"kind":"mc","stem":"비커에 기름을 먼저 붓고 물을 나중에 부으면 어떻게 될까요?","options":[{"t":"기름이 위로 올라가 다시 위층이 된다","correct":true},{"t":"먼저 부은 기름이 아래층에 그대로 있다","mis":"SC5-2-u1-X14"},{"t":"물과 기름이 골고루 섞인다","mis":"SC5-2-u1-X13"},{"t":"기름이 물에 녹아 없어진다","mis":"SC5-2-u1-X04"}],"explanation":["붓는 차례는 상관없어요.","기름은 위로 떠요.","기름이 위층이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_challenge#3','sci',5,2,'u1','L04','g5_2_sci_u1_L04_challenge','lesson_challenge','SC5-2-u1-C10',3,'mc','auto','물 위에 기름이 아주 얇고 넓게 퍼져 있을 때 더 알맞은 도구와 까닭은 어느 것인가요?',ARRAY['SC5-2-u1-X16','SC5-2-u1-X17']::text[],false,'{"seq":3,"concept":"SC5-2-u1-C10","difficulty":3,"kind":"mc","stem":"물 위에 기름이 아주 얇고 넓게 퍼져 있을 때 더 알맞은 도구와 까닭은 어느 것인가요?","options":[{"t":"흡착포 — 넓게 퍼진 기름에 대어 빨아들이기 쉽다","correct":true},{"t":"스포이트 — 얇은 기름층만 골라 뽑기 쉽다","mis":"SC5-2-u1-X16"},{"t":"체 — 기름이 체에 걸린다","mis":"SC5-2-u1-X17"},{"t":"돋보기 — 기름을 크게 보면 나뉜다","mis":"SC5-2-u1-X17"}],"explanation":["얇으면 뽑기 어려워요.","흡착포는 대기만 하면 돼요.","흡착포가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_challenge#4','sci',5,2,'u1','L04','g5_2_sci_u1_L04_challenge','lesson_challenge','SC5-2-u1-C8',3,'mc','auto','간장에 참기름을 너무 많이 부었더니 참기름이 위에 떠 있어요. 참기름을 덜어 내는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X13','SC5-2-u1-X17','SC5-2-u1-X14']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C8","difficulty":3,"kind":"mc","stem":"간장에 참기름을 너무 많이 부었더니 참기름이 위에 떠 있어요. 참기름을 덜어 내는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"위에 뜬 참기름을 숟가락이나 스포이트로 떠낸다","correct":true},{"t":"다시 세게 저어 참기름을 녹인다","mis":"SC5-2-u1-X13"},{"t":"체로 걸러 참기름을 남긴다","mis":"SC5-2-u1-X17"},{"t":"간장을 위에서부터 떠낸다","mis":"SC5-2-u1-X14"}],"explanation":["참기름은 위에 떠요.","위만 떠내면 돼요.","숟가락·스포이트를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_challenge#5','sci',5,2,'u1','L04','g5_2_sci_u1_L04_challenge','lesson_challenge','SC5-2-u1-C9',3,'ox','auto','스포이트로 기름을 뽑다가 경계면 가까이에 오면 그 부분은 따로 모아요.',ARRAY['SC5-2-u1-X15']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C9","difficulty":3,"kind":"ox","stem":"스포이트로 기름을 뽑다가 경계면 가까이에 오면 그 부분은 따로 모아요.","answer":"O","reason_options":[{"t":"경계면에서는 물이 기름에 섞여 들어갈 수 있기 때문에","correct":true},{"t":"경계면에서는 새 물질이 생기기 때문에","mis":"SC5-2-u1-X15"}],"mis":"SC5-2-u1-X15","explanation":["경계면은 두 액체가 닿아요.","물이 섞일 수 있어요.","따로 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_challenge#6','sci',5,2,'u1','L04','g5_2_sci_u1_L04_challenge','lesson_challenge','SC5-2-u1-C8',3,'error','auto','물과 기름 관찰 메모를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X14','SC5-2-u1-X13','SC5-2-u1-X17']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C8","difficulty":3,"kind":"error","stem":"물과 기름 관찰 메모를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세아 — 「물이 위층, 기름이 아래층에 있었어.」","correct":true,"mis_target":"SC5-2-u1-X14"},{"t":"윤호 — 「세게 저어도 몇 분 뒤 다시 층이 생겼어.」","mis":"SC5-2-u1-X13"},{"t":"가온 — 「위층만 떠내면 나눌 수 있겠어.」","mis":"SC5-2-u1-X17"}],"explanation":["기름이 위에 올라왔어요.","물이 아래예요.","세아의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["① 비커에 물을 붓고 식용유를 조금 부었다.","② 식용유가 물 위로 올라와 두 층이 생겼다.","③ 유리 막대로 세게 저었더니 뿌옇게 되었다.","④ 몇 분 뒤 다시 보니 또 두 층으로 나뉘어 있었다."],"title":"물과 기름 관찰 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_challenge#7','sci',5,2,'u1','L04','g5_2_sci_u1_L04_challenge','lesson_challenge','SC5-2-u1-C10',3,'mc','auto','물 위에 마블링 물감을 떨어뜨리고 도화지를 덮으면 무늬가 찍혀요. 이것이 가능한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X33','SC5-2-u1-X13','SC5-2-u1-X14']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C10","difficulty":3,"kind":"mc","stem":"물 위에 마블링 물감을 떨어뜨리고 도화지를 덮으면 무늬가 찍혀요. 이것이 가능한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"마블링 물감이 기름 성분이라 물과 섞이지 않고 물 위에 떠 있기 때문이다","correct":true},{"t":"물감이 진해서 물에 녹지 않기 때문이다","mis":"SC5-2-u1-X33"},{"t":"물감이 물에 골고루 섞이기 때문이다","mis":"SC5-2-u1-X13"},{"t":"물감이 물 아래로 가라앉기 때문이다","mis":"SC5-2-u1-X14"}],"explanation":["물감은 기름 성분이에요.","물과 안 섞여요.","위에 떠서 찍혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_challenge#8','sci',5,2,'u1','L04','g5_2_sci_u1_L04_challenge','lesson_challenge','SC5-2-u1-C10',4,'mc','auto','국이나 찌개 위의 기름을 줄이는 방법 두 가지를 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X13','SC5-2-u1-X17','SC5-2-u1-X14']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C10","difficulty":4,"kind":"mc","stem":"국이나 찌개 위의 기름을 줄이는 방법 두 가지를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"국자로 위에 뜬 기름을 떠낸다 · 주방 종이를 살짝 대어 기름을 흡수시킨다","correct":true},{"t":"세게 저어 기름을 섞는다 · 뚜껑을 덮어 둔다","mis":"SC5-2-u1-X13"},{"t":"체로 국을 거른다 · 국을 데운다","mis":"SC5-2-u1-X17"},{"t":"국 아래쪽을 떠낸다 · 기름을 더 붓는다","mis":"SC5-2-u1-X14"}],"explanation":["기름은 위에 떠요.","떠내거나 흡수해요.","국자와 주방 종이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_challenge#9','sci',5,2,'u1','L04','g5_2_sci_u1_L04_challenge','lesson_challenge','SC5-2-u1-C8',4,'mc','auto','물과 기름을 나누는 여러 방법(스포이트·흡착포·국자)의 공통점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X33']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C8","difficulty":4,"kind":"mc","stem":"물과 기름을 나누는 여러 방법(스포이트·흡착포·국자)의 공통점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"섞이지 않고 위에 뜬 기름을 걷어 낸다는 점을 이용한다","correct":true},{"t":"알갱이의 크기 차이를 이용한다","mis":"SC5-2-u1-X33"},{"t":"물에 녹는 성질을 이용한다","mis":"SC5-2-u1-X33"},{"t":"색깔 차이를 이용한다","mis":"SC5-2-u1-X33"}],"explanation":["기름은 위에 떠요.","위층을 걷어 내요.","섞이지 않는 성질을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L04_challenge#10','sci',5,2,'u1','L04','g5_2_sci_u1_L04_challenge','lesson_challenge','SC5-2-u1-C10',4,'essay','teacher','물과 기름을 나누는 두 도구 자료를 보고, ① 나눈 기름을 다시 써야 할 때와 ② 바다에 기름이 얇게 퍼졌을 때 각각 어떤 도구가 알맞은지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u1-C10","difficulty":4,"kind":"essay","stem":"물과 기름을 나누는 두 도구 자료를 보고, ① 나눈 기름을 다시 써야 할 때와 ② 바다에 기름이 얇게 퍼졌을 때 각각 어떤 도구가 알맞은지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: ① 기름을 다시 써야 할 때는 스포이트가 알맞다. 위층 기름을 뽑아 다른 그릇에 옮기므로 그대로 다시 쓸 수 있다. ② 바다에 얇게 퍼진 기름에는 흡착포가 알맞다. 넓게 퍼진 기름에 대기만 하면 빨아들여 물을 깨끗하게 남긴다.","scoring_points":["①에 스포이트를 골랐는가","②에 흡착포를 골랐는가","각각의 까닭을 썼는가"]},"explanation":["다시 쓰면 스포이트예요.","얇게 퍼지면 흡착포예요.","까닭을 밝혀요."],"asset":{"type":"passage","lines":["스포이트 — 위층 기름을 뽑아 다른 비커에 옮긴다.","흡착포 — 핀셋으로 기름 위에 가볍게 대어 기름을 빨아들인다."],"title":"물과 기름을 나누는 두 도구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_basic#1','sci',5,2,'u1','L05','g5_2_sci_u1_L05_basic','lesson_basic','SC5-2-u1-C11',1,'mc','auto','소금과 모래를 나눌 때 이용하는 성질로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X18','SC5-2-u1-X33']::text[],false,'{"seq":1,"concept":"SC5-2-u1-C11","difficulty":1,"kind":"mc","stem":"소금과 모래를 나눌 때 이용하는 성질로 알맞은 것은 어느 것인가요?","options":[{"t":"소금은 물에 녹고 모래는 물에 녹지 않는다","correct":true},{"t":"소금은 모래보다 알갱이가 훨씬 크다","mis":"SC5-2-u1-X18"},{"t":"소금은 자석에 붙는다","mis":"SC5-2-u1-X33"},{"t":"모래는 물 위에 뜬다","mis":"SC5-2-u1-X33"}],"explanation":["물에 넣어 봐요.","소금은 녹아요.","모래는 안 녹아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_basic#2','sci',5,2,'u1','L05','g5_2_sci_u1_L05_basic','lesson_basic','SC5-2-u1-C12',1,'sa','auto','물에 녹는 물질과 녹지 않는 물질을 걸러서 나누는 방법을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-2-u1-C12","difficulty":1,"kind":"sa","stem":"물에 녹는 물질과 녹지 않는 물질을 걸러서 나누는 방법을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["거름"],"explanation":["거름종이를 써요.","걸러서 나눠요.","거름이에요."],"mis":"SC5-2-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_basic#3','sci',5,2,'u1','L05','g5_2_sci_u1_L05_basic','lesson_basic','SC5-2-u1-C12',1,'mc','auto','소금과 모래의 혼합물을 물에 넣어 저은 뒤 거름 장치로 걸렀어요. 거름종이 위에 남는 것은 어느 것인가요?',ARRAY['SC5-2-u1-X19']::text[],false,'{"seq":3,"concept":"SC5-2-u1-C12","difficulty":1,"kind":"mc","stem":"소금과 모래의 혼합물을 물에 넣어 저은 뒤 거름 장치로 걸렀어요. 거름종이 위에 남는 것은 어느 것인가요?","options":[{"t":"모래","correct":true},{"t":"소금","mis":"SC5-2-u1-X19"},{"t":"소금과 모래 모두","mis":"SC5-2-u1-X19"},{"t":"아무것도 남지 않는다","mis":"SC5-2-u1-X19"}],"explanation":["소금은 녹았어요.","모래는 안 녹아요.","모래가 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_basic#4','sci',5,2,'u1','L05','g5_2_sci_u1_L05_basic','lesson_basic','SC5-2-u1-C13',1,'ox','auto','소금물을 가열해 물을 증발시키면 소금이 남아요.',ARRAY['SC5-2-u1-X04']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C13","difficulty":1,"kind":"ox","stem":"소금물을 가열해 물을 증발시키면 소금이 남아요.","answer":"O","reason_options":[{"t":"물만 날아가고 녹아 있던 소금이 남기 때문에","correct":true},{"t":"가열하면 소금도 물과 함께 모두 날아가기 때문에","mis":"SC5-2-u1-X04"}],"mis":"SC5-2-u1-X04","explanation":["물이 증발해요.","소금은 남아요.","하얀 알갱이가 소금이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_basic#5','sci',5,2,'u1','L05','g5_2_sci_u1_L05_basic','lesson_basic','SC5-2-u1-C12',2,'mc','auto','소금과 모래의 혼합물을 나누는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X20','SC5-2-u1-X18']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C12","difficulty":2,"kind":"mc","stem":"소금과 모래의 혼합물을 나누는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"물에 녹이기 → 거름 → 증발","correct":true},{"t":"증발 → 물에 녹이기 → 거름","mis":"SC5-2-u1-X20"},{"t":"거름 → 증발 → 물에 녹이기","mis":"SC5-2-u1-X20"},{"t":"체로 거르기 → 증발","mis":"SC5-2-u1-X18"}],"explanation":["먼저 물에 녹여요.","모래를 걸러요.","소금물을 증발시켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_basic#6','sci',5,2,'u1','L05','g5_2_sci_u1_L05_basic','lesson_basic','SC5-2-u1-C13',2,'mc','auto','증발 실험에서 지켜야 할 것으로 알맞지 않은 것을 고르세요.',ARRAY['SC5-2-u1-X21']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C13","difficulty":2,"kind":"mc","stem":"증발 실험에서 지켜야 할 것으로 알맞지 않은 것을 고르세요.","options":[{"t":"전원을 끈 가열판을 바로 손으로 만진다","correct":true},{"t":"보안경과 면장갑을 낀다","mis":"SC5-2-u1-X21"},{"t":"증발 접시는 집게로 옮긴다","mis":"SC5-2-u1-X21"},{"t":"약하게 가열한다","mis":"SC5-2-u1-X21"}],"explanation":["가열판은 끈 뒤에도 뜨거워요.","만지면 데어요.","그것이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_basic#7','sci',5,2,'u1','L05','g5_2_sci_u1_L05_basic','lesson_basic','SC5-2-u1-C11',2,'mc','auto','소금과 모래의 혼합물을 체로 나누기 어려운 까닭은 어느 것인가요?',ARRAY['SC5-2-u1-X18','SC5-2-u1-X08']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C11","difficulty":2,"kind":"mc","stem":"소금과 모래의 혼합물을 체로 나누기 어려운 까닭은 어느 것인가요?","options":[{"t":"두 알갱이의 크기가 비슷해서","correct":true},{"t":"소금이 체에 닿으면 녹아서","mis":"SC5-2-u1-X18"},{"t":"모래가 체의 눈을 막아서","mis":"SC5-2-u1-X18"},{"t":"둘 다 흰색이라서","mis":"SC5-2-u1-X08"}],"explanation":["소금과 모래는 크기가 비슷해요.","체는 크기로 나눠요.","그래서 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_basic#8','sci',5,2,'u1','L05','g5_2_sci_u1_L05_basic','lesson_basic','SC5-2-u1-C12',2,'ox','auto','거름종이를 빠져나간 액체에는 소금이 녹아 있어요.',ARRAY['SC5-2-u1-X19']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C12","difficulty":2,"kind":"ox","stem":"거름종이를 빠져나간 액체에는 소금이 녹아 있어요.","answer":"O","reason_options":[{"t":"소금은 물에 녹아 물과 함께 거름종이를 지나가기 때문에","correct":true},{"t":"소금은 모두 거름종이 위에 걸렸기 때문에","mis":"SC5-2-u1-X19"}],"mis":"SC5-2-u1-X19","explanation":["소금은 녹아 있어요.","물과 함께 빠져나가요.","아래 액체는 소금물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_basic#9','sci',5,2,'u1','L05','g5_2_sci_u1_L05_basic','lesson_basic','SC5-2-u1-C14',2,'mc','auto','생활 속에서 나누기 자료에서 증발을 이용한 것은 어느 것인가요?',ARRAY['SC5-2-u1-X22']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C14","difficulty":2,"kind":"mc","stem":"생활 속에서 나누기 자료에서 증발을 이용한 것은 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"SC5-2-u1-X22"},{"t":"다","mis":"SC5-2-u1-X22"},{"t":"가와 다","mis":"SC5-2-u1-X22"}],"explanation":["가·다는 천으로 걸러요.","나는 햇빛과 바람이에요.","물이 증발해요."],"asset":{"type":"passage","lines":["가 — 장을 담근 뒤 천으로 걸러 간장을 얻는다.","나 — 바닷물을 넓은 바닥에 가두고 햇빛과 바람에 둔다.","다 — 굳은 우유 덩어리를 천으로 걸러 치즈를 만든다."],"title":"생활 속에서 나누기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_basic#10','sci',5,2,'u1','L05','g5_2_sci_u1_L05_basic','lesson_basic','SC5-2-u1-C12',3,'error','auto','거름 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X19','SC5-2-u1-X23']::text[],false,'{"seq":10,"concept":"SC5-2-u1-C12","difficulty":3,"kind":"error","stem":"거름 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「거름종이로 거르면 소금이 종이 위에 하얗게 남아.」","correct":true,"mis_target":"SC5-2-u1-X19"},{"t":"도하 — 「거름종이를 접어 깔때기에 물을 묻혀 붙여.」","mis":"SC5-2-u1-X23"},{"t":"미르 — 「깔때기 끝을 비커 옆면에 대야 튀지 않아.」","mis":"SC5-2-u1-X23"}],"explanation":["소금은 녹아 빠져나가요.","종이 위엔 모래가 남아요.","서윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_challenge#1','sci',5,2,'u1','L05','g5_2_sci_u1_L05_challenge','lesson_challenge','SC5-2-u1-C14',2,'match','auto','생활 속 예와 이용한 분리 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u1-C14","difficulty":2,"kind":"match","stem":"생활 속 예와 이용한 분리 방법을 알맞게 이으세요.","pairs":[{"l":"천으로 걸러 간장 얻기","r":"거름"},{"l":"염전에서 소금 얻기","r":"증발"},{"l":"강에서 조개 잡기","r":"체"},{"l":"국 위 기름 떠내기","r":"위에 뜬 것 걷어 내기"}],"mis":"SC5-2-u1-X22","explanation":["천은 거름이에요.","염전은 증발이에요.","조개는 체, 기름은 떠내기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_challenge#2','sci',5,2,'u1','L05','g5_2_sci_u1_L05_challenge','lesson_challenge','SC5-2-u1-C12',2,'mc','auto','거름 장치를 꾸미고 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X23']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C12","difficulty":2,"kind":"mc","stem":"거름 장치를 꾸미고 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"거름종이를 접어 깔때기에 물을 묻혀 붙이고, 유리 막대를 따라 천천히 붓는다","correct":true},{"t":"거름종이 없이 깔때기만 놓고 붓는다","mis":"SC5-2-u1-X23"},{"t":"혼합물을 한꺼번에 세게 쏟아붓는다","mis":"SC5-2-u1-X23"},{"t":"깔때기 끝을 비커 가운데 허공에 둔다","mis":"SC5-2-u1-X23"}],"explanation":["거름종이를 잘 붙여요.","유리 막대를 따라요.","천천히 부어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_challenge#3','sci',5,2,'u1','L05','g5_2_sci_u1_L05_challenge','lesson_challenge','SC5-2-u1-C11',3,'mc','auto','소금에 실수로 후추를 쏟았어요. 소금과 후추를 각각 얻는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X34','SC5-2-u1-X18','SC5-2-u1-X20']::text[],false,'{"seq":3,"concept":"SC5-2-u1-C11","difficulty":3,"kind":"mc","stem":"소금에 실수로 후추를 쏟았어요. 소금과 후추를 각각 얻는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"물에 넣어 저은 뒤 거름으로 후추를 거르고, 빠져나간 소금물을 증발시킨다","correct":true},{"t":"그대로 가열해 증발시킨다","mis":"SC5-2-u1-X34"},{"t":"체로 걸러 나눈다","mis":"SC5-2-u1-X18"},{"t":"물에 넣어 거름까지만 하고 끝낸다","mis":"SC5-2-u1-X20"}],"explanation":["후추는 물에 안 녹아요.","거름으로 후추를 얻어요.","증발로 소금을 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_challenge#4','sci',5,2,'u1','L05','g5_2_sci_u1_L05_challenge','lesson_challenge','SC5-2-u1-C13',3,'mc','auto','증발 접시를 가열한 뒤 하얀 알갱이가 남았어요. 이 알갱이에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X19','SC5-2-u1-X03','SC5-2-u1-X21']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C13","difficulty":3,"kind":"mc","stem":"증발 접시를 가열한 뒤 하얀 알갱이가 남았어요. 이 알갱이에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"소금물에 녹아 있던 소금이다","correct":true},{"t":"거름종이를 빠져나온 모래이다","mis":"SC5-2-u1-X19"},{"t":"가열해서 새로 생긴 물질이다","mis":"SC5-2-u1-X03"},{"t":"증발 접시가 녹은 것이다","mis":"SC5-2-u1-X21"}],"explanation":["물이 날아갔어요.","녹아 있던 것이 남아요.","소금이에요."],"asset":{"type":"passage","lines":["① 소금과 모래의 혼합물을 물이 담긴 비커에 넣고 저었다.","② 거름종이를 깔때기에 붙이고 ①을 천천히 부었다.","③ 거름종이를 빠져나간 액체를 증발 접시에 담았다.","④ 가열판으로 약하게 가열했다."],"title":"소금과 모래 나누기 실험 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_challenge#5','sci',5,2,'u1','L05','g5_2_sci_u1_L05_challenge','lesson_challenge','SC5-2-u1-C13',3,'ox','auto','증발 접시는 세게 가열할수록 빨리 끝나서 좋아요.',ARRAY['SC5-2-u1-X21']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C13","difficulty":3,"kind":"ox","stem":"증발 접시는 세게 가열할수록 빨리 끝나서 좋아요.","answer":"X","reason_options":[{"t":"세게 가열하면 액체가 튀어 위험하므로 약하게 가열해야 하기 때문에","correct":true},{"t":"빨리 끝내려면 세게 가열해야 하기 때문에","mis":"SC5-2-u1-X21"}],"mis":"SC5-2-u1-X21","explanation":["세게 하면 튀어요.","다칠 수 있어요.","약하게 가열해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_challenge#6','sci',5,2,'u1','L05','g5_2_sci_u1_L05_challenge','lesson_challenge','SC5-2-u1-C11',3,'error','auto','소금과 모래를 물에 넣은 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X04','SC5-2-u1-X20']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C11","difficulty":3,"kind":"error","stem":"소금과 모래를 물에 넣은 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"한결 — 「소금이 물에 들어가 없어졌으니 소금은 다시 얻을 수 없어.」","correct":true,"mis_target":"SC5-2-u1-X04"},{"t":"수빈 — 「소금은 물에 녹아 보이지 않을 뿐이야.」","mis":"SC5-2-u1-X04"},{"t":"태하 — 「물을 증발시키면 소금이 다시 나와.」","mis":"SC5-2-u1-X20"}],"explanation":["소금은 녹아 있어요.","증발시키면 얻어요.","한결의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_challenge#7','sci',5,2,'u1','L05','g5_2_sci_u1_L05_challenge','lesson_challenge','SC5-2-u1-C14',3,'mc','auto','바닷가에서 놀고 나니 신발에 하얀 알갱이가 묻어 있었어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X03','SC5-2-u1-X04','SC5-2-u1-X21']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C14","difficulty":3,"kind":"mc","stem":"바닷가에서 놀고 나니 신발에 하얀 알갱이가 묻어 있었어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"신발에 묻은 바닷물의 물이 증발하고 녹아 있던 소금이 남았다","correct":true},{"t":"모래가 하얗게 바뀌었다","mis":"SC5-2-u1-X03"},{"t":"바닷물의 소금은 물에 녹지 않아 처음부터 보였다","mis":"SC5-2-u1-X04"},{"t":"신발이 녹아 하얗게 되었다","mis":"SC5-2-u1-X21"}],"explanation":["바닷물엔 소금이 녹아 있어요.","물이 증발했어요.","소금이 남았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_challenge#8','sci',5,2,'u1','L05','g5_2_sci_u1_L05_challenge','lesson_challenge','SC5-2-u1-C21',4,'mc','auto','소금·모래·좁쌀이 섞인 혼합물을 모두 나누는 차례로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X34','SC5-2-u1-X20','SC5-2-u1-X12']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C21","difficulty":4,"kind":"mc","stem":"소금·모래·좁쌀이 섞인 혼합물을 모두 나누는 차례로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"체로 좁쌀을 나누고, 물에 녹여 거름으로 모래를 얻은 뒤, 소금물을 증발시킨다","correct":true},{"t":"먼저 가열해 증발시키고, 체로 거른 뒤 거름을 한다","mis":"SC5-2-u1-X34"},{"t":"물에 녹여 바로 증발시키고, 남은 것을 거른다","mis":"SC5-2-u1-X20"},{"t":"체로 좁쌀만 나누고 끝낸다","mis":"SC5-2-u1-X12"}],"explanation":["좁쌀은 크기로 나눠요.","모래는 거름으로요.","소금은 증발로요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_challenge#9','sci',5,2,'u1','L05','g5_2_sci_u1_L05_challenge','lesson_challenge','SC5-2-u1-C12',4,'mc','auto','거름 장치 없이 종이컵과 커피 필터만 있을 때 소금과 모래를 나누는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X18','SC5-2-u1-X21','SC5-2-u1-X19']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C12","difficulty":4,"kind":"mc","stem":"거름 장치 없이 종이컵과 커피 필터만 있을 때 소금과 모래를 나누는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바닥에 구멍 낸 종이컵에 커피 필터를 깔아 거르고, 빠져나간 소금물은 햇볕에 두어 증발시킨다","correct":true},{"t":"커피 필터에 마른 혼합물을 그대로 부어 흔든다","mis":"SC5-2-u1-X18"},{"t":"종이컵에 물과 혼합물을 넣고 그대로 마신다","mis":"SC5-2-u1-X21"},{"t":"커피 필터로 거른 뒤 거름종이 위의 것만 소금이라고 한다","mis":"SC5-2-u1-X19"}],"explanation":["커피 필터가 거름종이 역할이에요.","물에 녹여 걸러요.","햇볕으로 증발시켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L05_challenge#10','sci',5,2,'u1','L05','g5_2_sci_u1_L05_challenge','lesson_challenge','SC5-2-u1-C12',4,'essay','teacher','소금과 모래 나누기 실험 차례를 보고, 각 단계에서 무엇이 일어나는지와 이용한 성질을 쓰고, 가열할 때 지킬 안전 수칙을 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u1-C12","difficulty":4,"kind":"essay","stem":"소금과 모래 나누기 실험 차례를 보고, 각 단계에서 무엇이 일어나는지와 이용한 성질을 쓰고, 가열할 때 지킬 안전 수칙을 하나 쓰세요.","answer_guide":{"answer":"예: ①에서 소금은 물에 녹고 모래는 녹지 않는다. ②에서 녹지 않은 모래는 거름종이 위에 남고 소금물은 빠져나간다. ③·④에서 소금물을 가열하면 물이 증발하고 소금이 남는다. 소금은 물에 녹고 모래는 녹지 않는 성질을 이용했다. 가열할 때는 약하게 가열하고 증발 접시는 집게로 옮긴다.","scoring_points":["거름 단계에서 일어나는 일을 썼는가","증발 단계에서 일어나는 일을 썼는가","이용한 성질과 안전 수칙을 썼는가"]},"explanation":["녹이고 걸러요.","증발시켜요.","안전도 지켜요."],"asset":{"type":"passage","lines":["① 소금과 모래의 혼합물을 물이 담긴 비커에 넣고 저었다.","② 거름종이를 깔때기에 붙이고 ①을 천천히 부었다.","③ 거름종이를 빠져나간 액체를 증발 접시에 담았다.","④ 가열판으로 약하게 가열했다."],"title":"소금과 모래 나누기 실험 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_basic#1','sci',5,2,'u1','L06','g5_2_sci_u1_L06_basic','lesson_basic','SC5-2-u1-C15',1,'mc','auto','바닷물에서 소금 등을 걸러 마실 물을 만드는 장치는 어느 것인가요?',ARRAY['SC5-2-u1-X26']::text[],false,'{"seq":1,"concept":"SC5-2-u1-C15","difficulty":1,"kind":"mc","stem":"바닷물에서 소금 등을 걸러 마실 물을 만드는 장치는 어느 것인가요?","options":[{"t":"해수 담수화 장치","correct":true},{"t":"공기 청정기","mis":"SC5-2-u1-X26"},{"t":"인공지능 폐기물 선별 장치","mis":"SC5-2-u1-X26"},{"t":"전자레인지","mis":"SC5-2-u1-X26"}],"explanation":["바닷물이 재료예요.","마실 물을 만들어요.","해수 담수화 장치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_basic#2','sci',5,2,'u1','L06','g5_2_sci_u1_L06_basic','lesson_basic','SC5-2-u1-C16',1,'mc','auto','오염 물질을 걸러 깨끗한 공기를 내보내는 장치는 어느 것인가요?',ARRAY['SC5-2-u1-X26']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C16","difficulty":1,"kind":"mc","stem":"오염 물질을 걸러 깨끗한 공기를 내보내는 장치는 어느 것인가요?","options":[{"t":"공기 청정기","correct":true},{"t":"정수기","mis":"SC5-2-u1-X26"},{"t":"해수 담수화 장치","mis":"SC5-2-u1-X26"},{"t":"냉장고","mis":"SC5-2-u1-X26"}],"explanation":["공기에서 먼지를 걸러요.","필터가 있어요.","공기 청정기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_basic#3','sci',5,2,'u1','L06','g5_2_sci_u1_L06_basic','lesson_basic','SC5-2-u1-C17',1,'sa','auto','조사한 자료를 보고서에 쓸 때 어디에서 가져왔는지 꼭 밝혀야 해요. 이것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-2-u1-C17","difficulty":1,"kind":"sa","stem":"조사한 자료를 보고서에 쓸 때 어디에서 가져왔는지 꼭 밝혀야 해요. 이것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["출처"],"explanation":["자료를 가져온 곳이에요.","꼭 밝혀요.","출처예요."],"mis":"SC5-2-u1-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_basic#4','sci',5,2,'u1','L06','g5_2_sci_u1_L06_basic','lesson_basic','SC5-2-u1-C16',1,'ox','auto','정수기·마스크·공기 청정기도 혼합물의 분리를 이용한 장치예요.',ARRAY['SC5-2-u1-X25']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C16","difficulty":1,"kind":"ox","stem":"정수기·마스크·공기 청정기도 혼합물의 분리를 이용한 장치예요.","answer":"O","reason_options":[{"t":"물이나 공기에서 오염 물질을 나누어 걸러 내기 때문에","correct":true},{"t":"혼합물의 분리는 실험실에서만 쓰는 방법이기 때문에","mis":"SC5-2-u1-X25"}],"mis":"SC5-2-u1-X25","explanation":["물에서 오염 물질을 걸러요.","공기에서 먼지를 걸러요.","생활 속 분리 장치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_basic#5','sci',5,2,'u1','L06','g5_2_sci_u1_L06_basic','lesson_basic','SC5-2-u1-C15',2,'mc','auto','바닷물이 가득한 섬 마을에 마실 물이 모자란 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X04','SC5-2-u1-X24']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C15","difficulty":2,"kind":"mc","stem":"바닷물이 가득한 섬 마을에 마실 물이 모자란 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"바닷물에는 소금 등이 섞여 있어 그대로 마실 수 없어서","correct":true},{"t":"바닷물 속 소금은 녹아 없어져 맹물이라서","mis":"SC5-2-u1-X04"},{"t":"바닷물은 너무 차가워서","mis":"SC5-2-u1-X24"},{"t":"바닷물에는 물이 들어 있지 않아서","mis":"SC5-2-u1-X24"}],"explanation":["바닷물은 짜요.","소금 등이 섞였어요.","나누어야 마셔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_basic#6','sci',5,2,'u1','L06','g5_2_sci_u1_L06_basic','lesson_basic','SC5-2-u1-C16',2,'mc','auto','휴대용 정수 장치는 무엇으로 물속 오염 물질을 걸러 내나요?',ARRAY['SC5-2-u1-X26','SC5-2-u1-X33']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C16","difficulty":2,"kind":"mc","stem":"휴대용 정수 장치는 무엇으로 물속 오염 물질을 걸러 내나요?","options":[{"t":"여러 겹의 거름망","correct":true},{"t":"흡착포","mis":"SC5-2-u1-X26"},{"t":"증발 접시","mis":"SC5-2-u1-X26"},{"t":"자석","mis":"SC5-2-u1-X33"}],"explanation":["물이 지나가요.","여러 겹을 거쳐요.","거름망이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_basic#7','sci',5,2,'u1','L06','g5_2_sci_u1_L06_basic','lesson_basic','SC5-2-u1-C16',2,'mc','auto','혼합물의 분리를 이용한 장치 카드에서 인공지능 폐기물 선별 장치에 해당하는 것은 어느 것인가요?',ARRAY['SC5-2-u1-X26']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C16","difficulty":2,"kind":"mc","stem":"혼합물의 분리를 이용한 장치 카드에서 인공지능 폐기물 선별 장치에 해당하는 것은 어느 것인가요?","options":[{"t":"라","correct":true},{"t":"가","mis":"SC5-2-u1-X26"},{"t":"다","mis":"SC5-2-u1-X26"},{"t":"마","mis":"SC5-2-u1-X26"}],"explanation":["폐기물은 쓰레기예요.","카메라로 골라요.","라예요."],"asset":{"type":"passage","lines":["가 — 바닷물에서 소금 등을 걸러 마실 물을 만든다.","나 — 여러 겹 거름망으로 물속 오염 물질을 거른다.","다 — 필터로 공기 속 먼지를 거른다.","라 — 카메라로 보고 플라스틱·종이·유리를 골라 낸다.","마 — 쓰고 난 더러운 물을 나누어 다시 쓸 수 있게 한다."],"title":"혼합물의 분리를 이용한 장치 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_basic#8','sci',5,2,'u1','L06','g5_2_sci_u1_L06_basic','lesson_basic','SC5-2-u1-C16',2,'ox','auto','혼합물의 분리를 이용한 장치는 물질의 성질을 모두 바꾸어 줘요.',ARRAY['SC5-2-u1-X27']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C16","difficulty":2,"kind":"ox","stem":"혼합물의 분리를 이용한 장치는 물질의 성질을 모두 바꾸어 줘요.","answer":"X","reason_options":[{"t":"성질은 그대로 두고 섞인 것을 나누기만 하기 때문에","correct":true},{"t":"분리하면 물질이 새 물질로 바뀌기 때문에","mis":"SC5-2-u1-X27"}],"mis":"SC5-2-u1-X27","explanation":["분리는 나누는 거예요.","성질은 그대로예요.","바꾸지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_basic#9','sci',5,2,'u1','L06','g5_2_sci_u1_L06_basic','lesson_basic','SC5-2-u1-C17',2,'mc','auto','장치 조사 보고서를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X28']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C17","difficulty":2,"kind":"mc","stem":"장치 조사 보고서를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"장치 고르기 → 조사하기 → 보고서 쓰기 → 공유하기","correct":true},{"t":"공유하기 → 장치 고르기 → 보고서 쓰기 → 조사하기","mis":"SC5-2-u1-X28"},{"t":"보고서 쓰기 → 조사하기 → 장치 고르기 → 공유하기","mis":"SC5-2-u1-X28"},{"t":"조사하기 → 공유하기 → 장치 고르기 → 보고서 쓰기","mis":"SC5-2-u1-X28"}],"explanation":["먼저 장치를 골라요.","조사하고 써요.","마지막에 공유해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_basic#10','sci',5,2,'u1','L06','g5_2_sci_u1_L06_basic','lesson_basic','SC5-2-u1-C16',3,'error','auto','분리 장치를 조사하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X25','SC5-2-u1-X26']::text[],false,'{"seq":10,"concept":"SC5-2-u1-C16","difficulty":3,"kind":"error","stem":"분리 장치를 조사하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지율 — 「혼합물의 분리는 과학자가 실험실에서만 쓰는 방법이야.」","correct":true,"mis_target":"SC5-2-u1-X25"},{"t":"하온 — 「하수 처리 시설은 더러운 물을 나누어 다시 쓸 수 있게 해.」","mis":"SC5-2-u1-X26"},{"t":"리안 — 「선별 장치는 쓰레기에서 재활용품을 골라 내.」","mis":"SC5-2-u1-X26"}],"explanation":["정수기도 분리 장치예요.","생활 곳곳에 있어요.","지율의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_challenge#1','sci',5,2,'u1','L06','g5_2_sci_u1_L06_challenge','lesson_challenge','SC5-2-u1-C16',2,'match','auto','장치와 그 장치가 무엇에서 무엇을 나누는지 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u1-C16","difficulty":2,"kind":"match","stem":"장치와 그 장치가 무엇에서 무엇을 나누는지 알맞게 이으세요.","pairs":[{"l":"해수 담수화 장치","r":"바닷물에서 소금 등"},{"l":"정수 장치","r":"물에서 오염 물질"},{"l":"공기 정화 장치","r":"공기에서 먼지"},{"l":"폐기물 선별 장치","r":"쓰레기에서 재활용품"}],"mis":"SC5-2-u1-X26","explanation":["바닷물은 담수화예요.","물은 정수, 공기는 정화예요.","쓰레기는 선별이에요."],"asset":{"type":"passage","lines":["가 — 바닷물에서 소금 등을 걸러 마실 물을 만든다.","나 — 여러 겹 거름망으로 물속 오염 물질을 거른다.","다 — 필터로 공기 속 먼지를 거른다.","라 — 카메라로 보고 플라스틱·종이·유리를 골라 낸다.","마 — 쓰고 난 더러운 물을 나누어 다시 쓸 수 있게 한다."],"title":"혼합물의 분리를 이용한 장치 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_challenge#2','sci',5,2,'u1','L06','g5_2_sci_u1_L06_challenge','lesson_challenge','SC5-2-u1-C17',2,'mc','auto','보고서에 출처를 밝히는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X28']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C17","difficulty":2,"kind":"mc","stem":"보고서에 출처를 밝히는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자료를 만든 사람의 노력을 존중하고, 믿을 수 있는 자료인지 다른 사람도 확인할 수 있게 하려고","correct":true},{"t":"보고서를 길어 보이게 하려고","mis":"SC5-2-u1-X28"},{"t":"내가 직접 만든 자료처럼 보이게 하려고","mis":"SC5-2-u1-X28"},{"t":"출처는 밝히지 않아도 되므로 까닭이 없다","mis":"SC5-2-u1-X28"}],"explanation":["남이 만든 자료예요.","노력을 존중해요.","믿을 수 있는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_challenge#3','sci',5,2,'u1','L06','g5_2_sci_u1_L06_challenge','lesson_challenge','SC5-2-u1-C16',3,'mc','auto','구멍이 큰 거름망으로는 마스크를 만들 수 없는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X09','SC5-2-u1-X04']::text[],false,'{"seq":3,"concept":"SC5-2-u1-C16","difficulty":3,"kind":"mc","stem":"구멍이 큰 거름망으로는 마스크를 만들 수 없는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"구멍이 먼지보다 크면 작은 오염 물질이 빠져나가 나뉘지 않기 때문이다","correct":true},{"t":"구멍이 크면 공기가 지나가지 못하기 때문이다","mis":"SC5-2-u1-X09"},{"t":"구멍 크기와 마스크는 관계가 없기 때문이다","mis":"SC5-2-u1-X09"},{"t":"구멍이 크면 먼지가 녹아 없어지기 때문이다","mis":"SC5-2-u1-X04"}],"explanation":["마스크는 공기와 먼지를 나눠요.","먼지보다 구멍이 작아야 해요.","크면 먼지가 지나가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_challenge#4','sci',5,2,'u1','L06','g5_2_sci_u1_L06_challenge','lesson_challenge','SC5-2-u1-C16',3,'mc','auto','공기 청정기의 필터가 먼지를 거르는 방법과 가장 닮은 실험은 어느 것인가요?',ARRAY['SC5-2-u1-X26','SC5-2-u1-X25']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C16","difficulty":3,"kind":"mc","stem":"공기 청정기의 필터가 먼지를 거르는 방법과 가장 닮은 실험은 어느 것인가요?","options":[{"t":"체로 모래와 자갈 나누기","correct":true},{"t":"증발 접시로 소금 얻기","mis":"SC5-2-u1-X26"},{"t":"흡착포로 기름 흡수하기","mis":"SC5-2-u1-X26"},{"t":"말판 놀이로 물질 나누기","mis":"SC5-2-u1-X25"}],"explanation":["필터에는 작은 구멍이 있어요.","크기 차이로 걸러요.","체와 닮았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_challenge#5','sci',5,2,'u1','L06','g5_2_sci_u1_L06_challenge','lesson_challenge','SC5-2-u1-C15',3,'ox','auto','해수 담수화 장치는 바닷물에 소금을 더 넣어 마실 물을 만들어요.',ARRAY['SC5-2-u1-X24']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C15","difficulty":3,"kind":"ox","stem":"해수 담수화 장치는 바닷물에 소금을 더 넣어 마실 물을 만들어요.","answer":"X","reason_options":[{"t":"바닷물에서 소금 등을 나누어 걸러 내어 마실 물을 만들기 때문에","correct":true},{"t":"소금을 많이 넣을수록 마시기 좋은 물이 되기 때문에","mis":"SC5-2-u1-X24"}],"mis":"SC5-2-u1-X24","explanation":["바닷물은 이미 짜요.","소금 등을 걸러 내요.","마실 물을 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_challenge#6','sci',5,2,'u1','L06','g5_2_sci_u1_L06_challenge','lesson_challenge','SC5-2-u1-C17',3,'error','auto','조사 보고서를 쓰며 친구들이 말했어요. 알맞지 않은 의견은 누구의 것인가요?',ARRAY['SC5-2-u1-X28']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C17","difficulty":3,"kind":"error","stem":"조사 보고서를 쓰며 친구들이 말했어요. 알맞지 않은 의견은 누구의 것인가요?","options":[{"t":"보람 — 「누리집 글을 출처 없이 그대로 복사해 붙이자.」","correct":true,"mis_target":"SC5-2-u1-X28"},{"t":"유건 — 「장치가 만들어진 상황도 조사하자.」","mis":"SC5-2-u1-X28"},{"t":"채린 — 「찾은 내용을 내 말로 바꾸어 정리하자.」","mis":"SC5-2-u1-X28"}],"explanation":["출처를 밝혀요.","내 말로 정리해요.","보람의 의견이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_challenge#7','sci',5,2,'u1','L06','g5_2_sci_u1_L06_challenge','lesson_challenge','SC5-2-u1-C16',3,'mc','auto','혼합물의 분리를 이용한 장치가 지속가능한 삶에 도움이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X27','SC5-2-u1-X35']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C16","difficulty":3,"kind":"mc","stem":"혼합물의 분리를 이용한 장치가 지속가능한 삶에 도움이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"물을 다시 쓰고 쓰레기에서 자원을 골라 다시 써 한정된 자원을 아끼기 때문이다","correct":true},{"t":"장치를 쓰면 자원이 저절로 늘어나기 때문이다","mis":"SC5-2-u1-X27"},{"t":"편하기만 하면 되기 때문이다","mis":"SC5-2-u1-X35"},{"t":"물질을 새 물질로 바꾸어 주기 때문이다","mis":"SC5-2-u1-X27"}],"explanation":["물을 다시 써요.","자원을 골라 다시 써요.","자원을 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_challenge#8','sci',5,2,'u1','L06','g5_2_sci_u1_L06_challenge','lesson_challenge','SC5-2-u1-C16',4,'mc','auto','혼합물을 분리할 수 없다면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X35','SC5-2-u1-X25','SC5-2-u1-X03']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C16","difficulty":4,"kind":"mc","stem":"혼합물을 분리할 수 없다면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"깨끗한 물을 얻기 어려워 건강을 해치고, 재활용품을 나누지 못해 자원이 모자라고 환경이 오염된다","correct":true},{"t":"조금 불편할 뿐 달라지는 것은 없다","mis":"SC5-2-u1-X35"},{"t":"물과 공기가 저절로 깨끗해진다","mis":"SC5-2-u1-X25"},{"t":"모든 물질이 한 가지 물질로 바뀐다","mis":"SC5-2-u1-X03"}],"explanation":["물을 거를 수 없어요.","쓰레기를 나눌 수 없어요.","건강과 환경이 위험해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_challenge#9','sci',5,2,'u1','L06','g5_2_sci_u1_L06_challenge','lesson_challenge','SC5-2-u1-C15',4,'mc','auto','가뭄이 잦은 섬 마을에 가장 먼저 필요한 장치와 그 까닭을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X26','SC5-2-u1-X24']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C15","difficulty":4,"kind":"mc","stem":"가뭄이 잦은 섬 마을에 가장 먼저 필요한 장치와 그 까닭을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"해수 담수화 장치 — 둘러싼 바닷물로 마실 물을 만들 수 있어서","correct":true},{"t":"공기 청정기 — 바닷물을 마실 물로 바꾸어서","mis":"SC5-2-u1-X26"},{"t":"폐기물 선별 장치 — 바닷물에서 소금을 걸러서","mis":"SC5-2-u1-X26"},{"t":"장치 없이 바닷물을 그대로 마시면 된다","mis":"SC5-2-u1-X24"}],"explanation":["가뭄이라 물이 모자라요.","바닷물은 많아요.","해수 담수화 장치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L06_challenge#10','sci',5,2,'u1','L06','g5_2_sci_u1_L06_challenge','lesson_challenge','SC5-2-u1-C16',4,'essay','teacher','혼합물의 분리를 이용한 장치 카드 가운데 하나를 골라, 무엇에서 무엇을 나누는지, 이 단원의 어떤 실험과 닮았는지, 우리 삶에 주는 도움을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u1-C16","difficulty":4,"kind":"essay","stem":"혼합물의 분리를 이용한 장치 카드 가운데 하나를 골라, 무엇에서 무엇을 나누는지, 이 단원의 어떤 실험과 닮았는지, 우리 삶에 주는 도움을 쓰세요.","answer_guide":{"answer":"예: 나(정수 장치)를 골랐다. 물에서 오염 물질을 나눈다. 여러 겹 거름망으로 거르니 거름 장치로 모래를 거른 실험과 닮았다. 깨끗한 물을 마실 수 있게 해 건강을 지키고, 물을 아껴 쓰게 도와준다.","scoring_points":["무엇에서 무엇을 나누는지 썼는가","닮은 실험을 바르게 이었는가","삶에 주는 도움을 썼는가"]},"explanation":["장치를 골라요.","실험과 이어요.","도움을 써요."],"asset":{"type":"passage","lines":["가 — 바닷물에서 소금 등을 걸러 마실 물을 만든다.","나 — 여러 겹 거름망으로 물속 오염 물질을 거른다.","다 — 필터로 공기 속 먼지를 거른다.","라 — 카메라로 보고 플라스틱·종이·유리를 골라 낸다.","마 — 쓰고 난 더러운 물을 나누어 다시 쓸 수 있게 한다."],"title":"혼합물의 분리를 이용한 장치 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_basic#1','sci',5,2,'u1','L07','g5_2_sci_u1_L07_basic','lesson_basic','SC5-2-u1-C18',1,'mc','auto','분리 장치를 소개하는 포스터에서 가장 크게 드러나야 하는 것은 어느 것인가요?',ARRAY['SC5-2-u1-X29','SC5-2-u1-X30']::text[],false,'{"seq":1,"concept":"SC5-2-u1-C18","difficulty":1,"kind":"mc","stem":"분리 장치를 소개하는 포스터에서 가장 크게 드러나야 하는 것은 어느 것인가요?","options":[{"t":"어떤 방법으로 혼합물을 분리하는지","correct":true},{"t":"반짝이는 꾸미기 그림","mis":"SC5-2-u1-X29"},{"t":"모둠 이름","mis":"SC5-2-u1-X29"},{"t":"모둠원의 집 주소","mis":"SC5-2-u1-X30"}],"explanation":["포스터는 장치를 알려요.","분리 방법이 핵심이에요.","분리 방법이 크게 보여야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_basic#2','sci',5,2,'u1','L07','g5_2_sci_u1_L07_basic','lesson_basic','SC5-2-u1-C18',1,'mc','auto','포스터를 만드는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X29']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C18","difficulty":1,"kind":"mc","stem":"포스터를 만드는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"계획하기 → 해 보기 → 나누기","correct":true},{"t":"나누기 → 계획하기 → 해 보기","mis":"SC5-2-u1-X29"},{"t":"해 보기 → 나누기 → 계획하기","mis":"SC5-2-u1-X29"},{"t":"나누기 → 해 보기 → 계획하기","mis":"SC5-2-u1-X29"}],"explanation":["먼저 계획해요.","그다음 만들어요.","마지막에 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_basic#3','sci',5,2,'u1','L07','g5_2_sci_u1_L07_basic','lesson_basic','SC5-2-u1-C18',1,'sa','auto','장치가 어떤 상황에서 왜 만들어졌는지를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-2-u1-C18","difficulty":1,"kind":"sa","stem":"장치가 어떤 상황에서 왜 만들어졌는지를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["개발 배경","개발배경"],"explanation":["만든 까닭이에요.","그때 상황이에요.","개발 배경이에요."],"mis":"SC5-2-u1-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_basic#4','sci',5,2,'u1','L07','g5_2_sci_u1_L07_basic','lesson_basic','SC5-2-u1-C19',1,'ox','auto','다른 모둠 포스터 댓글에 친구의 집 주소를 써도 괜찮아요.',ARRAY['SC5-2-u1-X30']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C19","difficulty":1,"kind":"ox","stem":"다른 모둠 포스터 댓글에 친구의 집 주소를 써도 괜찮아요.","answer":"X","reason_options":[{"t":"개인 정보는 누리망에 올리면 안 되기 때문에","correct":true},{"t":"친한 친구의 주소라면 괜찮기 때문에","mis":"SC5-2-u1-X30"}],"mis":"SC5-2-u1-X30","explanation":["주소는 개인 정보예요.","누구나 볼 수 있어요.","쓰면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_basic#5','sci',5,2,'u1','L07','g5_2_sci_u1_L07_basic','lesson_basic','SC5-2-u1-C19',2,'mc','auto','포스터에 달린 댓글 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X30']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C19","difficulty":2,"kind":"mc","stem":"포스터에 달린 댓글 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"댓글 ㉰","correct":true},{"t":"댓글 ㉯","mis":"SC5-2-u1-X30"},{"t":"댓글 ㉱","mis":"SC5-2-u1-X30"},{"t":"㉯와 ㉱","mis":"SC5-2-u1-X30"}],"explanation":["새로 안 점을 썼어요.","바르고 고운 말이에요.","㉰가 알맞아요."],"asset":{"type":"passage","lines":["댓글 ㉮ 「거름망이 몇 겹인지 그림으로 보여 주면 더 좋겠어요.」","댓글 ㉯ 「별로야.」","댓글 ㉰ 「공기 정화 장치 필터도 체랑 닮았다는 걸 새로 알았어요!」","댓글 ㉱ 「이거 만든 사람 우리 옆집 사는 애다.」"],"title":"포스터에 달린 댓글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_basic#6','sci',5,2,'u1','L07','g5_2_sci_u1_L07_basic','lesson_basic','SC5-2-u1-C18',2,'mc','auto','분리 장치 포스터에 넣지 않아야 하는 것은 어느 것인가요?',ARRAY['SC5-2-u1-X29','SC5-2-u1-X28']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C18","difficulty":2,"kind":"mc","stem":"분리 장치 포스터에 넣지 않아야 하는 것은 어느 것인가요?","options":[{"t":"모둠원의 전화번호","correct":true},{"t":"어떤 방법으로 무엇을 나누는지","mis":"SC5-2-u1-X29"},{"t":"장치가 개발된 상황","mis":"SC5-2-u1-X29"},{"t":"가져온 자료의 출처","mis":"SC5-2-u1-X28"}],"explanation":["개인 정보는 빼요.","나머지는 꼭 넣어요.","전화번호를 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_basic#7','sci',5,2,'u1','L07','g5_2_sci_u1_L07_basic','lesson_basic','SC5-2-u1-C18',2,'mc','auto','휴대용 정수 장치 포스터의 가운데에 가장 크게 둘 말로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X29']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C18","difficulty":2,"kind":"mc","stem":"휴대용 정수 장치 포스터의 가운데에 가장 크게 둘 말로 알맞은 것은 어느 것인가요?","options":[{"t":"여러 겹 거름망으로 오염 물질을 걸러요","correct":true},{"t":"멋진 물병","mis":"SC5-2-u1-X29"},{"t":"우리 모둠 최고","mis":"SC5-2-u1-X29"},{"t":"가격이 싸요","mis":"SC5-2-u1-X29"}],"explanation":["분리 방법이 보여야 해요.","거름망으로 걸러요.","그 말을 크게 둬요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_basic#8','sci',5,2,'u1','L07','g5_2_sci_u1_L07_basic','lesson_basic','SC5-2-u1-C18',2,'ox','auto','포스터에는 장치 이름과 사진만 크게 넣으면 충분해요.',ARRAY['SC5-2-u1-X29']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C18","difficulty":2,"kind":"ox","stem":"포스터에는 장치 이름과 사진만 크게 넣으면 충분해요.","answer":"X","reason_options":[{"t":"무엇을 무엇에서 어떻게 나누는지가 드러나야 하기 때문에","correct":true},{"t":"사진만 보면 누구나 분리 방법을 알 수 있기 때문에","mis":"SC5-2-u1-X29"}],"mis":"SC5-2-u1-X29","explanation":["이름과 사진만으론 부족해요.","분리 방법이 있어야 해요.","어떻게 나누는지 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_basic#9','sci',5,2,'u1','L07','g5_2_sci_u1_L07_basic','lesson_basic','SC5-2-u1-C19',2,'mc','auto','모둠에서 포스터를 만들 때 바른 태도는 어느 것인가요?',ARRAY['SC5-2-u1-X29','SC5-2-u1-X28']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C19","difficulty":2,"kind":"mc","stem":"모둠에서 포스터를 만들 때 바른 태도는 어느 것인가요?","options":[{"t":"자료 정리·글쓰기·그림·발표 등을 나누어 맡아 모두 참여한다","correct":true},{"t":"잘하는 한 사람이 혼자 다 만든다","mis":"SC5-2-u1-X29"},{"t":"꾸미기에 시간을 다 쓴다","mis":"SC5-2-u1-X29"},{"t":"다른 모둠 포스터를 그대로 따라 한다","mis":"SC5-2-u1-X28"}],"explanation":["모두의 포스터예요.","역할을 나눠요.","모두 참여해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_basic#10','sci',5,2,'u1','L07','g5_2_sci_u1_L07_basic','lesson_basic','SC5-2-u1-C18',3,'error','auto','포스터를 만들며 친구들이 말했어요. 알맞지 않은 의견은 누구의 것인가요?',ARRAY['SC5-2-u1-X28','SC5-2-u1-X29']::text[],false,'{"seq":10,"concept":"SC5-2-u1-C18","difficulty":3,"kind":"error","stem":"포스터를 만들며 친구들이 말했어요. 알맞지 않은 의견은 누구의 것인가요?","options":[{"t":"지환 — 「누리망에서 찾은 멋진 사진은 출처 없이 그대로 쓰자.」","correct":true,"mis_target":"SC5-2-u1-X28"},{"t":"소담 — 「분리 방법을 화살표 그림으로 보여 주자.」","mis":"SC5-2-u1-X29"},{"t":"은재 — 「개발 배경을 짧게 한 줄로 쓰자.」","mis":"SC5-2-u1-X29"}],"explanation":["사진에도 출처가 있어요.","밝히고 써요.","지환의 의견이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_challenge#1','sci',5,2,'u1','L07','g5_2_sci_u1_L07_challenge','lesson_challenge','SC5-2-u1-C18',2,'match','auto','햇살 모둠 포스터 계획을 보고 포스터의 자리와 넣을 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u1-C18","difficulty":2,"kind":"match","stem":"햇살 모둠 포스터 계획을 보고 포스터의 자리와 넣을 내용을 알맞게 이으세요.","pairs":[{"l":"맨 위","r":"장치 이름"},{"l":"가운데","r":"분리 방법"},{"l":"아래","r":"개발 배경"},{"l":"맨 아래","r":"출처"}],"mis":"SC5-2-u1-X29","explanation":["맨 위는 이름이에요.","가운데는 분리 방법이에요.","아래는 배경과 출처예요."],"asset":{"type":"passage","lines":["맨 위 — 장치 이름: 휴대용 정수 장치","가운데 — 여러 겹 거름망으로 오염 물질을 걸러요(화살표 그림)","아래 — 깨끗한 물을 구하기 어려운 곳을 위해 만들었어요","맨 아래 — 가져온 곳: 과학관 누리집"],"title":"햇살 모둠 포스터 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_challenge#2','sci',5,2,'u1','L07','g5_2_sci_u1_L07_challenge','lesson_challenge','SC5-2-u1-C19',2,'mc','auto','어느 모둠 포스터에 「멋져요」 댓글만 다섯 개 달렸어요. 포스터를 더 좋게 만드는 댓글로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X30']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C19","difficulty":2,"kind":"mc","stem":"어느 모둠 포스터에 「멋져요」 댓글만 다섯 개 달렸어요. 포스터를 더 좋게 만드는 댓글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「거름망이 몇 겹인지 그림으로 보여 주면 거름 원리가 더 잘 보일 것 같아요.」","correct":true},{"t":"「멋져요.」","mis":"SC5-2-u1-X30"},{"t":"「별로예요, 다시 해요.」","mis":"SC5-2-u1-X30"},{"t":"「우리 모둠이 더 잘했어요.」","mis":"SC5-2-u1-X30"}],"explanation":["구체적인 점을 짚어요.","고칠 방향을 알려요.","다음 포스터가 나아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_challenge#3','sci',5,2,'u1','L07','g5_2_sci_u1_L07_challenge','lesson_challenge','SC5-2-u1-C18',3,'mc','auto','정수 장치 포스터의 분리 방법을 이 단원 실험과 이어 설명할 때 가장 닮은 실험은 어느 것인가요?',ARRAY['SC5-2-u1-X33','SC5-2-u1-X29','SC5-2-u1-X20']::text[],false,'{"seq":3,"concept":"SC5-2-u1-C18","difficulty":3,"kind":"mc","stem":"정수 장치 포스터의 분리 방법을 이 단원 실험과 이어 설명할 때 가장 닮은 실험은 어느 것인가요?","options":[{"t":"거름 장치로 모래를 거른 실험","correct":true},{"t":"스포이트로 기름을 뽑은 실험","mis":"SC5-2-u1-X33"},{"t":"말판 놀이","mis":"SC5-2-u1-X29"},{"t":"증발 접시를 가열한 실험만","mis":"SC5-2-u1-X20"}],"explanation":["정수 장치는 거름망이 있어요.","걸러서 나눠요.","거름 실험과 닮았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_challenge#4','sci',5,2,'u1','L07','g5_2_sci_u1_L07_challenge','lesson_challenge','SC5-2-u1-C18',3,'mc','auto','해수 담수화 장치 포스터의 「분리 방법」 칸에 들어갈 말로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X24','SC5-2-u1-X26']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C18","difficulty":3,"kind":"mc","stem":"해수 담수화 장치 포스터의 「분리 방법」 칸에 들어갈 말로 알맞은 것은 어느 것인가요?","options":[{"t":"바닷물에서 소금 등을 걸러 마실 물을 만들어요","correct":true},{"t":"바닷물에 소금을 넣어 짜게 만들어요","mis":"SC5-2-u1-X24"},{"t":"공기 속 먼지를 걸러요","mis":"SC5-2-u1-X26"},{"t":"플라스틱을 카메라로 골라요","mis":"SC5-2-u1-X26"}],"explanation":["재료는 바닷물이에요.","소금 등을 걸러요.","마실 물이 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_challenge#5','sci',5,2,'u1','L07','g5_2_sci_u1_L07_challenge','lesson_challenge','SC5-2-u1-C18',3,'ox','auto','완성한 포스터를 옆 모둠에 잠깐만 보여 주고 무엇을 나누는 장치인지 맞혀 보게 하는 것은 좋은 점검 방법이에요.',ARRAY['SC5-2-u1-X29']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C18","difficulty":3,"kind":"ox","stem":"완성한 포스터를 옆 모둠에 잠깐만 보여 주고 무엇을 나누는 장치인지 맞혀 보게 하는 것은 좋은 점검 방법이에요.","answer":"O","reason_options":[{"t":"분리 방법이 한눈에 보이는지 확인할 수 있기 때문에","correct":true},{"t":"포스터는 오래 들여다봐야만 알 수 있어야 좋기 때문에","mis":"SC5-2-u1-X29"}],"mis":"SC5-2-u1-X29","explanation":["포스터는 한눈에 보여야 해요.","잠깐 보고 알면 성공이에요.","좋은 점검 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_challenge#6','sci',5,2,'u1','L07','g5_2_sci_u1_L07_challenge','lesson_challenge','SC5-2-u1-C19',3,'error','auto','포스터에 단 댓글들이에요. 알맞지 않은 댓글은 누구의 것인가요?',ARRAY['SC5-2-u1-X30']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C19","difficulty":3,"kind":"error","stem":"포스터에 단 댓글들이에요. 알맞지 않은 댓글은 누구의 것인가요?","options":[{"t":"나윤 — 「이 모둠 포스터는 별로야.」","correct":true,"mis_target":"SC5-2-u1-X30"},{"t":"시온 — 「공기 정화 장치 필터는 몇 겹인지 궁금해요.」","mis":"SC5-2-u1-X30"},{"t":"준혁 — 「분리 방법이 크게 보여서 이해가 잘 됐어요.」","mis":"SC5-2-u1-X30"}],"explanation":["까닭 없는 말이에요.","도움이 안 돼요.","나윤의 댓글이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_challenge#7','sci',5,2,'u1','L07','g5_2_sci_u1_L07_challenge','lesson_challenge','SC5-2-u1-C18',3,'mc','auto','저학년 동생들이 볼 포스터라면 무엇을 바꾸는 것이 가장 알맞은가요?',ARRAY['SC5-2-u1-X29']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C18","difficulty":3,"kind":"mc","stem":"저학년 동생들이 볼 포스터라면 무엇을 바꾸는 것이 가장 알맞은가요?","options":[{"t":"어려운 낱말을 쉬운 말로 바꾸고 분리 과정을 그림 화살표로 보여 준다","correct":true},{"t":"글씨를 아주 작게 해 내용을 많이 넣는다","mis":"SC5-2-u1-X29"},{"t":"분리 방법을 빼고 그림만 넣는다","mis":"SC5-2-u1-X29"},{"t":"어려운 낱말을 더 많이 넣는다","mis":"SC5-2-u1-X29"}],"explanation":["보는 사람을 생각해요.","쉬운 말로 바꿔요.","그림으로 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_challenge#8','sci',5,2,'u1','L07','g5_2_sci_u1_L07_challenge','lesson_challenge','SC5-2-u1-C18',4,'mc','auto','분리 장치를 포스터로 만들어 공유하는 목적으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X29','SC5-2-u1-X30']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C18","difficulty":4,"kind":"mc","stem":"분리 장치를 포스터로 만들어 공유하는 목적으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"분리 기술의 쓸모와 가치를 많은 사람이 한눈에 알게 하려고","correct":true},{"t":"꾸미기 실력을 뽐내려고","mis":"SC5-2-u1-X29"},{"t":"장치를 팔려고","mis":"SC5-2-u1-X29"},{"t":"친구들의 개인 정보를 모으려고","mis":"SC5-2-u1-X30"}],"explanation":["포스터는 알리는 거예요.","분리 기술을 소개해요.","가치를 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_challenge#9','sci',5,2,'u1','L07','g5_2_sci_u1_L07_challenge','lesson_challenge','SC5-2-u1-C19',4,'mc','auto','공유 플랫폼에 포스터를 올리고 댓글을 달 때의 바른 태도를 모두 담은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X30','SC5-2-u1-X28']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C19","difficulty":4,"kind":"mc","stem":"공유 플랫폼에 포스터를 올리고 댓글을 달 때의 바른 태도를 모두 담은 것은 어느 것인가요?","options":[{"t":"바르고 고운 말을 쓰고, 출처를 밝히며, 개인 정보는 올리지 않는다","correct":true},{"t":"재미있으면 흉보는 말도 괜찮다","mis":"SC5-2-u1-X30"},{"t":"출처는 빼고 사진을 많이 올린다","mis":"SC5-2-u1-X28"},{"t":"친구 이름과 연락처를 함께 올린다","mis":"SC5-2-u1-X30"}],"explanation":["고운 말을 써요.","출처를 밝혀요.","개인 정보는 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L07_challenge#10','sci',5,2,'u1','L07','g5_2_sci_u1_L07_challenge','lesson_challenge','SC5-2-u1-C18',4,'essay','teacher','우리 모둠이 소개할 분리 장치를 하나 골라, 포스터의 맨 위·가운데·아래·맨 아래에 무엇을 넣을지 쓰고, 가운데 내용을 그렇게 정한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u1-C18","difficulty":4,"kind":"essay","stem":"우리 모둠이 소개할 분리 장치를 하나 골라, 포스터의 맨 위·가운데·아래·맨 아래에 무엇을 넣을지 쓰고, 가운데 내용을 그렇게 정한 까닭을 쓰세요.","answer_guide":{"answer":"예: 해수 담수화 장치를 골랐다. 맨 위 — 「해수 담수화 장치」. 가운데 — 「바닷물에서 소금 등을 걸러 마실 물을 만들어요」와 화살표 그림. 아래 — 가뭄이 들거나 섬처럼 물이 모자란 곳을 위해 만들었다. 맨 아래 — 가져온 누리집. 포스터를 본 친구가 무엇을 무엇에서 어떻게 나누는지 바로 알아야 하기 때문에 가운데에 분리 방법을 넣었다.","scoring_points":["장치를 하나 골랐는가","네 자리에 넣을 내용을 썼는가","가운데에 분리 방법을 둔 까닭을 썼는가"]},"explanation":["장치를 골라요.","네 자리를 채워요.","분리 방법이 가운데예요."],"asset":{"type":"passage","lines":["맨 위 — 장치 이름: 휴대용 정수 장치","가운데 — 여러 겹 거름망으로 오염 물질을 걸러요(화살표 그림)","아래 — 깨끗한 물을 구하기 어려운 곳을 위해 만들었어요","맨 아래 — 가져온 곳: 과학관 누리집"],"title":"햇살 모둠 포스터 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_basic#1','sci',5,2,'u1','L08','g5_2_sci_u1_L08_basic','lesson_basic','SC5-2-u1-C20',1,'mc','auto','새활용의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X31','SC5-2-u1-X32']::text[],false,'{"seq":1,"concept":"SC5-2-u1-C20","difficulty":1,"kind":"mc","stem":"새활용의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"버려지는 물건에 아이디어나 디자인을 더해 새로운 가치를 만드는 것","correct":true},{"t":"쓴 물건을 녹이거나 부수어 다시 쓰는 것","mis":"SC5-2-u1-X31"},{"t":"쓰레기를 땅에 묻는 것","mis":"SC5-2-u1-X32"},{"t":"낡은 물건을 고치지 않고 그대로 다시 쓰는 것","mis":"SC5-2-u1-X32"}],"explanation":["버려질 물건이에요.","아이디어를 더해요.","새 가치를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_basic#2','sci',5,2,'u1','L08','g5_2_sci_u1_L08_basic','lesson_basic','SC5-2-u1-C20',1,'sa','auto','버려지는 물건에 아이디어나 디자인을 더해 새로운 가치를 만드는 것을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-2-u1-C20","difficulty":1,"kind":"sa","stem":"버려지는 물건에 아이디어나 디자인을 더해 새로운 가치를 만드는 것을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["새활용"],"explanation":["버림에서 쓰임으로예요.","재활용과 달라요.","새활용이에요."],"mis":"SC5-2-u1-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_basic#3','sci',5,2,'u1','L08','g5_2_sci_u1_L08_basic','lesson_basic','SC5-2-u1-C21',1,'mc','auto','모래와 자갈을 나눌 때 이용하는 성질은 어느 것인가요?',ARRAY['SC5-2-u1-X33','SC5-2-u1-X08']::text[],false,'{"seq":3,"concept":"SC5-2-u1-C21","difficulty":1,"kind":"mc","stem":"모래와 자갈을 나눌 때 이용하는 성질은 어느 것인가요?","options":[{"t":"알갱이의 크기 차이","correct":true},{"t":"물에 녹는 성질","mis":"SC5-2-u1-X33"},{"t":"알갱이의 색깔","mis":"SC5-2-u1-X08"},{"t":"자석에 붙는 성질","mis":"SC5-2-u1-X33"}],"explanation":["모래는 작아요.","자갈은 커요.","크기 차이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_basic#4','sci',5,2,'u1','L08','g5_2_sci_u1_L08_basic','lesson_basic','SC5-2-u1-C21',1,'ox','auto','물과 기름처럼 섞이지 않는 액체 혼합물은 스포이트로 나눌 수 있어요.',ARRAY['SC5-2-u1-X33']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C21","difficulty":1,"kind":"ox","stem":"물과 기름처럼 섞이지 않는 액체 혼합물은 스포이트로 나눌 수 있어요.","answer":"O","reason_options":[{"t":"위층 액체만 뽑아 다른 그릇으로 옮길 수 있기 때문에","correct":true},{"t":"스포이트는 고체 알갱이만 나누는 도구이기 때문에","mis":"SC5-2-u1-X33"}],"mis":"SC5-2-u1-X33","explanation":["기름은 위에 있어요.","스포이트로 뽑아요.","나눌 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_basic#5','sci',5,2,'u1','L08','g5_2_sci_u1_L08_basic','lesson_basic','SC5-2-u1-C20',2,'mc','auto','페트병 뚜껑으로 벽화를 만들 때 가장 먼저 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X31','SC5-2-u1-X32']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C20","difficulty":2,"kind":"mc","stem":"페트병 뚜껑으로 벽화를 만들 때 가장 먼저 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"뚜껑을 씻어 색깔별로 나누어 모은다","correct":true},{"t":"뚜껑을 모두 녹인다","mis":"SC5-2-u1-X31"},{"t":"뚜껑을 다른 쓰레기와 섞어 둔다","mis":"SC5-2-u1-X32"},{"t":"뚜껑을 그냥 버린다","mis":"SC5-2-u1-X32"}],"explanation":["재료부터 모아요.","색깔별로 나눠요.","그다음 꾸며요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_basic#6','sci',5,2,'u1','L08','g5_2_sci_u1_L08_basic','lesson_basic','SC5-2-u1-C21',2,'blank','auto','혼합물의 분리 정리판에서 ㉢에 들어갈 말은 어느 것인가요?',ARRAY['SC5-2-u1-X20','SC5-2-u1-X33']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C21","difficulty":2,"kind":"blank","stem":"혼합물의 분리 정리판에서 ㉢에 들어갈 말은 어느 것인가요?","options":[{"t":"증발","correct":true},{"t":"체","mis":"SC5-2-u1-X20"},{"t":"흡착포","mis":"SC5-2-u1-X33"},{"t":"스포이트","mis":"SC5-2-u1-X33"}],"explanation":["소금과 모래 줄이에요.","거름 다음이에요.","증발이에요."],"asset":{"type":"passage","lines":["모래와 자갈 — (㉠) 차이 — 체","물과 기름 — 섞이지 않고 위에 뜸 — (㉡)·흡착포","소금과 모래 — 물에 녹는지 — 거름 → (㉢)"],"title":"혼합물의 분리 정리판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_basic#7','sci',5,2,'u1','L08','g5_2_sci_u1_L08_basic','lesson_basic','SC5-2-u1-C20',2,'mc','auto','다시 쓰는 여러 방법 자료에서 새활용이 아닌 것은 어느 것인가요?',ARRAY['SC5-2-u1-X31']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C20","difficulty":2,"kind":"mc","stem":"다시 쓰는 여러 방법 자료에서 새활용이 아닌 것은 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"SC5-2-u1-X31"},{"t":"다","mis":"SC5-2-u1-X31"},{"t":"라","mis":"SC5-2-u1-X31"}],"explanation":["가는 부수고 녹여요.","그것은 재활용이에요.","나·다·라가 새활용이에요."],"asset":{"type":"passage","lines":["가 — 페트병을 잘게 부수고 녹여 옷감을 만든다.","나 — 안 쓰는 청바지로 가방을 만든다.","다 — 페트병 뚜껑을 색깔별로 모아 벽화를 만든다.","라 — 플라스틱 병 모양을 살려 물방울 조명을 만든다."],"title":"다시 쓰는 여러 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_basic#8','sci',5,2,'u1','L08','g5_2_sci_u1_L08_basic','lesson_basic','SC5-2-u1-C20',2,'ox','auto','재활용과 새활용은 같은 뜻의 말이에요.',ARRAY['SC5-2-u1-X31']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C20","difficulty":2,"kind":"ox","stem":"재활용과 새활용은 같은 뜻의 말이에요.","answer":"X","reason_options":[{"t":"재활용은 녹이거나 부수어 변형하고, 새활용은 아이디어를 더해 새 가치를 만들기 때문에","correct":true},{"t":"둘 다 다시 쓰는 것이니 똑같기 때문에","mis":"SC5-2-u1-X31"}],"mis":"SC5-2-u1-X31","explanation":["재활용은 변형해요.","새활용은 아이디어를 더해요.","서로 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_basic#9','sci',5,2,'u1','L08','g5_2_sci_u1_L08_basic','lesson_basic','SC5-2-u1-C21',2,'mc','auto','좁쌀이 담긴 그릇에 소금을 떨어뜨렸어요. 좁쌀만 얻는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X34','SC5-2-u1-X33']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C21","difficulty":2,"kind":"mc","stem":"좁쌀이 담긴 그릇에 소금을 떨어뜨렸어요. 좁쌀만 얻는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"물에 넣어 소금을 녹인 뒤 체로 거른다","correct":true},{"t":"그대로 증발 접시에 넣고 가열한다","mis":"SC5-2-u1-X34"},{"t":"흡착포를 올려놓는다","mis":"SC5-2-u1-X33"},{"t":"자석을 가까이 한다","mis":"SC5-2-u1-X33"}],"explanation":["소금은 물에 녹아요.","좁쌀은 체에 남아요.","녹이고 체로 걸러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_basic#10','sci',5,2,'u1','L08','g5_2_sci_u1_L08_basic','lesson_basic','SC5-2-u1-C21',3,'error','auto','단원을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X13','SC5-2-u1-X03','SC5-2-u1-X33']::text[],false,'{"seq":10,"concept":"SC5-2-u1-C21","difficulty":3,"kind":"error","stem":"단원을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이든 — 「물과 기름은 오래 저으면 골고루 잘 섞여.」","correct":true,"mis_target":"SC5-2-u1-X13"},{"t":"하윤 — 「혼합물 속 물질은 성질이 변하지 않은 채 섞여 있어.」","mis":"SC5-2-u1-X03"},{"t":"서하 — 「소금물을 증발시키면 소금을 얻을 수 있어.」","mis":"SC5-2-u1-X33"}],"explanation":["물과 기름은 다시 층을 이뤄요.","골고루 섞이지 않아요.","이든의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_challenge#1','sci',5,2,'u1','L08','g5_2_sci_u1_L08_challenge','lesson_challenge','SC5-2-u1-C21',2,'match','auto','혼합물과 나눌 때 이용하는 성질을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u1-C21","difficulty":2,"kind":"match","stem":"혼합물과 나눌 때 이용하는 성질을 알맞게 이으세요.","pairs":[{"l":"모래와 자갈","r":"알갱이의 크기 차이"},{"l":"물과 기름","r":"섞이지 않고 위에 뜸"},{"l":"소금과 모래","r":"물에 녹는지 녹지 않는지"},{"l":"소금물","r":"물만 증발하고 소금이 남음"}],"mis":"SC5-2-u1-X33","explanation":["크기·뜸·녹음이에요.","소금물은 증발이에요.","성질에 맞게 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_challenge#2','sci',5,2,'u1','L08','g5_2_sci_u1_L08_challenge','lesson_challenge','SC5-2-u1-C20',2,'mc','auto','새활용이 재활용보다 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X32','SC5-2-u1-X31','SC5-2-u1-X27']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C20","difficulty":2,"kind":"mc","stem":"새활용이 재활용보다 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"녹이거나 부수는 과정이 적어 에너지와 자원을 덜 쓴다","correct":true},{"t":"물건을 더 많이 버리게 한다","mis":"SC5-2-u1-X32"},{"t":"재활용과 똑같아 좋은 점이 따로 없다","mis":"SC5-2-u1-X31"},{"t":"물건의 성질을 모두 새로 바꾼다","mis":"SC5-2-u1-X27"}],"explanation":["새활용은 모양을 살려요.","녹이지 않아요.","에너지를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_challenge#3','sci',5,2,'u1','L08','g5_2_sci_u1_L08_challenge','lesson_challenge','SC5-2-u1-C21',3,'mc','auto','소금·모래·좁쌀이 섞인 혼합물을 물에 넣었어요. 세 가지를 모두 나누는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X34','SC5-2-u1-X12','SC5-2-u1-X33']::text[],false,'{"seq":3,"concept":"SC5-2-u1-C21","difficulty":3,"kind":"mc","stem":"소금·모래·좁쌀이 섞인 혼합물을 물에 넣었어요. 세 가지를 모두 나누는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"체로 좁쌀을 걸러 내고 → 거름 장치로 모래를 거른 뒤 → 소금물을 증발시킨다","correct":true},{"t":"먼저 증발시키고 → 체로 거르고 → 거름 장치로 거른다","mis":"SC5-2-u1-X34"},{"t":"거름 장치로 한 번만 거른다","mis":"SC5-2-u1-X12"},{"t":"흡착포로 소금을 빨아들인다","mis":"SC5-2-u1-X33"}],"explanation":["좁쌀은 크기로 나눠요.","모래는 거름으로요.","소금은 마지막에 증발로요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_challenge#4','sci',5,2,'u1','L08','g5_2_sci_u1_L08_challenge','lesson_challenge','SC5-2-u1-C4',3,'mc','auto','「혼합물을 분리하는 까닭은 우리 주변 물질이 모두 혼합물이기 때문이다.」가 옳지 않은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X07','SC5-2-u1-X06','SC5-2-u1-X03']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C4","difficulty":3,"kind":"mc","stem":"「혼합물을 분리하는 까닭은 우리 주변 물질이 모두 혼합물이기 때문이다.」가 옳지 않은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 가지 물질로 된 것도 있고, 분리하는 까닭은 필요한 물질을 얻으려는 것이기 때문이다","correct":true},{"t":"주변 물질은 정말 모두 혼합물이기 때문이다","mis":"SC5-2-u1-X07"},{"t":"혼합물은 분리할 수 없기 때문이다","mis":"SC5-2-u1-X06"},{"t":"분리하면 성질이 바뀌기 때문이다","mis":"SC5-2-u1-X03"}],"explanation":["금관·못은 한 가지예요.","「모두」가 틀렸어요.","필요한 물질을 얻으려 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_challenge#5','sci',5,2,'u1','L08','g5_2_sci_u1_L08_challenge','lesson_challenge','SC5-2-u1-C21',3,'ox','auto','혼합물을 나눌 때는 도구부터 고르기보다 섞인 물질의 성질을 먼저 살펴야 해요.',ARRAY['SC5-2-u1-X33']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C21","difficulty":3,"kind":"ox","stem":"혼합물을 나눌 때는 도구부터 고르기보다 섞인 물질의 성질을 먼저 살펴야 해요.","answer":"O","reason_options":[{"t":"물질의 성질 차이에 따라 알맞은 분리 방법이 달라지기 때문에","correct":true},{"t":"좋은 도구 하나면 어떤 혼합물이든 나눌 수 있기 때문에","mis":"SC5-2-u1-X33"}],"mis":"SC5-2-u1-X33","explanation":["혼합물마다 성질이 달라요.","성질에 맞는 방법이 있어요.","성질을 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_challenge#6','sci',5,2,'u1','L08','g5_2_sci_u1_L08_challenge','lesson_challenge','SC5-2-u1-C20',3,'error','auto','새활용을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X32','SC5-2-u1-X31']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C20","difficulty":3,"kind":"error","stem":"새활용을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"루다 — 「새활용은 낡은 물건을 아무 생각 없이 그대로 다시 쓰는 거야.」","correct":true,"mis_target":"SC5-2-u1-X32"},{"t":"선우 — 「버린 물건을 작품으로 바꾸는 사람도 있어.」","mis":"SC5-2-u1-X31"},{"t":"가윤 — 「쓸 수 있는 재료를 먼저 나누어 골라 모아야 해.」","mis":"SC5-2-u1-X32"}],"explanation":["새활용은 아이디어를 더해요.","새 가치를 만들어요.","루다의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_challenge#7','sci',5,2,'u1','L08','g5_2_sci_u1_L08_challenge','lesson_challenge','SC5-2-u1-C20',3,'mc','auto','업사이클링 아티스트가 하는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X31','SC5-2-u1-X32']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C20","difficulty":3,"kind":"mc","stem":"업사이클링 아티스트가 하는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"버려진 물건에서 쓸 만한 것을 나누어 골라 작품으로 바꾸고 메시지를 전한다","correct":true},{"t":"버려진 물건을 녹여 새 원료로 만든다","mis":"SC5-2-u1-X31"},{"t":"버려진 물건을 모아 땅에 묻는다","mis":"SC5-2-u1-X32"},{"t":"새 물건만 사서 작품을 만든다","mis":"SC5-2-u1-X32"}],"explanation":["버린 물건이 재료예요.","나누어 골라요.","작품으로 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_challenge#8','sci',5,2,'u1','L08','g5_2_sci_u1_L08_challenge','lesson_challenge','SC5-2-u1-C21',4,'mc','auto','「혼합물의 분리」 단원을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SC5-2-u1-X03','SC5-2-u1-X33','SC5-2-u1-X25']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C21","difficulty":4,"kind":"mc","stem":"「혼합물의 분리」 단원을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"혼합물은 섞인 물질의 서로 다른 성질(크기·섞이지 않음·물에 녹음)을 이용해 나누고, 이 방법이 생활 속 장치와 새활용으로 이어진다","correct":true},{"t":"혼합물은 한 번 섞이면 다시 나눌 수 없다","mis":"SC5-2-u1-X03"},{"t":"어떤 혼합물이든 체 하나로 모두 나눌 수 있다","mis":"SC5-2-u1-X33"},{"t":"혼합물의 분리는 실험실에서만 쓰인다","mis":"SC5-2-u1-X25"}],"explanation":["성질 차이로 나눠요.","방법이 여러 가지예요.","생활에 쓰여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_challenge#9','sci',5,2,'u1','L08','g5_2_sci_u1_L08_challenge','lesson_challenge','SC5-2-u1-C21',4,'mc','auto','흙탕물에서 맑은 물을 얻는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X20','SC5-2-u1-X33','SC5-2-u1-X09']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C21","difficulty":4,"kind":"mc","stem":"흙탕물에서 맑은 물을 얻는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"거름 장치로 걸러 흙은 거름종이 위에 남기고 빠져나간 물을 모은다","correct":true},{"t":"흙탕물을 가열해 물을 모두 날려 보낸다","mis":"SC5-2-u1-X20"},{"t":"스포이트로 흙만 뽑아낸다","mis":"SC5-2-u1-X33"},{"t":"눈이 아주 큰 체로 거른다","mis":"SC5-2-u1-X09"}],"explanation":["흙은 물에 녹지 않아요.","거름종이에 걸려요.","빠져나간 물이 맑아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_L08_challenge#10','sci',5,2,'u1','L08','g5_2_sci_u1_L08_challenge','lesson_challenge','SC5-2-u1-C20',4,'essay','teacher','쓰고 남은 물건 하나로 나만의 새활용 작품을 계획해 쓰고, 재료를 어떻게 나누어 모을지와 이것이 재활용과 다른 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u1-C20","difficulty":4,"kind":"essay","stem":"쓰고 남은 물건 하나로 나만의 새활용 작품을 계획해 쓰고, 재료를 어떻게 나누어 모을지와 이것이 재활용과 다른 점을 쓰세요.","answer_guide":{"answer":"예: 색깔이 다른 페트병 뚜껑으로 우리 반 이름 모자이크를 만들겠다. 뚜껑을 씻어 말린 뒤 색깔별로 나누어 상자에 모은다. 뚜껑을 녹이거나 부수지 않고 모양을 살려 아이디어를 더하므로 재활용보다 에너지와 자원을 덜 쓴다.","scoring_points":["새활용 작품을 계획했는가","재료를 나누어 모으는 방법을 썼는가","재활용과 다른 점을 썼는가"]},"explanation":["작품을 정해요.","재료를 나눠 모아요.","재활용과 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#1','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C1',1,'mc','auto','바다반 캠프 일지 ①에서 오른쪽에 놓인 카드의 공통점은 어느 것인가요?',ARRAY['SC5-2-u1-X01','SC5-2-u1-X02']::text[],false,'{"seq":1,"concept":"SC5-2-u1-C1","difficulty":1,"kind":"mc","stem":"바다반 캠프 일지 ①에서 오른쪽에 놓인 카드의 공통점은 어느 것인가요?","options":[{"t":"두 가지 이상의 물질이 섞여 있다","correct":true},{"t":"한 가지 물질로만 되어 있다","mis":"SC5-2-u1-X01"},{"t":"모두 차갑다","mis":"SC5-2-u1-X02"},{"t":"모두 딱딱하다","mis":"SC5-2-u1-X02"}],"explanation":["흙·음료·공기예요.","여럿이 섞였어요.","섞여 있는 물질이에요."],"asset":{"type":"passage","lines":["캠프 첫날, 물건 카드를 두 갈래로 나누는 놀이를 했다.","왼쪽 — 얼음, 선생님 금반지, 텐트 못","오른쪽 — 바닷가 흙, 탄산음료, 캠프장 공기","모둠장 수아: 「무엇으로 되어 있는지 보고 나눴어.」"],"title":"① 첫날 — 물건 카드 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#2','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C2',1,'mc','auto','혼합물의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X03','SC5-2-u1-X01']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C2","difficulty":1,"kind":"mc","stem":"혼합물의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 가지 이상의 물질이 각각의 성질이 변하지 않은 채 섞여 있는 것","correct":true},{"t":"섞이면서 성질이 모두 바뀐 것","mis":"SC5-2-u1-X03"},{"t":"한 가지 물질로만 된 것","mis":"SC5-2-u1-X01"},{"t":"눈에 보이는 고체만 섞인 것","mis":"SC5-2-u1-X01"}],"explanation":["두 가지 이상이에요.","성질은 그대로예요.","그것이 혼합물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#3','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C6',1,'mc','auto','바다반 캠프 일지 ②에서 체에 남은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X10','SC5-2-u1-X17']::text[],false,'{"seq":3,"concept":"SC5-2-u1-C6","difficulty":1,"kind":"mc","stem":"바다반 캠프 일지 ②에서 체에 남은 것은 어느 것인가요?","options":[{"t":"작은 조개와 조약돌","correct":true},{"t":"고운 모래","mis":"SC5-2-u1-X10"},{"t":"바닷물","mis":"SC5-2-u1-X17"},{"t":"아무것도 없다","mis":"SC5-2-u1-X10"}],"explanation":["조개는 커요.","체에 걸려요.","조개와 조약돌이 남았어요."],"asset":{"type":"passage","lines":["바닷가 흙을 큰 체에 담아 살살 흔들었다.","고운 모래는 아래 양동이로 빠지고, 작은 조개와 조약돌이 체에 남았다.","양동이의 모래를 돋보기로 보니 색이 여러 가지였다."],"title":"② 둘째 날 아침 — 체로 조개 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#4','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C8',1,'mc','auto','바다반 캠프 일지 ③에서 기름이 국의 어디에 있었나요?',ARRAY['SC5-2-u1-X14','SC5-2-u1-X13']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C8","difficulty":1,"kind":"mc","stem":"바다반 캠프 일지 ③에서 기름이 국의 어디에 있었나요?","options":[{"t":"국의 위쪽","correct":true},{"t":"국의 바닥","mis":"SC5-2-u1-X14"},{"t":"국 전체에 골고루","mis":"SC5-2-u1-X13"},{"t":"국그릇 밖","mis":"SC5-2-u1-X14"}],"explanation":["기름이 동동 떴어요.","위에 있어요.","위쪽이에요."],"asset":{"type":"passage","lines":["점심 미역국 위에 기름이 동동 떠 있었다.","조리사님은 국자로 위의 기름을 떠내고, 주방 종이를 살짝 대었다.","남은 기름은 하수구에 붓지 않고 따로 모았다."],"title":"③ 둘째 날 점심 — 미역국 기름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#5','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C10',1,'mc','auto','바다반 캠프 일지 ③에서 조리사님이 국 위에 주방 종이를 대어 이용한 것은 어느 것인가요?',ARRAY['SC5-2-u1-X17','SC5-2-u1-X13']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C10","difficulty":1,"kind":"mc","stem":"바다반 캠프 일지 ③에서 조리사님이 국 위에 주방 종이를 대어 이용한 것은 어느 것인가요?","options":[{"t":"종이가 위에 뜬 기름을 빨아들이는 것","correct":true},{"t":"종이가 물을 데우는 것","mis":"SC5-2-u1-X17"},{"t":"종이가 기름을 물에 섞는 것","mis":"SC5-2-u1-X13"},{"t":"종이가 국을 체처럼 거르는 것","mis":"SC5-2-u1-X17"}],"explanation":["기름은 위에 떠요.","종이가 빨아들여요.","흡착포와 같아요."],"asset":{"type":"passage","lines":["점심 미역국 위에 기름이 동동 떠 있었다.","조리사님은 국자로 위의 기름을 떠내고, 주방 종이를 살짝 대었다.","남은 기름은 하수구에 붓지 않고 따로 모았다."],"title":"③ 둘째 날 점심 — 미역국 기름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#6','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C12',1,'mc','auto','바다반 캠프 일지 ④에서 거름종이 위에 남은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X19']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C12","difficulty":1,"kind":"mc","stem":"바다반 캠프 일지 ④에서 거름종이 위에 남은 것은 어느 것인가요?","options":[{"t":"모래","correct":true},{"t":"소금","mis":"SC5-2-u1-X19"},{"t":"하얀 알갱이","mis":"SC5-2-u1-X19"},{"t":"바닷물 전부","mis":"SC5-2-u1-X19"}],"explanation":["모래는 물에 안 녹아요.","거름종이에 걸려요.","모래예요."],"asset":{"type":"passage","lines":["모래가 섞인 바닷물을 떠 와 비커에 담았다.","거름 장치로 거르자 거름종이 위에 모래가 남았다.","빠져나간 맑은 액체를 증발 접시에 붓고 약하게 가열했다.","물이 줄어들더니 하얀 알갱이가 남았다."],"title":"④ 둘째 날 오후 — 바닷물 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#7','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C13',1,'mc','auto','바다반 캠프 일지 ④에서 마지막에 남은 하얀 알갱이는 무엇인가요?',ARRAY['SC5-2-u1-X19','SC5-2-u1-X03']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C13","difficulty":1,"kind":"mc","stem":"바다반 캠프 일지 ④에서 마지막에 남은 하얀 알갱이는 무엇인가요?","options":[{"t":"소금","correct":true},{"t":"모래","mis":"SC5-2-u1-X19"},{"t":"거름종이 조각","mis":"SC5-2-u1-X19"},{"t":"새로 생긴 물질","mis":"SC5-2-u1-X03"}],"explanation":["물이 날아갔어요.","녹아 있던 것이 남아요.","소금이에요."],"asset":{"type":"passage","lines":["모래가 섞인 바닷물을 떠 와 비커에 담았다.","거름 장치로 거르자 거름종이 위에 모래가 남았다.","빠져나간 맑은 액체를 증발 접시에 붓고 약하게 가열했다.","물이 줄어들더니 하얀 알갱이가 남았다."],"title":"④ 둘째 날 오후 — 바닷물 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#8','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C15',1,'mc','auto','바다반 캠프 일지 ⑥의 섬 마을에서 바닷물에서 소금 등을 걸러 내는 장치는 어느 것인가요?',ARRAY['SC5-2-u1-X26']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C15","difficulty":1,"kind":"mc","stem":"바다반 캠프 일지 ⑥의 섬 마을에서 바닷물에서 소금 등을 걸러 내는 장치는 어느 것인가요?","options":[{"t":"해수 담수화 장치","correct":true},{"t":"공기 정화 장치","mis":"SC5-2-u1-X26"},{"t":"폐기물 선별 장치","mis":"SC5-2-u1-X26"},{"t":"흡착포","mis":"SC5-2-u1-X26"}],"explanation":["바닷물을 걸러요.","마실 물을 만들어요.","해수 담수화 장치예요."],"asset":{"type":"passage","lines":["배를 타고 작은 섬 마을에 갔다. 바다로 둘러싸였지만 마실 물이 모자랐다.","마을에는 바닷물에서 소금 등을 걸러 내는 장치가 있었다.","마을 학교에는 공기 속 먼지를 거르는 장치도 있었다."],"title":"⑥ 셋째 날 오후 — 섬 마을 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#9','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C1',2,'mc','auto','바다반 캠프 일지 ①에서 수아가 카드를 나눈 기준으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X02','SC5-2-u1-X01']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C1","difficulty":2,"kind":"mc","stem":"바다반 캠프 일지 ①에서 수아가 카드를 나눈 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 가지 물질로 되어 있는지, 여러 물질이 섞여 있는지","correct":true},{"t":"차가운지 따뜻한지","mis":"SC5-2-u1-X02"},{"t":"눈에 보이는지 보이지 않는지","mis":"SC5-2-u1-X01"},{"t":"값이 비싼지 싼지","mis":"SC5-2-u1-X02"}],"explanation":["왼쪽은 한 가지예요.","오른쪽은 섞였어요.","무엇으로 되었는지예요."],"asset":{"type":"passage","lines":["캠프 첫날, 물건 카드를 두 갈래로 나누는 놀이를 했다.","왼쪽 — 얼음, 선생님 금반지, 텐트 못","오른쪽 — 바닷가 흙, 탄산음료, 캠프장 공기","모둠장 수아: 「무엇으로 되어 있는지 보고 나눴어.」"],"title":"① 첫날 — 물건 카드 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#10','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C4',2,'mc','auto','우리가 혼합물을 나누는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X06','SC5-2-u1-X07']::text[],false,'{"seq":10,"concept":"SC5-2-u1-C4","difficulty":2,"kind":"mc","stem":"우리가 혼합물을 나누는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 물질이 섞여 있어 나누어야 필요한 물질을 얻어 쓸 수 있으므로","correct":true},{"t":"분리하면 물질이 더 무거워지므로","mis":"SC5-2-u1-X06"},{"t":"분리하면 물질의 양이 늘어나므로","mis":"SC5-2-u1-X06"},{"t":"주변 물질이 모두 혼합물이므로","mis":"SC5-2-u1-X07"}],"explanation":["섞여 있어요.","나눠야 골라 써요.","필요한 물질을 얻어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#11','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C6',2,'mc','auto','바다반 캠프 일지 ②의 체로 고운 모래와 조개를 나눌 수 있었던 까닭은 어느 것인가요?',ARRAY['SC5-2-u1-X09','SC5-2-u1-X33']::text[],false,'{"seq":11,"concept":"SC5-2-u1-C6","difficulty":2,"kind":"mc","stem":"바다반 캠프 일지 ②의 체로 고운 모래와 조개를 나눌 수 있었던 까닭은 어느 것인가요?","options":[{"t":"체의 눈이 모래보다 크고 조개보다 작았기 때문이다","correct":true},{"t":"체의 눈이 조개보다 컸기 때문이다","mis":"SC5-2-u1-X09"},{"t":"체의 눈이 모래보다 작았기 때문이다","mis":"SC5-2-u1-X09"},{"t":"모래가 물에 녹았기 때문이다","mis":"SC5-2-u1-X33"}],"explanation":["모래는 빠졌어요.","조개는 남았어요.","눈이 그 사이예요."],"asset":{"type":"passage","lines":["바닷가 흙을 큰 체에 담아 살살 흔들었다.","고운 모래는 아래 양동이로 빠지고, 작은 조개와 조약돌이 체에 남았다.","양동이의 모래를 돋보기로 보니 색이 여러 가지였다."],"title":"② 둘째 날 아침 — 체로 조개 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#12','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C10',2,'mc','auto','바다반 캠프 일지 ③에서 조리사님이 국의 기름을 줄인 두 방법의 공통된 까닭은 어느 것인가요?',ARRAY['SC5-2-u1-X13','SC5-2-u1-X14','SC5-2-u1-X17']::text[],false,'{"seq":12,"concept":"SC5-2-u1-C10","difficulty":2,"kind":"mc","stem":"바다반 캠프 일지 ③에서 조리사님이 국의 기름을 줄인 두 방법의 공통된 까닭은 어느 것인가요?","options":[{"t":"기름이 물과 섞이지 않고 위에 떠 있어서","correct":true},{"t":"기름이 물에 녹아 있어서","mis":"SC5-2-u1-X13"},{"t":"기름이 국 바닥에 가라앉아서","mis":"SC5-2-u1-X14"},{"t":"기름 알갱이가 커서 체에 걸려서","mis":"SC5-2-u1-X17"}],"explanation":["기름은 위에 떠요.","떠내고 빨아들여요.","섞이지 않기 때문이에요."],"asset":{"type":"passage","lines":["점심 미역국 위에 기름이 동동 떠 있었다.","조리사님은 국자로 위의 기름을 떠내고, 주방 종이를 살짝 대었다.","남은 기름은 하수구에 붓지 않고 따로 모았다."],"title":"③ 둘째 날 점심 — 미역국 기름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#13','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C12',2,'mc','auto','바다반 캠프 일지 ④에서 거름종이를 빠져나간 맑은 액체에 들어 있는 것은 어느 것인가요?',ARRAY['SC5-2-u1-X19']::text[],false,'{"seq":13,"concept":"SC5-2-u1-C12","difficulty":2,"kind":"mc","stem":"바다반 캠프 일지 ④에서 거름종이를 빠져나간 맑은 액체에 들어 있는 것은 어느 것인가요?","options":[{"t":"물에 녹아 있는 소금","correct":true},{"t":"모래","mis":"SC5-2-u1-X19"},{"t":"아무것도 없는 물","mis":"SC5-2-u1-X19"},{"t":"조개","mis":"SC5-2-u1-X19"}],"explanation":["소금은 녹았어요.","물과 함께 빠져요.","소금물이에요."],"asset":{"type":"passage","lines":["모래가 섞인 바닷물을 떠 와 비커에 담았다.","거름 장치로 거르자 거름종이 위에 모래가 남았다.","빠져나간 맑은 액체를 증발 접시에 붓고 약하게 가열했다.","물이 줄어들더니 하얀 알갱이가 남았다."],"title":"④ 둘째 날 오후 — 바닷물 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#14','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C14',2,'mc','auto','바다반 캠프 일지 ⑤의 염전은 이 단원의 어느 실험을 크게 만든 것과 같나요?',ARRAY['SC5-2-u1-X22']::text[],false,'{"seq":14,"concept":"SC5-2-u1-C14","difficulty":2,"kind":"mc","stem":"바다반 캠프 일지 ⑤의 염전은 이 단원의 어느 실험을 크게 만든 것과 같나요?","options":[{"t":"증발 장치로 소금물을 가열해 소금을 얻은 실험","correct":true},{"t":"체로 모래와 자갈을 나눈 실험","mis":"SC5-2-u1-X22"},{"t":"스포이트로 기름을 뽑은 실험","mis":"SC5-2-u1-X22"},{"t":"거름 장치로 모래를 거른 실험","mis":"SC5-2-u1-X22"}],"explanation":["물을 날려 보내요.","소금이 남아요.","증발 실험이에요."],"asset":{"type":"passage","lines":["바닷가 염전에 갔다. 바닷물을 넓고 얕은 바닥에 가두어 두었다.","해설사님: 「햇빛과 바람이 물을 날려 보내면 소금이 남아요.」","바닥 곳곳에 하얀 소금이 모여 있었다."],"title":"⑤ 셋째 날 — 염전 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#15','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C15',2,'mc','auto','바다반 캠프 일지 ⑥의 섬 마을에 마실 물이 모자랐던 까닭은 어느 것인가요?',ARRAY['SC5-2-u1-X04','SC5-2-u1-X24']::text[],false,'{"seq":15,"concept":"SC5-2-u1-C15","difficulty":2,"kind":"mc","stem":"바다반 캠프 일지 ⑥의 섬 마을에 마실 물이 모자랐던 까닭은 어느 것인가요?","options":[{"t":"둘러싼 바닷물에 소금 등이 섞여 있어 그대로 마실 수 없어서","correct":true},{"t":"바닷물 속 소금이 녹아 없어져 맹물이라서","mis":"SC5-2-u1-X04"},{"t":"섬에는 바닷물이 닿지 않아서","mis":"SC5-2-u1-X24"},{"t":"바닷물이 너무 차가워서","mis":"SC5-2-u1-X24"}],"explanation":["바닷물은 짜요.","그냥 못 마셔요.","나누어야 해요."],"asset":{"type":"passage","lines":["배를 타고 작은 섬 마을에 갔다. 바다로 둘러싸였지만 마실 물이 모자랐다.","마을에는 바닷물에서 소금 등을 걸러 내는 장치가 있었다.","마을 학교에는 공기 속 먼지를 거르는 장치도 있었다."],"title":"⑥ 셋째 날 오후 — 섬 마을 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#16','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C18',2,'mc','auto','바다반 캠프 일지 ⑦에서 선별장 장치를 소개하는 포스터 가운데에 가장 크게 넣을 말은 어느 것인가요?',ARRAY['SC5-2-u1-X29','SC5-2-u1-X30']::text[],false,'{"seq":16,"concept":"SC5-2-u1-C18","difficulty":2,"kind":"mc","stem":"바다반 캠프 일지 ⑦에서 선별장 장치를 소개하는 포스터 가운데에 가장 크게 넣을 말은 어느 것인가요?","options":[{"t":"카메라로 보고 플라스틱·종이·유리를 골라 내요","correct":true},{"t":"우리 모둠 최고","mis":"SC5-2-u1-X29"},{"t":"멋진 로봇 그림","mis":"SC5-2-u1-X29"},{"t":"모둠원 연락처","mis":"SC5-2-u1-X30"}],"explanation":["분리 방법이 핵심이에요.","무엇을 골라 내나요.","그 말을 크게 넣어요."],"asset":{"type":"passage","lines":["캠프 쓰레기를 플라스틱·종이·캔으로 나누어 모았다.","선별장 영상 — 카메라가 달린 장치가 플라스틱·종이·유리를 골라 냈다.","모둠마다 오늘 본 장치 하나를 골라 포스터를 만들어 올렸다."],"title":"⑦ 넷째 날 — 분리배출과 포스터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#17','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C7',3,'mc','auto','바다반 캠프장에서 쌀·콩·좁쌀이 섞였어요. 크기는 좁쌀 < 쌀 < 콩이에요. 세 가지를 모두 나누는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X12','SC5-2-u1-X09','SC5-2-u1-X33']::text[],false,'{"seq":17,"concept":"SC5-2-u1-C7","difficulty":3,"kind":"mc","stem":"바다반 캠프장에서 쌀·콩·좁쌀이 섞였어요. 크기는 좁쌀 < 쌀 < 콩이에요. 세 가지를 모두 나누는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"눈 크기가 다른 체 두 개로 한 번에 하나씩 차례로 거른다","correct":true},{"t":"체 하나로 한 번에 세 가지를 나눈다","mis":"SC5-2-u1-X12"},{"t":"가장 촘촘한 체 하나로 거른다","mis":"SC5-2-u1-X09"},{"t":"물에 녹여 증발시킨다","mis":"SC5-2-u1-X33"}],"explanation":["세 가지가 섞였어요.","한 번에 하나씩이에요.","체 두 개를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#18','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C10',3,'mc','auto','바다에 기름이 얇고 넓게 퍼졌을 때 스포이트보다 흡착포가 알맞은 까닭은 어느 것인가요?',ARRAY['SC5-2-u1-X16','SC5-2-u1-X15','SC5-2-u1-X17']::text[],false,'{"seq":18,"concept":"SC5-2-u1-C10","difficulty":3,"kind":"mc","stem":"바다에 기름이 얇고 넓게 퍼졌을 때 스포이트보다 흡착포가 알맞은 까닭은 어느 것인가요?","options":[{"t":"얇게 퍼진 기름은 뽑기 어렵지만 흡착포는 대기만 하면 빨아들이기 때문이다","correct":true},{"t":"흡착포로 얻은 기름은 바로 다시 쓸 수 있기 때문이다","mis":"SC5-2-u1-X16"},{"t":"스포이트는 물만 뽑기 때문이다","mis":"SC5-2-u1-X15"},{"t":"흡착포는 바닷물을 증발시키기 때문이다","mis":"SC5-2-u1-X17"}],"explanation":["얇은 층은 뽑기 어려워요.","흡착포는 대면 돼요.","흡착포가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#19','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C13',3,'mc','auto','증발 실험을 할 때 안전하게 한 친구는 누구인가요?',ARRAY['SC5-2-u1-X21']::text[],false,'{"seq":19,"concept":"SC5-2-u1-C13","difficulty":3,"kind":"mc","stem":"증발 실험을 할 때 안전하게 한 친구는 누구인가요?","options":[{"t":"하진 — 보안경과 면장갑을 끼고 약하게 가열한 뒤 집게로 접시를 옮겼다","correct":true},{"t":"우빈 — 빨리 끝내려고 세게 가열했다","mis":"SC5-2-u1-X21"},{"t":"라엘 — 전원을 끄자마자 가열판을 손으로 짚었다","mis":"SC5-2-u1-X21"},{"t":"도담 — 증발 접시를 맨손으로 옮겼다","mis":"SC5-2-u1-X21"}],"explanation":["약하게 가열해요.","집게를 써요.","하진이 안전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#20','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C16',3,'mc','auto','정수 장치의 여러 겹 거름망과 가장 닮은 실험은 어느 것인가요?',ARRAY['SC5-2-u1-X26','SC5-2-u1-X25']::text[],false,'{"seq":20,"concept":"SC5-2-u1-C16","difficulty":3,"kind":"mc","stem":"정수 장치의 여러 겹 거름망과 가장 닮은 실험은 어느 것인가요?","options":[{"t":"거름 장치로 물에 녹지 않는 모래를 걸러 낸 실험","correct":true},{"t":"증발 접시로 소금을 얻은 실험","mis":"SC5-2-u1-X26"},{"t":"스포이트로 기름을 옮긴 실험","mis":"SC5-2-u1-X26"},{"t":"말판 놀이","mis":"SC5-2-u1-X25"}],"explanation":["거름망으로 걸러요.","녹지 않은 것이 걸려요.","거름 실험과 닮았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#21','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C20',3,'mc','auto','다음 가운데 재활용에 해당하는 것은 어느 것인가요?',ARRAY['SC5-2-u1-X31']::text[],false,'{"seq":21,"concept":"SC5-2-u1-C20","difficulty":3,"kind":"mc","stem":"다음 가운데 재활용에 해당하는 것은 어느 것인가요?","options":[{"t":"모은 페트병을 잘게 부수고 녹여 옷감 원료로 만든다","correct":true},{"t":"뚜껑을 그대로 붙여 벽화를 만든다","mis":"SC5-2-u1-X31"},{"t":"안 쓰는 청바지로 가방을 만든다","mis":"SC5-2-u1-X31"},{"t":"플라스틱 병 모양을 살려 조명을 만든다","mis":"SC5-2-u1-X31"}],"explanation":["부수고 녹였어요.","변형해 다시 써요.","재활용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#22','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C21',3,'mc','auto','혼합물과 알맞은 분리 방법을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X33']::text[],false,'{"seq":22,"concept":"SC5-2-u1-C21","difficulty":3,"kind":"mc","stem":"혼합물과 알맞은 분리 방법을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"모래와 자갈 — 체 · 물과 기름 — 스포이트 · 소금과 모래 — 거름과 증발","correct":true},{"t":"모래와 자갈 — 증발 · 물과 기름 — 체 · 소금과 모래 — 스포이트","mis":"SC5-2-u1-X33"},{"t":"모래와 자갈 — 거름 · 물과 기름 — 증발 · 소금과 모래 — 체","mis":"SC5-2-u1-X33"},{"t":"모두 체 하나로 나눈다","mis":"SC5-2-u1-X33"}],"explanation":["크기는 체예요.","뜨면 스포이트예요.","녹으면 거름·증발이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#23','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C21',4,'mc','auto','바다반 캠프 일지 ①~⑧을 차례로 볼 때 가장 알맞은 정리는 어느 것인가요?',ARRAY['SC5-2-u1-X07','SC5-2-u1-X33','SC5-2-u1-X03']::text[],false,'{"seq":23,"concept":"SC5-2-u1-C21","difficulty":4,"kind":"mc","stem":"바다반 캠프 일지 ①~⑧을 차례로 볼 때 가장 알맞은 정리는 어느 것인가요?","options":[{"t":"섞여 있는 물질을 알아본 뒤, 크기·섞이지 않음·물에 녹음 같은 성질로 나누고, 그 방법이 장치와 새활용으로 이어졌다","correct":true},{"t":"캠프에서 본 물질은 모두 한 가지 물질이었다","mis":"SC5-2-u1-X07"},{"t":"모든 혼합물을 체 하나로 나누었다","mis":"SC5-2-u1-X33"},{"t":"나눈 물질은 모두 성질이 바뀌었다","mis":"SC5-2-u1-X03"}],"explanation":["①은 섞인 물질이에요.","②~⑤는 나누는 방법이에요.","⑥~⑧은 생활과 새활용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#24','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C1',4,'essay','teacher','바다반 캠프 일지 ①을 보고 수아가 카드를 나눈 기준을 쓰고, 왼쪽과 오른쪽에서 하나씩 골라 그렇게 나눈 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-2-u1-C1","difficulty":4,"kind":"essay","stem":"바다반 캠프 일지 ①을 보고 수아가 카드를 나눈 기준을 쓰고, 왼쪽과 오른쪽에서 하나씩 골라 그렇게 나눈 까닭을 쓰세요.","answer_guide":{"answer":"예: 수아는 무엇으로 되어 있는지를 기준으로 한 가지 물질과 섞여 있는 물질을 나눴다. 얼음은 물 한 가지로 되어 있어 왼쪽이다. 탄산음료는 물과 이산화 탄소 등이 섞여 있어 오른쪽이다.","scoring_points":["나눈 기준을 썼는가","왼쪽 카드의 까닭을 썼는가","오른쪽 카드의 까닭을 썼는가"]},"explanation":["기준을 써요.","왼쪽 까닭이에요.","오른쪽 까닭이에요."],"asset":{"type":"passage","lines":["캠프 첫날, 물건 카드를 두 갈래로 나누는 놀이를 했다.","왼쪽 — 얼음, 선생님 금반지, 텐트 못","오른쪽 — 바닷가 흙, 탄산음료, 캠프장 공기","모둠장 수아: 「무엇으로 되어 있는지 보고 나눴어.」"],"title":"① 첫날 — 물건 카드 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_a#25','sci',5,2,'u1','','g5_2_sci_u1_review_a','unit_review','SC5-2-u1-C14',4,'essay','teacher','바다반 캠프 일지 ⑤의 염전과 실험의 증발 장치를 견주어 같은 점과 다른 점을 한 가지씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-2-u1-C14","difficulty":4,"kind":"essay","stem":"바다반 캠프 일지 ⑤의 염전과 실험의 증발 장치를 견주어 같은 점과 다른 점을 한 가지씩 쓰세요.","answer_guide":{"answer":"예: 같은 점 — 둘 다 소금물에서 물을 증발시켜 녹아 있던 소금을 얻는다. 다른 점 — 염전은 햇빛과 바람으로 넓은 바닥에서 천천히 증발시키고, 실험은 가열판으로 증발 접시를 가열한다.","scoring_points":["같은 점을 썼는가","다른 점을 썼는가","증발이라는 낱말을 바르게 썼는가"]},"explanation":["둘 다 증발이에요.","열을 얻는 곳이 달라요.","크기도 달라요."],"asset":{"type":"passage","lines":["바닷가 염전에 갔다. 바닷물을 넓고 얕은 바닥에 가두어 두었다.","해설사님: 「햇빛과 바람이 물을 날려 보내면 소금이 남아요.」","바닥 곳곳에 하얀 소금이 모여 있었다."],"title":"⑤ 셋째 날 — 염전 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#1','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C1',1,'ox','auto','캠프장 공기는 여러 가지 기체가 섞여 있는 물질이에요.',ARRAY['SC5-2-u1-X01']::text[],false,'{"seq":1,"concept":"SC5-2-u1-C1","difficulty":1,"kind":"ox","stem":"캠프장 공기는 여러 가지 기체가 섞여 있는 물질이에요.","answer":"O","reason_options":[{"t":"질소·산소·이산화 탄소 등이 섞여 있기 때문에","correct":true},{"t":"눈에 보이지 않으니 한 가지이기 때문에","mis":"SC5-2-u1-X01"}],"mis":"SC5-2-u1-X01","explanation":["공기는 안 보여요.","여러 기체가 있어요.","섞여 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#2','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C3',1,'mc','auto','목화에서 분리해 얻는 물질은 어느 것인가요?',ARRAY['SC5-2-u1-X05']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C3","difficulty":1,"kind":"mc","stem":"목화에서 분리해 얻는 물질은 어느 것인가요?","options":[{"t":"목화솜","correct":true},{"t":"설탕","mis":"SC5-2-u1-X05"},{"t":"천연고무액","mis":"SC5-2-u1-X05"},{"t":"소금","mis":"SC5-2-u1-X05"}],"explanation":["목화는 솜이 열려요.","옷과 이불을 만들어요.","목화솜이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#3','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C6',1,'sa','auto','바다반 캠프 일지 ②에서 바닷가 흙을 담아 흔든, 구멍이 뚫린 도구는 무엇인가요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-2-u1-C6","difficulty":1,"kind":"sa","stem":"바다반 캠프 일지 ②에서 바닷가 흙을 담아 흔든, 구멍이 뚫린 도구는 무엇인가요? 한 글자로 쓰세요.","answer":["체"],"explanation":["구멍이 있어요.","크기로 나눠요.","체예요."],"asset":{"type":"passage","lines":["바닷가 흙을 큰 체에 담아 살살 흔들었다.","고운 모래는 아래 양동이로 빠지고, 작은 조개와 조약돌이 체에 남았다.","양동이의 모래를 돋보기로 보니 색이 여러 가지였다."],"title":"② 둘째 날 아침 — 체로 조개 찾기"},"mis":"SC5-2-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#4','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C8',1,'ox','auto','물과 기름을 섞으면 기름이 아래쪽, 물이 위쪽에 있어요.',ARRAY['SC5-2-u1-X14']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C8","difficulty":1,"kind":"ox","stem":"물과 기름을 섞으면 기름이 아래쪽, 물이 위쪽에 있어요.","answer":"X","reason_options":[{"t":"기름이 위쪽, 물이 아래쪽에 층을 이루기 때문에","correct":true},{"t":"기름은 언제나 바닥에 가라앉기 때문에","mis":"SC5-2-u1-X14"}],"mis":"SC5-2-u1-X14","explanation":["기름은 떠요.","물은 아래예요.","거꾸로 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#5','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C10',1,'ox','auto','흡착포는 물 위에 뜬 기름을 빨아들여요.',ARRAY['SC5-2-u1-X16']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C10","difficulty":1,"kind":"ox","stem":"흡착포는 물 위에 뜬 기름을 빨아들여요.","answer":"O","reason_options":[{"t":"기름을 흡수하는 종이이기 때문에","correct":true},{"t":"흡착포는 물만 빨아들이기 때문에","mis":"SC5-2-u1-X16"}],"mis":"SC5-2-u1-X16","explanation":["흡착포는 기름을 흡수해요.","물은 남겨요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#6','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C12',1,'sa','auto','바다반 캠프 일지 ④에서 모래를 걸러 낸 방법은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SC5-2-u1-C12","difficulty":1,"kind":"sa","stem":"바다반 캠프 일지 ④에서 모래를 걸러 낸 방법은 무엇인가요? 두 글자로 쓰세요.","answer":["거름"],"explanation":["거름종이를 썼어요.","걸러서 나눠요.","거름이에요."],"asset":{"type":"passage","lines":["모래가 섞인 바닷물을 떠 와 비커에 담았다.","거름 장치로 거르자 거름종이 위에 모래가 남았다.","빠져나간 맑은 액체를 증발 접시에 붓고 약하게 가열했다.","물이 줄어들더니 하얀 알갱이가 남았다."],"title":"④ 둘째 날 오후 — 바닷물 실험"},"mis":"SC5-2-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#7','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C14',1,'mc','auto','바다반 캠프 일지 ⑤의 염전에서 소금을 얻는 방법은 어느 것인가요?',ARRAY['SC5-2-u1-X22']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C14","difficulty":1,"kind":"mc","stem":"바다반 캠프 일지 ⑤의 염전에서 소금을 얻는 방법은 어느 것인가요?","options":[{"t":"햇빛과 바람으로 물을 증발시킨다","correct":true},{"t":"천으로 거른다","mis":"SC5-2-u1-X22"},{"t":"체로 거른다","mis":"SC5-2-u1-X22"},{"t":"흡착포로 빨아들인다","mis":"SC5-2-u1-X22"}],"explanation":["물을 날려 보내요.","햇빛과 바람이에요.","증발이에요."],"asset":{"type":"passage","lines":["바닷가 염전에 갔다. 바닷물을 넓고 얕은 바닥에 가두어 두었다.","해설사님: 「햇빛과 바람이 물을 날려 보내면 소금이 남아요.」","바닥 곳곳에 하얀 소금이 모여 있었다."],"title":"⑤ 셋째 날 — 염전 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#8','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C16',1,'mc','auto','공기 속 먼지를 걸러 내는 장치는 어느 것인가요?',ARRAY['SC5-2-u1-X26']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C16","difficulty":1,"kind":"mc","stem":"공기 속 먼지를 걸러 내는 장치는 어느 것인가요?","options":[{"t":"공기 정화 장치","correct":true},{"t":"해수 담수화 장치","mis":"SC5-2-u1-X26"},{"t":"정수 장치","mis":"SC5-2-u1-X26"},{"t":"증발 접시","mis":"SC5-2-u1-X26"}],"explanation":["공기가 재료예요.","먼지를 걸러요.","공기 정화 장치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#9','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C1',2,'ox','auto','바다반 캠프 일지 ①에서 얼음 카드는 차갑고 딱딱하므로 오른쪽으로 옮겨야 해요.',ARRAY['SC5-2-u1-X02']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C1","difficulty":2,"kind":"ox","stem":"바다반 캠프 일지 ①에서 얼음 카드는 차갑고 딱딱하므로 오른쪽으로 옮겨야 해요.","answer":"X","reason_options":[{"t":"얼음은 물 한 가지로 되어 있어 왼쪽이 맞기 때문에","correct":true},{"t":"차갑고 딱딱한 것은 섞여 있는 물질이기 때문에","mis":"SC5-2-u1-X02"}],"mis":"SC5-2-u1-X02","explanation":["얼음은 물이 언 거예요.","한 가지예요.","왼쪽이 맞아요."],"asset":{"type":"passage","lines":["캠프 첫날, 물건 카드를 두 갈래로 나누는 놀이를 했다.","왼쪽 — 얼음, 선생님 금반지, 텐트 못","오른쪽 — 바닷가 흙, 탄산음료, 캠프장 공기","모둠장 수아: 「무엇으로 되어 있는지 보고 나눴어.」"],"title":"① 첫날 — 물건 카드 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#10','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C4',2,'ox','auto','바다반 캠프 일지 ⑦에서 쓰레기를 플라스틱·종이·캔으로 나누어 모은 것은 필요한 물질을 다시 얻어 쓰려는 것이에요.',ARRAY['SC5-2-u1-X06']::text[],false,'{"seq":10,"concept":"SC5-2-u1-C4","difficulty":2,"kind":"ox","stem":"바다반 캠프 일지 ⑦에서 쓰레기를 플라스틱·종이·캔으로 나누어 모은 것은 필요한 물질을 다시 얻어 쓰려는 것이에요.","answer":"O","reason_options":[{"t":"물질별로 나누어야 다시 자원으로 쓸 수 있기 때문에","correct":true},{"t":"통을 보기 좋게 채우려는 것이기 때문에","mis":"SC5-2-u1-X06"}],"mis":"SC5-2-u1-X06","explanation":["물질별로 나눴어요.","다시 쓸 수 있어요.","분리의 까닭과 같아요."],"asset":{"type":"passage","lines":["캠프 쓰레기를 플라스틱·종이·캔으로 나누어 모았다.","선별장 영상 — 카메라가 달린 장치가 플라스틱·종이·유리를 골라 냈다.","모둠마다 오늘 본 장치 하나를 골라 포스터를 만들어 올렸다."],"title":"⑦ 넷째 날 — 분리배출과 포스터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#11','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C6',2,'ox','auto','바다반 캠프 일지 ②에서 체의 눈이 모래보다 작았다면 모래와 조개가 모두 체에 남았을 거예요.',ARRAY['SC5-2-u1-X09']::text[],false,'{"seq":11,"concept":"SC5-2-u1-C6","difficulty":2,"kind":"ox","stem":"바다반 캠프 일지 ②에서 체의 눈이 모래보다 작았다면 모래와 조개가 모두 체에 남았을 거예요.","answer":"O","reason_options":[{"t":"모래도 눈보다 커져 빠져나가지 못하기 때문에","correct":true},{"t":"눈이 작을수록 모래가 더 잘 빠지기 때문에","mis":"SC5-2-u1-X09"}],"mis":"SC5-2-u1-X09","explanation":["눈이 작으면 모래도 걸려요.","둘 다 남아요.","나뉘지 않아요."],"asset":{"type":"passage","lines":["바닷가 흙을 큰 체에 담아 살살 흔들었다.","고운 모래는 아래 양동이로 빠지고, 작은 조개와 조약돌이 체에 남았다.","양동이의 모래를 돋보기로 보니 색이 여러 가지였다."],"title":"② 둘째 날 아침 — 체로 조개 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#12','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C10',2,'ox','auto','바다반 캠프 일지 ③에서 국자로 떠낸 기름은 다시 모아 쓸 수 있어요.',ARRAY['SC5-2-u1-X16']::text[],false,'{"seq":12,"concept":"SC5-2-u1-C10","difficulty":2,"kind":"ox","stem":"바다반 캠프 일지 ③에서 국자로 떠낸 기름은 다시 모아 쓸 수 있어요.","answer":"O","reason_options":[{"t":"스포이트처럼 기름을 그대로 떠서 옮겼기 때문에","correct":true},{"t":"떠낸 기름은 모두 물로 바뀌기 때문에","mis":"SC5-2-u1-X16"}],"mis":"SC5-2-u1-X16","explanation":["국자로 떠냈어요.","그대로 옮겼어요.","다시 모을 수 있어요."],"asset":{"type":"passage","lines":["점심 미역국 위에 기름이 동동 떠 있었다.","조리사님은 국자로 위의 기름을 떠내고, 주방 종이를 살짝 대었다.","남은 기름은 하수구에 붓지 않고 따로 모았다."],"title":"③ 둘째 날 점심 — 미역국 기름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#13','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C12',2,'ox','auto','바다반 캠프 일지 ④에서 거름종이 위에는 소금과 모래가 함께 남았어요.',ARRAY['SC5-2-u1-X19']::text[],false,'{"seq":13,"concept":"SC5-2-u1-C12","difficulty":2,"kind":"ox","stem":"바다반 캠프 일지 ④에서 거름종이 위에는 소금과 모래가 함께 남았어요.","answer":"X","reason_options":[{"t":"소금은 물에 녹아 빠져나가고 모래만 남았기 때문에","correct":true},{"t":"거름종이는 모든 것을 다 걸러 내기 때문에","mis":"SC5-2-u1-X19"}],"mis":"SC5-2-u1-X19","explanation":["소금은 녹았어요.","빠져나갔어요.","모래만 남아요."],"asset":{"type":"passage","lines":["모래가 섞인 바닷물을 떠 와 비커에 담았다.","거름 장치로 거르자 거름종이 위에 모래가 남았다.","빠져나간 맑은 액체를 증발 접시에 붓고 약하게 가열했다.","물이 줄어들더니 하얀 알갱이가 남았다."],"title":"④ 둘째 날 오후 — 바닷물 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#14','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C14',2,'ox','auto','바다반 캠프 일지 ⑤의 염전에서 바닷물을 얕게 넓게 가두는 것은 물이 잘 증발하게 하려는 거예요.',ARRAY['SC5-2-u1-X22']::text[],false,'{"seq":14,"concept":"SC5-2-u1-C14","difficulty":2,"kind":"ox","stem":"바다반 캠프 일지 ⑤의 염전에서 바닷물을 얕게 넓게 가두는 것은 물이 잘 증발하게 하려는 거예요.","answer":"O","reason_options":[{"t":"넓게 펼치면 햇빛과 바람에 물이 잘 날아가기 때문에","correct":true},{"t":"얕게 가두면 소금이 녹아 사라지기 때문에","mis":"SC5-2-u1-X22"}],"mis":"SC5-2-u1-X22","explanation":["넓게 펼쳐요.","물이 잘 날아가요.","증발을 돕는 거예요."],"asset":{"type":"passage","lines":["바닷가 염전에 갔다. 바닷물을 넓고 얕은 바닥에 가두어 두었다.","해설사님: 「햇빛과 바람이 물을 날려 보내면 소금이 남아요.」","바닥 곳곳에 하얀 소금이 모여 있었다."],"title":"⑤ 셋째 날 — 염전 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#15','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C15',2,'ox','auto','바다반 캠프 일지 ⑥의 장치는 바닷물에 소금을 더 넣어 마실 물을 만들어요.',ARRAY['SC5-2-u1-X24']::text[],false,'{"seq":15,"concept":"SC5-2-u1-C15","difficulty":2,"kind":"ox","stem":"바다반 캠프 일지 ⑥의 장치는 바닷물에 소금을 더 넣어 마실 물을 만들어요.","answer":"X","reason_options":[{"t":"바닷물에서 소금 등을 걸러 내 마실 물을 만들기 때문에","correct":true},{"t":"소금을 넣어야 물이 깨끗해지기 때문에","mis":"SC5-2-u1-X24"}],"mis":"SC5-2-u1-X24","explanation":["소금을 걸러 내요.","넣는 게 아니에요.","마실 물을 만들어요."],"asset":{"type":"passage","lines":["배를 타고 작은 섬 마을에 갔다. 바다로 둘러싸였지만 마실 물이 모자랐다.","마을에는 바닷물에서 소금 등을 걸러 내는 장치가 있었다.","마을 학교에는 공기 속 먼지를 거르는 장치도 있었다."],"title":"⑥ 셋째 날 오후 — 섬 마을 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#16','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C19',2,'ox','auto','바다반 캠프 일지 ⑦의 포스터에 「별로야」라고만 댓글을 다는 것은 바른 댓글이에요.',ARRAY['SC5-2-u1-X30']::text[],false,'{"seq":16,"concept":"SC5-2-u1-C19","difficulty":2,"kind":"ox","stem":"바다반 캠프 일지 ⑦의 포스터에 「별로야」라고만 댓글을 다는 것은 바른 댓글이에요.","answer":"X","reason_options":[{"t":"까닭 없는 말은 도움이 되지 않고 상처를 줄 수 있기 때문에","correct":true},{"t":"짧은 댓글일수록 좋기 때문에","mis":"SC5-2-u1-X30"}],"mis":"SC5-2-u1-X30","explanation":["까닭이 없어요.","도움이 안 돼요.","바른 댓글이 아니에요."],"asset":{"type":"passage","lines":["캠프 쓰레기를 플라스틱·종이·캔으로 나누어 모았다.","선별장 영상 — 카메라가 달린 장치가 플라스틱·종이·유리를 골라 냈다.","모둠마다 오늘 본 장치 하나를 골라 포스터를 만들어 올렸다."],"title":"⑦ 넷째 날 — 분리배출과 포스터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#17','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C7',3,'ox','auto','좁쌀·쌀·콩을 나눌 때 큰 체를 먼저 써도 세 가지를 모두 나눌 수 있어요.',ARRAY['SC5-2-u1-X12']::text[],false,'{"seq":17,"concept":"SC5-2-u1-C7","difficulty":3,"kind":"ox","stem":"좁쌀·쌀·콩을 나눌 때 큰 체를 먼저 써도 세 가지를 모두 나눌 수 있어요.","answer":"O","reason_options":[{"t":"큰 체로 콩을 먼저 남기고, 빠진 것을 작은 체로 다시 거르면 되기 때문에","correct":true},{"t":"반드시 작은 체부터 써야만 나뉘기 때문에","mis":"SC5-2-u1-X12"}],"mis":"SC5-2-u1-X12","explanation":["큰 체로 콩이 남아요.","작은 체로 쌀이 남아요.","차례를 바꿔도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#18','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C10',3,'ox','auto','흡착포로 빨아들인 기름은 다시 모아 쓰기 어려워요.',ARRAY['SC5-2-u1-X16']::text[],false,'{"seq":18,"concept":"SC5-2-u1-C10","difficulty":3,"kind":"ox","stem":"흡착포로 빨아들인 기름은 다시 모아 쓰기 어려워요.","answer":"O","reason_options":[{"t":"기름이 흡착포에 스며들어 버리기 때문에","correct":true},{"t":"흡착포는 기름을 그대로 옮겨 담기 때문에","mis":"SC5-2-u1-X16"}],"mis":"SC5-2-u1-X16","explanation":["기름이 스며들어요.","꺼내기 어려워요.","다시 쓰기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#19','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C13',3,'ox','auto','가열판은 전원을 끄면 곧바로 식어서 만져도 돼요.',ARRAY['SC5-2-u1-X21']::text[],false,'{"seq":19,"concept":"SC5-2-u1-C13","difficulty":3,"kind":"ox","stem":"가열판은 전원을 끄면 곧바로 식어서 만져도 돼요.","answer":"X","reason_options":[{"t":"전원을 끈 뒤에도 한동안 뜨거워 데일 수 있기 때문에","correct":true},{"t":"전원을 끄면 바로 차가워지기 때문에","mis":"SC5-2-u1-X21"}],"mis":"SC5-2-u1-X21","explanation":["끈 뒤에도 뜨거워요.","데일 수 있어요.","만지면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#20','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C16',3,'ox','auto','바다반 캠프 일지 ⑦의 선별장 장치는 쓰레기의 성질을 바꾸어 새 물질로 만들어요.',ARRAY['SC5-2-u1-X27']::text[],false,'{"seq":20,"concept":"SC5-2-u1-C16","difficulty":3,"kind":"ox","stem":"바다반 캠프 일지 ⑦의 선별장 장치는 쓰레기의 성질을 바꾸어 새 물질로 만들어요.","answer":"X","reason_options":[{"t":"플라스틱·종이·유리를 성질 그대로 골라 나누기만 하기 때문에","correct":true},{"t":"골라 내는 동안 쓰레기가 새 물질로 바뀌기 때문에","mis":"SC5-2-u1-X27"}],"mis":"SC5-2-u1-X27","explanation":["골라 내기만 해요.","성질은 그대로예요.","바꾸지 않아요."],"asset":{"type":"passage","lines":["캠프 쓰레기를 플라스틱·종이·캔으로 나누어 모았다.","선별장 영상 — 카메라가 달린 장치가 플라스틱·종이·유리를 골라 냈다.","모둠마다 오늘 본 장치 하나를 골라 포스터를 만들어 올렸다."],"title":"⑦ 넷째 날 — 분리배출과 포스터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#21','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C20',3,'ox','auto','새활용은 재활용보다 에너지와 자원을 덜 써요.',ARRAY['SC5-2-u1-X31']::text[],false,'{"seq":21,"concept":"SC5-2-u1-C20","difficulty":3,"kind":"ox","stem":"새활용은 재활용보다 에너지와 자원을 덜 써요.","answer":"O","reason_options":[{"t":"녹이거나 부수는 과정 없이 모양을 살려 쓰기 때문에","correct":true},{"t":"새활용은 새 재료를 더 많이 사야 하기 때문에","mis":"SC5-2-u1-X31"}],"mis":"SC5-2-u1-X31","explanation":["녹이지 않아요.","모양을 살려요.","에너지를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#22','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C21',3,'blank','auto','혼합물의 분리 정리판에서 ㉡에 들어갈 도구는 어느 것인가요?',ARRAY['SC5-2-u1-X33']::text[],false,'{"seq":22,"concept":"SC5-2-u1-C21","difficulty":3,"kind":"blank","stem":"혼합물의 분리 정리판에서 ㉡에 들어갈 도구는 어느 것인가요?","options":[{"t":"스포이트","correct":true},{"t":"체","mis":"SC5-2-u1-X33"},{"t":"증발 접시","mis":"SC5-2-u1-X33"},{"t":"거름종이","mis":"SC5-2-u1-X33"}],"explanation":["물과 기름 줄이에요.","위에 뜬 것을 뽑아요.","스포이트예요."],"asset":{"type":"passage","lines":["모래와 자갈 — (㉠) 차이 — 체","물과 기름 — 섞이지 않고 위에 뜸 — (㉡)·흡착포","소금과 모래 — 물에 녹는지 — 거름 → (㉢)"],"title":"혼합물의 분리 정리판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#23','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C21',4,'mc','auto','바다반 캠프 일지에서 같은 성질을 이용한 것끼리 바르게 묶은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X33','SC5-2-u1-X22']::text[],false,'{"seq":23,"concept":"SC5-2-u1-C21","difficulty":4,"kind":"mc","stem":"바다반 캠프 일지에서 같은 성질을 이용한 것끼리 바르게 묶은 것은 어느 것인가요?","options":[{"t":"② 체로 조개 찾기와 ⑥ 학교의 먼지 거르는 장치","correct":true},{"t":"③ 국 기름 떠내기와 ⑤ 염전","mis":"SC5-2-u1-X33"},{"t":"④ 거름과 ② 체로 조개 찾기","mis":"SC5-2-u1-X33"},{"t":"⑤ 염전과 ③ 국 기름 떠내기","mis":"SC5-2-u1-X22"}],"explanation":["체는 크기로 나눠요.","먼지 거르기도 크기예요.","②와 ⑥이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#24','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C6',4,'essay','teacher','바다반 캠프 일지 ②를 보고 체로 모래와 조개를 나눈 원리를 쓰고, 알맞은 체의 눈 크기 조건을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-2-u1-C6","difficulty":4,"kind":"essay","stem":"바다반 캠프 일지 ②를 보고 체로 모래와 조개를 나눈 원리를 쓰고, 알맞은 체의 눈 크기 조건을 쓰세요.","answer_guide":{"answer":"예: 알갱이의 크기 차이를 이용했다. 체의 눈보다 작은 모래는 빠져나가고, 눈보다 큰 조개와 조약돌은 체에 남았다. 체의 눈은 모래보다 크고 조개보다 작아야 한다.","scoring_points":["크기 차이를 이용했다고 썼는가","남는 것과 빠지는 것을 썼는가","눈 크기 조건을 썼는가"]},"explanation":["크기 차이예요.","남고 빠져요.","눈은 그 사이예요."],"asset":{"type":"passage","lines":["바닷가 흙을 큰 체에 담아 살살 흔들었다.","고운 모래는 아래 양동이로 빠지고, 작은 조개와 조약돌이 체에 남았다.","양동이의 모래를 돋보기로 보니 색이 여러 가지였다."],"title":"② 둘째 날 아침 — 체로 조개 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_b#25','sci',5,2,'u1','','g5_2_sci_u1_review_b','unit_review','SC5-2-u1-C15',4,'essay','teacher','바다반 캠프 일지 ⑥을 보고 섬 마을에 물이 모자란 까닭과 장치가 이 문제를 어떻게 해결하는지 쓰고, 이 장치가 지속가능한 삶에 주는 도움을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-2-u1-C15","difficulty":4,"kind":"essay","stem":"바다반 캠프 일지 ⑥을 보고 섬 마을에 물이 모자란 까닭과 장치가 이 문제를 어떻게 해결하는지 쓰고, 이 장치가 지속가능한 삶에 주는 도움을 쓰세요.","answer_guide":{"answer":"예: 섬은 바다로 둘러싸였지만 바닷물에는 소금 등이 섞여 있어 그대로 마실 수 없다. 해수 담수화 장치는 바닷물에서 소금 등을 걸러 내 마실 물과 생활용수를 만든다. 물이 모자란 곳에서도 사람들이 건강하게 살 수 있게 돕는다.","scoring_points":["물이 모자란 까닭을 썼는가","장치가 해결하는 방법을 썼는가","삶에 주는 도움을 썼는가"]},"explanation":["바닷물은 짜요.","소금 등을 걸러요.","건강을 지켜요."],"asset":{"type":"passage","lines":["배를 타고 작은 섬 마을에 갔다. 바다로 둘러싸였지만 마실 물이 모자랐다.","마을에는 바닷물에서 소금 등을 걸러 내는 장치가 있었다.","마을 학교에는 공기 속 먼지를 거르는 장치도 있었다."],"title":"⑥ 셋째 날 오후 — 섬 마을 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#1','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C1',1,'mc','auto','캠프 물건 가운데 한 가지 물질로만 이루어진 것은 어느 것인가요?',ARRAY['SC5-2-u1-X02','SC5-2-u1-X01']::text[],false,'{"seq":1,"concept":"SC5-2-u1-C1","difficulty":1,"kind":"mc","stem":"캠프 물건 가운데 한 가지 물질로만 이루어진 것은 어느 것인가요?","options":[{"t":"텐트 못(철)","correct":true},{"t":"바닷가 흙","mis":"SC5-2-u1-X02"},{"t":"탄산음료","mis":"SC5-2-u1-X01"},{"t":"캠프장 공기","mis":"SC5-2-u1-X01"}],"explanation":["못은 철이에요.","한 가지예요.","텐트 못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#2','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C2',1,'ox','auto','설탕물 속 설탕은 녹아 있어도 단맛이 그대로예요.',ARRAY['SC5-2-u1-X04']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C2","difficulty":1,"kind":"ox","stem":"설탕물 속 설탕은 녹아 있어도 단맛이 그대로예요.","answer":"O","reason_options":[{"t":"혼합물 속 물질은 성질이 변하지 않기 때문에","correct":true},{"t":"물에 녹으면 단맛이 사라지기 때문에","mis":"SC5-2-u1-X04"}],"mis":"SC5-2-u1-X04","explanation":["설탕은 녹아 있어요.","성질은 그대로예요.","여전히 달아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#3','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C6',1,'ox','auto','체의 눈보다 큰 알갱이는 체에 남아요.',ARRAY['SC5-2-u1-X10']::text[],false,'{"seq":3,"concept":"SC5-2-u1-C6","difficulty":1,"kind":"ox","stem":"체의 눈보다 큰 알갱이는 체에 남아요.","answer":"O","reason_options":[{"t":"구멍보다 커서 지나가지 못하기 때문에","correct":true},{"t":"큰 알갱이일수록 구멍을 잘 빠져나가기 때문에","mis":"SC5-2-u1-X10"}],"mis":"SC5-2-u1-X10","explanation":["크면 못 지나가요.","체에 걸려요.","체에 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#4','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C9',1,'mc','auto','층을 이룬 물과 기름에서 위층의 기름을 뽑아 옮기는 도구는 어느 것인가요?',ARRAY['SC5-2-u1-X17']::text[],false,'{"seq":4,"concept":"SC5-2-u1-C9","difficulty":1,"kind":"mc","stem":"층을 이룬 물과 기름에서 위층의 기름을 뽑아 옮기는 도구는 어느 것인가요?","options":[{"t":"스포이트","correct":true},{"t":"체","mis":"SC5-2-u1-X17"},{"t":"증발 접시","mis":"SC5-2-u1-X17"},{"t":"돋보기","mis":"SC5-2-u1-X17"}],"explanation":["위층을 뽑아요.","빨아들여 옮겨요.","스포이트예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#5','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C10',1,'mc','auto','바다에 기름이 퍼졌을 때 물 위에 던져 기름을 빨아들이게 하는 것은 어느 것인가요?',ARRAY['SC5-2-u1-X17','SC5-2-u1-X16']::text[],false,'{"seq":5,"concept":"SC5-2-u1-C10","difficulty":1,"kind":"mc","stem":"바다에 기름이 퍼졌을 때 물 위에 던져 기름을 빨아들이게 하는 것은 어느 것인가요?","options":[{"t":"흡착포","correct":true},{"t":"체","mis":"SC5-2-u1-X17"},{"t":"스포이트 한 개","mis":"SC5-2-u1-X16"},{"t":"증발 접시","mis":"SC5-2-u1-X17"}],"explanation":["넓게 퍼졌어요.","빨아들여야 해요.","흡착포예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#6','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C11',1,'ox','auto','소금은 물에 녹고 모래는 물에 녹지 않아요.',ARRAY['SC5-2-u1-X04']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C11","difficulty":1,"kind":"ox","stem":"소금은 물에 녹고 모래는 물에 녹지 않아요.","answer":"O","reason_options":[{"t":"소금물은 투명하고 모래는 바닥에 가라앉기 때문에","correct":true},{"t":"둘 다 물에 녹아 없어지기 때문에","mis":"SC5-2-u1-X04"}],"mis":"SC5-2-u1-X04","explanation":["소금은 녹아요.","모래는 안 녹아요.","이 차이로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#7','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C13',1,'sa','auto','소금물에서 물을 날려 보내 녹아 있던 소금을 얻는 방법은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SC5-2-u1-C13","difficulty":1,"kind":"sa","stem":"소금물에서 물을 날려 보내 녹아 있던 소금을 얻는 방법은 무엇인가요? 두 글자로 쓰세요.","answer":["증발"],"explanation":["물이 날아가요.","소금이 남아요.","증발이에요."],"mis":"SC5-2-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#8','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C20',1,'ox','auto','바다반 캠프 일지 ⑧의 뚜껑 벽화는 새활용이에요.',ARRAY['SC5-2-u1-X31']::text[],false,'{"seq":8,"concept":"SC5-2-u1-C20","difficulty":1,"kind":"ox","stem":"바다반 캠프 일지 ⑧의 뚜껑 벽화는 새활용이에요.","answer":"O","reason_options":[{"t":"뚜껑을 녹이지 않고 아이디어를 더해 새 작품을 만들었기 때문에","correct":true},{"t":"뚜껑을 녹여 새 원료로 만들었기 때문에","mis":"SC5-2-u1-X31"}],"mis":"SC5-2-u1-X31","explanation":["뚜껑을 그대로 썼어요.","아이디어를 더했어요.","새활용이에요."],"asset":{"type":"passage","lines":["캠프 동안 모은 페트병 뚜껑을 씻어 색깔별로 나누었다.","뚜껑을 녹이지 않고 그대로 붙여 「바다반」 글자 벽화를 만들었다.","마지막으로 캠프에서 나눈 혼합물을 정리판에 적었다."],"title":"⑧ 마지막 날 — 뚜껑 벽화와 정리판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#9','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C1',2,'error','auto','바다반 캠프 일지 ①을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X01','SC5-2-u1-X02']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C1","difficulty":2,"kind":"error","stem":"바다반 캠프 일지 ①을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준 — 「캠프장 공기는 안 보이니까 왼쪽에 놓아야 해.」","correct":true,"mis_target":"SC5-2-u1-X01"},{"t":"보라 — 「탄산음료에는 물과 이산화 탄소 등이 섞여 있어.」","mis":"SC5-2-u1-X01"},{"t":"찬 — 「금반지는 금 한 가지야.」","mis":"SC5-2-u1-X02"}],"explanation":["공기는 여러 기체예요.","오른쪽이 맞아요.","준의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["캠프 첫날, 물건 카드를 두 갈래로 나누는 놀이를 했다.","왼쪽 — 얼음, 선생님 금반지, 텐트 못","오른쪽 — 바닷가 흙, 탄산음료, 캠프장 공기","모둠장 수아: 「무엇으로 되어 있는지 보고 나눴어.」"],"title":"① 첫날 — 물건 카드 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#10','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C4',2,'error','auto','혼합물을 분리하는 까닭을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X03','SC5-2-u1-X06']::text[],false,'{"seq":10,"concept":"SC5-2-u1-C4","difficulty":2,"kind":"error","stem":"혼합물을 분리하는 까닭을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다미 — 「분리하면 물질을 더 오래 쓸 수 있게 성질이 바뀌어서야.」","correct":true,"mis_target":"SC5-2-u1-X03"},{"t":"겸 — 「필요한 물질을 얻으려고 나눠.」","mis":"SC5-2-u1-X06"},{"t":"예서 — 「얻은 물질로 필요한 물건을 만들 수 있어.」","mis":"SC5-2-u1-X06"}],"explanation":["분리해도 성질은 그대로예요.","필요한 물질을 얻으려 해요.","다미의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#11','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C6',2,'error','auto','바다반 캠프 일지 ②를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X10','SC5-2-u1-X08']::text[],false,'{"seq":11,"concept":"SC5-2-u1-C6","difficulty":2,"kind":"error","stem":"바다반 캠프 일지 ②를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하늘 — 「양동이로 빠진 건 조개고 체에 남은 건 모래야.」","correct":true,"mis_target":"SC5-2-u1-X10"},{"t":"은호 — 「모래는 체의 눈보다 작아 빠졌어.」","mis":"SC5-2-u1-X10"},{"t":"라온 — 「크기 차이를 이용해 나눴어.」","mis":"SC5-2-u1-X08"}],"explanation":["모래가 빠졌어요.","조개가 남았어요.","하늘의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["바닷가 흙을 큰 체에 담아 살살 흔들었다.","고운 모래는 아래 양동이로 빠지고, 작은 조개와 조약돌이 체에 남았다.","양동이의 모래를 돋보기로 보니 색이 여러 가지였다."],"title":"② 둘째 날 아침 — 체로 조개 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#12','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C8',2,'error','auto','바다반 캠프 일지 ③을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X13','SC5-2-u1-X17','SC5-2-u1-X16']::text[],false,'{"seq":12,"concept":"SC5-2-u1-C8","difficulty":2,"kind":"error","stem":"바다반 캠프 일지 ③을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"마루 — 「국을 오래 저으면 기름이 골고루 섞여 안 보이게 돼.」","correct":true,"mis_target":"SC5-2-u1-X13"},{"t":"나린 — 「기름이 위에 떠서 국자로 떠낼 수 있었어.」","mis":"SC5-2-u1-X17"},{"t":"지오 — 「주방 종이는 흡착포처럼 기름을 빨아들여.」","mis":"SC5-2-u1-X16"}],"explanation":["저어도 다시 떠올라요.","골고루 섞이지 않아요.","마루의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["점심 미역국 위에 기름이 동동 떠 있었다.","조리사님은 국자로 위의 기름을 떠내고, 주방 종이를 살짝 대었다.","남은 기름은 하수구에 붓지 않고 따로 모았다."],"title":"③ 둘째 날 점심 — 미역국 기름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#13','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C12',2,'error','auto','바다반 캠프 일지 ④를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X20']::text[],false,'{"seq":13,"concept":"SC5-2-u1-C12","difficulty":2,"kind":"error","stem":"바다반 캠프 일지 ④를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도진 — 「먼저 가열하고 나서 거름 장치로 걸렀어.」","correct":true,"mis_target":"SC5-2-u1-X20"},{"t":"수하 — 「거름으로 모래를 먼저 나눴어.」","mis":"SC5-2-u1-X20"},{"t":"지민 — 「빠져나간 액체를 가열해 소금을 얻었어.」","mis":"SC5-2-u1-X20"}],"explanation":["거름이 먼저예요.","증발이 나중이에요.","도진의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["모래가 섞인 바닷물을 떠 와 비커에 담았다.","거름 장치로 거르자 거름종이 위에 모래가 남았다.","빠져나간 맑은 액체를 증발 접시에 붓고 약하게 가열했다.","물이 줄어들더니 하얀 알갱이가 남았다."],"title":"④ 둘째 날 오후 — 바닷물 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#14','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C14',2,'error','auto','생활 속 나누기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X22']::text[],false,'{"seq":14,"concept":"SC5-2-u1-C14","difficulty":2,"kind":"error","stem":"생활 속 나누기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세린 — 「염전에서는 천으로 바닷물을 걸러 소금을 얻어.」","correct":true,"mis_target":"SC5-2-u1-X22"},{"t":"도아 — 「간장은 천으로 걸러 얻어.」","mis":"SC5-2-u1-X22"},{"t":"윤재 — 「치즈도 천으로 걸러 만들어.」","mis":"SC5-2-u1-X22"}],"explanation":["염전은 증발이에요.","천은 거름이에요.","세린의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["바닷가 염전에 갔다. 바닷물을 넓고 얕은 바닥에 가두어 두었다.","해설사님: 「햇빛과 바람이 물을 날려 보내면 소금이 남아요.」","바닥 곳곳에 하얀 소금이 모여 있었다."],"title":"⑤ 셋째 날 — 염전 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#15','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C16',2,'error','auto','바다반 캠프 일지 ⑥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X26','SC5-2-u1-X25']::text[],false,'{"seq":15,"concept":"SC5-2-u1-C16","difficulty":2,"kind":"error","stem":"바다반 캠프 일지 ⑥을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「학교의 먼지 거르는 장치는 물속 오염 물질을 거르는 장치야.」","correct":true,"mis_target":"SC5-2-u1-X26"},{"t":"하라 — 「바닷물에서 소금 등을 거르는 건 해수 담수화 장치야.」","mis":"SC5-2-u1-X26"},{"t":"주아 — 「공기 정화 장치도 혼합물의 분리를 이용해.」","mis":"SC5-2-u1-X25"}],"explanation":["먼지는 공기 속에 있어요.","공기를 거르는 장치예요.","태오의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["배를 타고 작은 섬 마을에 갔다. 바다로 둘러싸였지만 마실 물이 모자랐다.","마을에는 바닷물에서 소금 등을 걸러 내는 장치가 있었다.","마을 학교에는 공기 속 먼지를 거르는 장치도 있었다."],"title":"⑥ 셋째 날 오후 — 섬 마을 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#16','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C20',2,'error','auto','바다반 캠프 일지 ⑧을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X31','SC5-2-u1-X32']::text[],false,'{"seq":16,"concept":"SC5-2-u1-C20","difficulty":2,"kind":"error","stem":"바다반 캠프 일지 ⑧을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"정우 — 「뚜껑 벽화는 뚜껑을 녹여 만들었으니 재활용이야.」","correct":true,"mis_target":"SC5-2-u1-X31"},{"t":"아린 — 「뚜껑을 색깔별로 나누어 모았어.」","mis":"SC5-2-u1-X32"},{"t":"소유 — 「아이디어를 더해 새 가치를 만들었어.」","mis":"SC5-2-u1-X31"}],"explanation":["녹이지 않았어요.","그대로 붙였어요.","정우의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["캠프 동안 모은 페트병 뚜껑을 씻어 색깔별로 나누었다.","뚜껑을 녹이지 않고 그대로 붙여 「바다반」 글자 벽화를 만들었다.","마지막으로 캠프에서 나눈 혼합물을 정리판에 적었다."],"title":"⑧ 마지막 날 — 뚜껑 벽화와 정리판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#17','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C7',3,'error','auto','좁쌀·쌀·콩을 나누는 계획을 두고 친구들이 말했어요. 알맞지 않은 의견은 누구의 것인가요?',ARRAY['SC5-2-u1-X09','SC5-2-u1-X12']::text[],false,'{"seq":17,"concept":"SC5-2-u1-C7","difficulty":3,"kind":"error","stem":"좁쌀·쌀·콩을 나누는 계획을 두고 친구들이 말했어요. 알맞지 않은 의견은 누구의 것인가요?","options":[{"t":"은솔 — 「눈이 좁쌀보다 작은 체 하나면 다 나뉘어.」","correct":true,"mis_target":"SC5-2-u1-X09"},{"t":"지후 — 「좁쌀보다 크고 쌀보다 작은 눈의 체가 필요해.」","mis":"SC5-2-u1-X09"},{"t":"채운 — 「쌀보다 크고 콩보다 작은 눈의 체도 필요해.」","mis":"SC5-2-u1-X12"}],"explanation":["눈이 너무 작아요.","모두 남아요.","은솔의 의견이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#18','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C9',3,'error','auto','스포이트로 물과 기름을 나누는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X15']::text[],false,'{"seq":18,"concept":"SC5-2-u1-C9","difficulty":3,"kind":"error","stem":"스포이트로 물과 기름을 나누는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「아래층 물부터 스포이트를 깊이 넣어 뽑아.」","correct":true,"mis_target":"SC5-2-u1-X15"},{"t":"유주 — 「위층 기름부터 뽑아 옮겨.」","mis":"SC5-2-u1-X15"},{"t":"서진 — 「경계면 가까이는 조심해서 따로 모아.」","mis":"SC5-2-u1-X15"}],"explanation":["기름은 위에 있어요.","위층부터 뽑아요.","태린의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#19','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C12',3,'error','auto','소금과 모래를 나누는 계획을 두고 친구들이 말했어요. 알맞지 않은 의견은 누구의 것인가요?',ARRAY['SC5-2-u1-X20']::text[],false,'{"seq":19,"concept":"SC5-2-u1-C12","difficulty":3,"kind":"error","stem":"소금과 모래를 나누는 계획을 두고 친구들이 말했어요. 알맞지 않은 의견은 누구의 것인가요?","options":[{"t":"서안 — 「물에 녹이지 말고 바로 거름 장치에 부어 모래를 걸러.」","correct":true,"mis_target":"SC5-2-u1-X20"},{"t":"나은 — 「먼저 물에 넣어 소금을 녹여.」","mis":"SC5-2-u1-X20"},{"t":"지원 — 「거름 뒤 소금물을 증발시켜.」","mis":"SC5-2-u1-X20"}],"explanation":["녹이지 않으면 소금도 걸려요.","먼저 녹여야 해요.","서안의 의견이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#20','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C16',3,'error','auto','분리 장치를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X35']::text[],false,'{"seq":20,"concept":"SC5-2-u1-C16","difficulty":3,"kind":"error","stem":"분리 장치를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「분리 장치는 편리할 뿐 건강이나 환경과는 관계없어.」","correct":true,"mis_target":"SC5-2-u1-X35"},{"t":"예솔 — 「깨끗한 물과 공기로 건강을 지켜.」","mis":"SC5-2-u1-X35"},{"t":"하빈 — 「자원을 골라 다시 써 환경을 지켜.」","mis":"SC5-2-u1-X35"}],"explanation":["건강을 지켜요.","자원도 아껴요.","민준의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#21','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C20',3,'error','auto','새활용 계획을 두고 친구들이 말했어요. 알맞지 않은 의견은 누구의 것인가요?',ARRAY['SC5-2-u1-X32','SC5-2-u1-X31']::text[],false,'{"seq":21,"concept":"SC5-2-u1-C20","difficulty":3,"kind":"error","stem":"새활용 계획을 두고 친구들이 말했어요. 알맞지 않은 의견은 누구의 것인가요?","options":[{"t":"로운 — 「재료는 나누지 말고 아무거나 섞어 담아 두자.」","correct":true,"mis_target":"SC5-2-u1-X32"},{"t":"지유 — 「쓸 수 있는 재료를 먼저 골라 모으자.」","mis":"SC5-2-u1-X32"},{"t":"해솔 — 「아이디어를 더해 새 쓰임을 찾자.」","mis":"SC5-2-u1-X31"}],"explanation":["재료를 나누어 모아요.","그래야 쓸 수 있어요.","로운의 의견이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#22','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C21',3,'error','auto','혼합물을 나누는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u1-X18','SC5-2-u1-X33']::text[],false,'{"seq":22,"concept":"SC5-2-u1-C21","difficulty":3,"kind":"error","stem":"혼합물을 나누는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「소금과 모래는 알갱이 크기가 달라서 체로 나눠.」","correct":true,"mis_target":"SC5-2-u1-X18"},{"t":"수호 — 「소금은 물에 녹는 성질로 나눠.」","mis":"SC5-2-u1-X33"},{"t":"리아 — 「모래와 자갈은 크기 차이로 나눠.」","mis":"SC5-2-u1-X33"}],"explanation":["소금과 모래는 크기가 비슷해요.","물에 녹는지로 나눠요.","하랑의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#23','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C12',4,'mc','auto','바다반 캠프 일지 ④에서 증발을 먼저 하고 거름을 나중에 했다면 어떻게 되었을까요?',ARRAY['SC5-2-u1-X34','SC5-2-u1-X03','SC5-2-u1-X20']::text[],false,'{"seq":23,"concept":"SC5-2-u1-C12","difficulty":4,"kind":"mc","stem":"바다반 캠프 일지 ④에서 증발을 먼저 하고 거름을 나중에 했다면 어떻게 되었을까요?","options":[{"t":"물이 날아가 소금과 모래가 함께 남아 거름으로 나눌 수 없었을 것이다","correct":true},{"t":"소금만 깨끗이 남았을 것이다","mis":"SC5-2-u1-X34"},{"t":"모래가 소금으로 바뀌었을 것이다","mis":"SC5-2-u1-X03"},{"t":"결과는 같았을 것이다","mis":"SC5-2-u1-X20"}],"explanation":["증발하면 물이 없어요.","소금과 모래가 함께 남아요.","거름이 먼저예요."],"asset":{"type":"passage","lines":["모래가 섞인 바닷물을 떠 와 비커에 담았다.","거름 장치로 거르자 거름종이 위에 모래가 남았다.","빠져나간 맑은 액체를 증발 접시에 붓고 약하게 가열했다.","물이 줄어들더니 하얀 알갱이가 남았다."],"title":"④ 둘째 날 오후 — 바닷물 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#24','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C10',4,'essay','teacher','바다반 캠프 일지 ③을 보고 국의 기름을 줄인 두 방법을 쓰고, 이 방법들이 가능한 까닭과 실험에서 쓴 도구 가운데 닮은 것을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-2-u1-C10","difficulty":4,"kind":"essay","stem":"바다반 캠프 일지 ③을 보고 국의 기름을 줄인 두 방법을 쓰고, 이 방법들이 가능한 까닭과 실험에서 쓴 도구 가운데 닮은 것을 쓰세요.","answer_guide":{"answer":"예: 국자로 위의 기름을 떠내고 주방 종이를 대어 기름을 빨아들였다. 기름은 물과 섞이지 않고 위에 떠 있기 때문에 가능하다. 국자는 스포이트와, 주방 종이는 흡착포와 닮았다.","scoring_points":["두 방법을 썼는가","기름이 위에 뜨고 섞이지 않는다는 까닭을 썼는가","닮은 도구를 이었는가"]},"explanation":["두 방법을 써요.","위에 떠요.","스포이트·흡착포예요."],"asset":{"type":"passage","lines":["점심 미역국 위에 기름이 동동 떠 있었다.","조리사님은 국자로 위의 기름을 떠내고, 주방 종이를 살짝 대었다.","남은 기름은 하수구에 붓지 않고 따로 모았다."],"title":"③ 둘째 날 점심 — 미역국 기름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_c#25','sci',5,2,'u1','','g5_2_sci_u1_review_c','unit_review','SC5-2-u1-C18',4,'essay','teacher','바다반 캠프 일지 ⑦을 보고 선별장 장치를 소개하는 포스터를 계획해 제목·분리 방법·개발 배경을 쓰고, 다른 모둠에 달 좋은 댓글을 하나 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-2-u1-C18","difficulty":4,"kind":"essay","stem":"바다반 캠프 일지 ⑦을 보고 선별장 장치를 소개하는 포스터를 계획해 제목·분리 방법·개발 배경을 쓰고, 다른 모둠에 달 좋은 댓글을 하나 쓰세요.","answer_guide":{"answer":"예: 제목 — 「인공지능 폐기물 선별 장치」. 분리 방법 — 카메라로 보고 플라스틱·종이·유리를 골라 낸다(화살표 그림). 개발 배경 — 사람이 하나하나 고르기 어려운 많은 쓰레기를 빠르게 나누려고. 댓글 — 「정수 장치가 거름을 이용한다는 걸 새로 알았어요. 거름망이 몇 겹인지도 궁금해요!」","scoring_points":["제목과 분리 방법을 썼는가","개발 배경을 썼는가","바르고 구체적인 댓글을 썼는가"]},"explanation":["분리 방법을 크게요.","배경도 써요.","고운 댓글이에요."],"asset":{"type":"passage","lines":["캠프 쓰레기를 플라스틱·종이·캔으로 나누어 모았다.","선별장 영상 — 카메라가 달린 장치가 플라스틱·종이·유리를 골라 냈다.","모둠마다 오늘 본 장치 하나를 골라 포스터를 만들어 올렸다."],"title":"⑦ 넷째 날 — 분리배출과 포스터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#1','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C1',1,'sa','auto','캠프 일지 ①의 왼쪽 카드처럼 한 가지로만 되어 있지 않고, 오른쪽 카드처럼 여러 물질이 섞여 있는 것을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u1-C1","difficulty":1,"kind":"sa","stem":"캠프 일지 ①의 왼쪽 카드처럼 한 가지로만 되어 있지 않고, 오른쪽 카드처럼 여러 물질이 섞여 있는 것을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["혼합물"],"explanation":["여럿이 섞였어요.","세 글자예요.","혼합물이에요."],"asset":{"type":"passage","lines":["캠프 첫날, 물건 카드를 두 갈래로 나누는 놀이를 했다.","왼쪽 — 얼음, 선생님 금반지, 텐트 못","오른쪽 — 바닷가 흙, 탄산음료, 캠프장 공기","모둠장 수아: 「무엇으로 되어 있는지 보고 나눴어.」"],"title":"① 첫날 — 물건 카드 놀이"},"mis":"SC5-2-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#2','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C3',1,'mc','auto','금광석에서 분리해 얻는 물질은 어느 것인가요?',ARRAY['SC5-2-u1-X05']::text[],false,'{"seq":2,"concept":"SC5-2-u1-C3","difficulty":1,"kind":"mc","stem":"금광석에서 분리해 얻는 물질은 어느 것인가요?","options":[{"t":"금","correct":true},{"t":"설탕","mis":"SC5-2-u1-X05"},{"t":"목화솜","mis":"SC5-2-u1-X05"},{"t":"천연고무액","mis":"SC5-2-u1-X05"}],"explanation":["금광석에는 금이 섞였어요.","나누어 얻어요.","금이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#3','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C5',1,'mc','auto','모래와 자갈의 혼합물을 체로 나눌 때 이용하는 성질은 어느 것인가요?',ARRAY['SC5-2-u1-X08','SC5-2-u1-X33']::text[],false,'{"seq":3,"concept":"SC5-2-u1-C5","difficulty":1,"kind":"mc","stem":"모래와 자갈의 혼합물을 체로 나눌 때 이용하는 성질은 어느 것인가요?","options":[{"t":"알갱이의 크기 차이","correct":true},{"t":"알갱이의 색깔 차이","mis":"SC5-2-u1-X08"},{"t":"물에 녹는 성질","mis":"SC5-2-u1-X33"},{"t":"냄새 차이","mis":"SC5-2-u1-X08"}],"explanation":["모양·색은 둘 다 여러 가지예요.","크기가 달라요.","크기 차이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#4','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C9',1,'sa','auto','물과 기름처럼 골고루 섞이지 않는 두 액체에서 위층 액체를 뽑아 옮기는 도구를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u1-C9","difficulty":1,"kind":"sa","stem":"물과 기름처럼 골고루 섞이지 않는 두 액체에서 위층 액체를 뽑아 옮기는 도구를 쓰세요.","answer":["스포이트"],"explanation":["고무 부분을 눌러요.","빨아들여요.","스포이트예요."],"mis":"SC5-2-u1-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#5','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C10',1,'sa','auto','기름을 흡수하는 종이로, 물 위에 뜬 기름에 대면 기름만 빨아들이는 것은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-2-u1-C10","difficulty":1,"kind":"sa","stem":"기름을 흡수하는 종이로, 물 위에 뜬 기름에 대면 기름만 빨아들이는 것은 무엇인가요? 세 글자로 쓰세요.","answer":["흡착포"],"explanation":["기름을 빨아들여요.","바다에서도 써요.","흡착포예요."],"mis":"SC5-2-u1-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#6','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C11',1,'mc','auto','소금과 모래의 혼합물을 나누려고 가장 먼저 할 일은 어느 것인가요?',ARRAY['SC5-2-u1-X34','SC5-2-u1-X18','SC5-2-u1-X33']::text[],false,'{"seq":6,"concept":"SC5-2-u1-C11","difficulty":1,"kind":"mc","stem":"소금과 모래의 혼합물을 나누려고 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"물에 넣어 저어 소금을 녹인다","correct":true},{"t":"바로 가열한다","mis":"SC5-2-u1-X34"},{"t":"체로 거른다","mis":"SC5-2-u1-X18"},{"t":"흡착포를 올린다","mis":"SC5-2-u1-X33"}],"explanation":["소금은 물에 녹아요.","먼저 녹여요.","그다음 걸러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#7','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C13',1,'ox','auto','증발 접시를 옮길 때는 집게를 써요.',ARRAY['SC5-2-u1-X21']::text[],false,'{"seq":7,"concept":"SC5-2-u1-C13","difficulty":1,"kind":"ox","stem":"증발 접시를 옮길 때는 집게를 써요.","answer":"O","reason_options":[{"t":"가열한 접시는 뜨거워 맨손으로 잡으면 데기 때문에","correct":true},{"t":"집게를 쓰면 소금이 더 많이 나오기 때문에","mis":"SC5-2-u1-X21"}],"mis":"SC5-2-u1-X21","explanation":["접시가 뜨거워요.","맨손은 위험해요.","집게를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#8','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C20',1,'sa','auto','버려지는 물건에 아이디어나 디자인을 더해 새로운 가치를 만드는 일을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SC5-2-u1-C20","difficulty":1,"kind":"sa","stem":"버려지는 물건에 아이디어나 디자인을 더해 새로운 가치를 만드는 일을 쓰세요.","answer":["새활용"],"explanation":["버림에서 쓰임으로요.","아이디어를 더해요.","새활용이에요."],"mis":"SC5-2-u1-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#9','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C1',2,'mc','auto','바다반 캠프 일지 ①의 오른쪽 카드에 더 놓을 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u1-X01','SC5-2-u1-X02']::text[],false,'{"seq":9,"concept":"SC5-2-u1-C1","difficulty":2,"kind":"mc","stem":"바다반 캠프 일지 ①의 오른쪽 카드에 더 놓을 수 있는 것은 어느 것인가요?","options":[{"t":"바닷물","correct":true},{"t":"산소","mis":"SC5-2-u1-X01"},{"t":"얼음 조각","mis":"SC5-2-u1-X02"},{"t":"구리 선","mis":"SC5-2-u1-X02"}],"explanation":["바닷물엔 소금이 섞였어요.","물도 있어요.","바닷물이에요."],"asset":{"type":"passage","lines":["캠프 첫날, 물건 카드를 두 갈래로 나누는 놀이를 했다.","왼쪽 — 얼음, 선생님 금반지, 텐트 못","오른쪽 — 바닷가 흙, 탄산음료, 캠프장 공기","모둠장 수아: 「무엇으로 되어 있는지 보고 나눴어.」"],"title":"① 첫날 — 물건 카드 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#10','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C4',2,'mc','auto','바다반 캠프 일지 ④에서 모래 섞인 바닷물을 나눈 목적으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X03','SC5-2-u1-X06']::text[],false,'{"seq":10,"concept":"SC5-2-u1-C4","difficulty":2,"kind":"mc","stem":"바다반 캠프 일지 ④에서 모래 섞인 바닷물을 나눈 목적으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"섞여 있는 바닷물에서 필요한 소금을 얻으려고","correct":true},{"t":"모래를 소금으로 바꾸려고","mis":"SC5-2-u1-X03"},{"t":"바닷물을 더 무겁게 하려고","mis":"SC5-2-u1-X06"},{"t":"바닷물의 양을 늘리려고","mis":"SC5-2-u1-X06"}],"explanation":["바닷물에 소금이 녹아 있어요.","모래도 섞였어요.","소금을 얻으려 했어요."],"asset":{"type":"passage","lines":["모래가 섞인 바닷물을 떠 와 비커에 담았다.","거름 장치로 거르자 거름종이 위에 모래가 남았다.","빠져나간 맑은 액체를 증발 접시에 붓고 약하게 가열했다.","물이 줄어들더니 하얀 알갱이가 남았다."],"title":"④ 둘째 날 오후 — 바닷물 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#11','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C11',2,'mc','auto','바다반 캠프 일지 ②에서 양동이의 모래를 보고 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u1-X11','SC5-2-u1-X03','SC5-2-u1-X10']::text[],false,'{"seq":11,"concept":"SC5-2-u1-C11","difficulty":2,"kind":"mc","stem":"바다반 캠프 일지 ②에서 양동이의 모래를 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"체로 나눈 모래도 여러 알갱이가 섞여 있다","correct":true},{"t":"체로 나눈 모래는 한 가지 물질이다","mis":"SC5-2-u1-X11"},{"t":"모래는 체를 지나며 색이 바뀌었다","mis":"SC5-2-u1-X03"},{"t":"모래와 조개는 같은 크기다","mis":"SC5-2-u1-X10"}],"explanation":["색이 여러 가지예요.","여러 알갱이예요.","여전히 섞여 있어요."],"asset":{"type":"passage","lines":["바닷가 흙을 큰 체에 담아 살살 흔들었다.","고운 모래는 아래 양동이로 빠지고, 작은 조개와 조약돌이 체에 남았다.","양동이의 모래를 돋보기로 보니 색이 여러 가지였다."],"title":"② 둘째 날 아침 — 체로 조개 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#12','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C10',2,'mc','auto','바다반 캠프 일지 ③에서 남은 기름을 하수구에 붓지 않고 따로 모은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X04','SC5-2-u1-X35','SC5-2-u1-X14']::text[],false,'{"seq":12,"concept":"SC5-2-u1-C10","difficulty":2,"kind":"mc","stem":"바다반 캠프 일지 ③에서 남은 기름을 하수구에 붓지 않고 따로 모은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"기름이 물에 섞이지 않고 떠다니며 물을 더럽힐 수 있어서","correct":true},{"t":"기름이 하수구 물에 녹아 없어져서","mis":"SC5-2-u1-X04"},{"t":"기름이 물을 깨끗하게 해서","mis":"SC5-2-u1-X35"},{"t":"기름은 물보다 아래로 가라앉아서","mis":"SC5-2-u1-X14"}],"explanation":["기름은 물에 안 섞여요.","물을 더럽혀요.","따로 모아요."],"asset":{"type":"passage","lines":["점심 미역국 위에 기름이 동동 떠 있었다.","조리사님은 국자로 위의 기름을 떠내고, 주방 종이를 살짝 대었다.","남은 기름은 하수구에 붓지 않고 따로 모았다."],"title":"③ 둘째 날 점심 — 미역국 기름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#13','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C12',2,'mc','auto','바다반 캠프 일지 ④에서 거름 장치를 쓸 때 알맞은 방법은 어느 것인가요?',ARRAY['SC5-2-u1-X23']::text[],false,'{"seq":13,"concept":"SC5-2-u1-C12","difficulty":2,"kind":"mc","stem":"바다반 캠프 일지 ④에서 거름 장치를 쓸 때 알맞은 방법은 어느 것인가요?","options":[{"t":"거름종이를 깔때기에 물을 묻혀 붙이고 깔때기 끝을 비커 옆면에 댄다","correct":true},{"t":"거름종이 없이 깔때기에 바로 붓는다","mis":"SC5-2-u1-X23"},{"t":"혼합물을 한꺼번에 쏟아붓는다","mis":"SC5-2-u1-X23"},{"t":"깔때기 끝을 허공에 띄워 둔다","mis":"SC5-2-u1-X23"}],"explanation":["종이를 잘 붙여요.","옆면에 대요.","튀지 않아요."],"asset":{"type":"passage","lines":["모래가 섞인 바닷물을 떠 와 비커에 담았다.","거름 장치로 거르자 거름종이 위에 모래가 남았다.","빠져나간 맑은 액체를 증발 접시에 붓고 약하게 가열했다.","물이 줄어들더니 하얀 알갱이가 남았다."],"title":"④ 둘째 날 오후 — 바닷물 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#14','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C14',2,'mc','auto','바다반 캠프 일지 ⑤에서 해설사님이 말한 「물을 날려 보내면」을 과학 낱말로 바꾼 것은 어느 것인가요?',ARRAY['SC5-2-u1-X22']::text[],false,'{"seq":14,"concept":"SC5-2-u1-C14","difficulty":2,"kind":"mc","stem":"바다반 캠프 일지 ⑤에서 해설사님이 말한 「물을 날려 보내면」을 과학 낱말로 바꾼 것은 어느 것인가요?","options":[{"t":"물이 증발하면","correct":true},{"t":"물이 걸러지면","mis":"SC5-2-u1-X22"},{"t":"물이 체에 남으면","mis":"SC5-2-u1-X22"},{"t":"물이 흡수되면","mis":"SC5-2-u1-X22"}],"explanation":["물이 공기 중으로 가요.","날아가는 거예요.","증발이에요."],"asset":{"type":"passage","lines":["바닷가 염전에 갔다. 바닷물을 넓고 얕은 바닥에 가두어 두었다.","해설사님: 「햇빛과 바람이 물을 날려 보내면 소금이 남아요.」","바닥 곳곳에 하얀 소금이 모여 있었다."],"title":"⑤ 셋째 날 — 염전 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#15','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C16',2,'mc','auto','바다반 캠프 일지 ⑥의 두 장치에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X27','SC5-2-u1-X25','SC5-2-u1-X26']::text[],false,'{"seq":15,"concept":"SC5-2-u1-C16","difficulty":2,"kind":"mc","stem":"바다반 캠프 일지 ⑥의 두 장치에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 혼합물을 나누어 깨끗한 물과 공기를 얻게 한다","correct":true},{"t":"둘 다 물질의 성질을 바꾸는 장치이다","mis":"SC5-2-u1-X27"},{"t":"혼합물의 분리와는 관계없는 장치이다","mis":"SC5-2-u1-X25"},{"t":"둘 다 쓰레기를 골라 내는 장치이다","mis":"SC5-2-u1-X26"}],"explanation":["하나는 물이에요.","하나는 공기예요.","둘 다 분리 장치예요."],"asset":{"type":"passage","lines":["배를 타고 작은 섬 마을에 갔다. 바다로 둘러싸였지만 마실 물이 모자랐다.","마을에는 바닷물에서 소금 등을 걸러 내는 장치가 있었다.","마을 학교에는 공기 속 먼지를 거르는 장치도 있었다."],"title":"⑥ 셋째 날 오후 — 섬 마을 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#16','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C20',2,'mc','auto','바다반 캠프 일지 ⑧에서 뚜껑 벽화를 만들기 전에 한 일은 어느 것인가요?',ARRAY['SC5-2-u1-X31','SC5-2-u1-X32','SC5-2-u1-X33']::text[],false,'{"seq":16,"concept":"SC5-2-u1-C20","difficulty":2,"kind":"mc","stem":"바다반 캠프 일지 ⑧에서 뚜껑 벽화를 만들기 전에 한 일은 어느 것인가요?","options":[{"t":"뚜껑을 씻어 색깔별로 나누었다","correct":true},{"t":"뚜껑을 녹였다","mis":"SC5-2-u1-X31"},{"t":"뚜껑을 다른 쓰레기와 섞었다","mis":"SC5-2-u1-X32"},{"t":"뚜껑을 체로 걸렀다","mis":"SC5-2-u1-X33"}],"explanation":["먼저 씻었어요.","색깔별로 나눴어요.","나누어 모았어요."],"asset":{"type":"passage","lines":["캠프 동안 모은 페트병 뚜껑을 씻어 색깔별로 나누었다.","뚜껑을 녹이지 않고 그대로 붙여 「바다반」 글자 벽화를 만들었다.","마지막으로 캠프에서 나눈 혼합물을 정리판에 적었다."],"title":"⑧ 마지막 날 — 뚜껑 벽화와 정리판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#17','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C6',3,'mc','auto','바다반 캠프 일지 ②의 체 대신 눈이 조개보다 큰 체를 썼다면 어떻게 되었을까요?',ARRAY['SC5-2-u1-X09','SC5-2-u1-X10','SC5-2-u1-X03']::text[],false,'{"seq":17,"concept":"SC5-2-u1-C6","difficulty":3,"kind":"mc","stem":"바다반 캠프 일지 ②의 체 대신 눈이 조개보다 큰 체를 썼다면 어떻게 되었을까요?","options":[{"t":"모래와 조개가 모두 빠져나가 나뉘지 않았을 것이다","correct":true},{"t":"조개만 체에 남았을 것이다","mis":"SC5-2-u1-X09"},{"t":"모래만 체에 남았을 것이다","mis":"SC5-2-u1-X10"},{"t":"모래가 조개로 바뀌었을 것이다","mis":"SC5-2-u1-X03"}],"explanation":["눈이 너무 커요.","조개도 빠져요.","나뉘지 않아요."],"asset":{"type":"passage","lines":["바닷가 흙을 큰 체에 담아 살살 흔들었다.","고운 모래는 아래 양동이로 빠지고, 작은 조개와 조약돌이 체에 남았다.","양동이의 모래를 돋보기로 보니 색이 여러 가지였다."],"title":"② 둘째 날 아침 — 체로 조개 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#18','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C10',3,'mc','auto','물과 식용유를 나눈 뒤 식용유를 다시 요리에 쓰려고 해요. 가장 알맞은 방법은 어느 것인가요?',ARRAY['SC5-2-u1-X16','SC5-2-u1-X17','SC5-2-u1-X13']::text[],false,'{"seq":18,"concept":"SC5-2-u1-C10","difficulty":3,"kind":"mc","stem":"물과 식용유를 나눈 뒤 식용유를 다시 요리에 쓰려고 해요. 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"스포이트로 위층 식용유를 뽑아 깨끗한 그릇에 옮긴다","correct":true},{"t":"흡착포로 빨아들인 뒤 꼭 짜서 쓴다","mis":"SC5-2-u1-X16"},{"t":"체로 거른다","mis":"SC5-2-u1-X17"},{"t":"세게 저어 섞은 뒤 쓴다","mis":"SC5-2-u1-X13"}],"explanation":["다시 써야 해요.","그대로 옮겨요.","스포이트예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#19','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C12',3,'mc','auto','설탕과 모래가 섞인 혼합물에서 설탕을 얻으려고 해요. 설탕도 물에 녹을 때, 알맞은 차례는 어느 것인가요?',ARRAY['SC5-2-u1-X34','SC5-2-u1-X18','SC5-2-u1-X20']::text[],false,'{"seq":19,"concept":"SC5-2-u1-C12","difficulty":3,"kind":"mc","stem":"설탕과 모래가 섞인 혼합물에서 설탕을 얻으려고 해요. 설탕도 물에 녹을 때, 알맞은 차례는 어느 것인가요?","options":[{"t":"물에 녹이기 → 거름으로 모래 걸러 내기 → 설탕물에서 물 증발시키기","correct":true},{"t":"증발 → 물에 녹이기 → 거름","mis":"SC5-2-u1-X34"},{"t":"체로 거르기 → 끝","mis":"SC5-2-u1-X18"},{"t":"거름 → 물에 녹이기 → 끝","mis":"SC5-2-u1-X20"}],"explanation":["설탕은 물에 녹아요.","모래는 걸러요.","물을 증발시켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#20','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C16',3,'mc','auto','바다반 캠프 일지 ⑥·⑦의 장치들이 모두 지속가능한 삶을 돕는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X27','SC5-2-u1-X25','SC5-2-u1-X35']::text[],false,'{"seq":20,"concept":"SC5-2-u1-C16","difficulty":3,"kind":"mc","stem":"바다반 캠프 일지 ⑥·⑦의 장치들이 모두 지속가능한 삶을 돕는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"깨끗한 물과 공기를 얻고 자원을 다시 써 한정된 자원과 환경을 지키기 때문이다","correct":true},{"t":"물질을 새 물질로 바꾸어 주기 때문이다","mis":"SC5-2-u1-X27"},{"t":"실험실에서만 쓰여 생활과 관계없기 때문이다","mis":"SC5-2-u1-X25"},{"t":"편하기만 하면 되기 때문이다","mis":"SC5-2-u1-X35"}],"explanation":["물·공기를 깨끗이 해요.","자원을 다시 써요.","지속가능한 삶을 도와요."],"asset":{"type":"passage","lines":["캠프 쓰레기를 플라스틱·종이·캔으로 나누어 모았다.","선별장 영상 — 카메라가 달린 장치가 플라스틱·종이·유리를 골라 냈다.","모둠마다 오늘 본 장치 하나를 골라 포스터를 만들어 올렸다."],"title":"⑦ 넷째 날 — 분리배출과 포스터"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#21','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C20',3,'mc','auto','새활용과 혼합물의 분리가 이어지는 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u1-X27','SC5-2-u1-X32','SC5-2-u1-X31']::text[],false,'{"seq":21,"concept":"SC5-2-u1-C20","difficulty":3,"kind":"mc","stem":"새활용과 혼합물의 분리가 이어지는 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"버려진 것들 가운데 쓸 수 있는 재료를 나누어 골라 모아야 새 쓰임을 찾을 수 있다","correct":true},{"t":"새활용은 물질의 성질을 바꾸는 일이다","mis":"SC5-2-u1-X27"},{"t":"새활용과 분리는 아무 관계가 없다","mis":"SC5-2-u1-X32"},{"t":"새활용은 물건을 녹여 섞는 일이다","mis":"SC5-2-u1-X31"}],"explanation":["재료를 나눠 골라요.","그래야 쓸 수 있어요.","분리와 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#22','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C21',3,'blank','auto','혼합물의 분리 정리판에서 ㉠에 들어갈 말은 어느 것인가요?',ARRAY['SC5-2-u1-X33','SC5-2-u1-X08']::text[],false,'{"seq":22,"concept":"SC5-2-u1-C21","difficulty":3,"kind":"blank","stem":"혼합물의 분리 정리판에서 ㉠에 들어갈 말은 어느 것인가요?","options":[{"t":"알갱이의 크기","correct":true},{"t":"물에 녹는 성질","mis":"SC5-2-u1-X33"},{"t":"알갱이의 색깔","mis":"SC5-2-u1-X08"},{"t":"위에 뜨는 성질","mis":"SC5-2-u1-X33"}],"explanation":["모래와 자갈 줄이에요.","체를 써요.","크기 차이예요."],"asset":{"type":"passage","lines":["모래와 자갈 — (㉠) 차이 — 체","물과 기름 — 섞이지 않고 위에 뜸 — (㉡)·흡착포","소금과 모래 — 물에 녹는지 — 거름 → (㉢)"],"title":"혼합물의 분리 정리판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#23','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C4',4,'mc','auto','혼합물을 분리할 수 있어서 우리 삶이 달라진 점을 바다반 캠프 일지로 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SC5-2-u1-X25','SC5-2-u1-X27','SC5-2-u1-X07']::text[],false,'{"seq":23,"concept":"SC5-2-u1-C4","difficulty":4,"kind":"mc","stem":"혼합물을 분리할 수 있어서 우리 삶이 달라진 점을 바다반 캠프 일지로 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"섬 마을은 바닷물로 마실 물을 얻고, 쓰레기는 나누어 자원으로 다시 쓰며, 소금과 깨끗한 공기도 얻는다","correct":true},{"t":"분리는 캠프 놀이일 뿐 삶과는 관계없다","mis":"SC5-2-u1-X25"},{"t":"분리하면 물질이 새로 바뀌어 편해졌을 뿐이다","mis":"SC5-2-u1-X27"},{"t":"주변 물질은 모두 혼합물이라서 분리할 수밖에 없다","mis":"SC5-2-u1-X07"}],"explanation":["마실 물을 얻어요.","자원을 다시 써요.","삶을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#24','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C12',4,'essay','teacher','바다반 캠프 일지 ④를 보고 모래가 섞인 바닷물에서 모래와 소금을 각각 얻은 과정을 차례대로 쓰고, 각 단계에서 이용한 성질을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-2-u1-C12","difficulty":4,"kind":"essay","stem":"바다반 캠프 일지 ④를 보고 모래가 섞인 바닷물에서 모래와 소금을 각각 얻은 과정을 차례대로 쓰고, 각 단계에서 이용한 성질을 쓰세요.","answer_guide":{"answer":"예: 거름 장치로 거르니 물에 녹지 않는 모래는 거름종이 위에 남고, 물에 녹은 소금은 물과 함께 빠져나갔다. 빠져나간 소금물을 증발 접시에 담아 약하게 가열하니 물이 증발하고 소금이 남았다. 소금은 물에 녹고 모래는 녹지 않는 성질을 이용했다.","scoring_points":["거름 단계를 썼는가","증발 단계를 썼는가","이용한 성질을 썼는가"]},"explanation":["거름이 먼저예요.","증발이 나중이에요.","녹는지로 나눠요."],"asset":{"type":"passage","lines":["모래가 섞인 바닷물을 떠 와 비커에 담았다.","거름 장치로 거르자 거름종이 위에 모래가 남았다.","빠져나간 맑은 액체를 증발 접시에 붓고 약하게 가열했다.","물이 줄어들더니 하얀 알갱이가 남았다."],"title":"④ 둘째 날 오후 — 바닷물 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u1_review_d#25','sci',5,2,'u1','','g5_2_sci_u1_review_d','unit_review','SC5-2-u1-C20',4,'essay','teacher','바다반 캠프 일지 ⑧을 보고 뚜껑 벽화가 새활용인 까닭을 쓰고, 벽화를 만들 때 이 단원에서 배운 「나누기」가 어떻게 쓰였는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-2-u1-C20","difficulty":4,"kind":"essay","stem":"바다반 캠프 일지 ⑧을 보고 뚜껑 벽화가 새활용인 까닭을 쓰고, 벽화를 만들 때 이 단원에서 배운 「나누기」가 어떻게 쓰였는지 쓰세요.","answer_guide":{"answer":"예: 뚜껑을 녹이거나 부수지 않고 아이디어를 더해 「바다반」 글자 벽화라는 새 가치를 만들었으므로 새활용이다. 뚜껑을 다른 쓰레기에서 골라 모으고, 씻은 뒤 색깔별로 나누어 모아 원하는 색으로 글자를 꾸몄다.","scoring_points":["새활용인 까닭을 썼는가","골라 모으고 색깔별로 나눈 과정을 썼는가","재활용과의 차이가 드러나는가"]},"explanation":["녹이지 않았어요.","나누어 모았어요.","새 가치를 만들었어요."],"asset":{"type":"passage","lines":["캠프 동안 모은 페트병 뚜껑을 씻어 색깔별로 나누었다.","뚜껑을 녹이지 않고 그대로 붙여 「바다반」 글자 벽화를 만들었다.","마지막으로 캠프에서 나눈 혼합물을 정리판에 적었다."],"title":"⑧ 마지막 날 — 뚜껑 벽화와 정리판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
